# Target 384 rebuilds once after Guardian victory so FE1E mode 3 can replace
# the resident on-foot party actors with the newly mounted Gear actors.  This
# is an internal presentation reload, not a graph edge or additional room.
SAME_FIELD_RELOAD_CONTRACTS = frozenset({(384, 0)})
# The single post-victory rebuild is audited explicitly so an accidental
# pre-battle or second reload cannot hide behind set-based route validation.
SAME_FIELD_RELOAD_COUNTS = {(384, 0): 1}
ROUTE_ENTRY_FIELD = 729
FINAL_ROUTE_PREDECESSOR = 383
# Central Control doubles as a title-selection-only gateway. It is not loaded during
# the playable approach, so its update actor is fresh when the party eventually
# reaches it from the fifth reserve magazine.
BOOTSTRAP_FIELD = ROUTE[-1]
# ATEL operands are byte addresses into the 0x400-word field-variable array.
# Only indices 0x000-0x1FF are copied back to GameState across field loads;
# operand 0x03FE is its final audited persistent word and is normalized at
# GameState offset 0x1D2E by the standalone bootstrap.
LIFT_STATE_VARIABLE = 0x03FC
INTERLOCK_VARIABLE = 0x03FE
AUXILIARY_INTERLOCK_BIT = 0
RAIL_INTERLOCK_BIT = 1
DIRECTIVE_RECORD_BIT = 2
ADDRESS_RECORD_BIT = 3
LAUNCH_AUTHORIZATION_BIT = 4
