STORAGE_ANNEX_CHEST_OPENED_BIT = 14
CRESCENS_STAGED_BIT = 15
# The main 0x03FE progression word is fully allocated.  Optional annex
# treasure therefore uses the adjacent audited persistent scratch word rather
# than aliasing a story, staging, or existing chest bit.
ANNEX_TREASURE_VARIABLE = 0x03FA
ANNEX_TREASURE_A_OPENED_BIT = 0
ANNEX_TREASURE_B_OPENED_BIT = 1
WEST_BULKHEAD_OPENED_BIT = 2
FACILITY_VIDEO_DISK_ACQUIRED_BIT = 3
AUXILIARY_INTERLOCK_MASK = 1 << AUXILIARY_INTERLOCK_BIT
RAIL_INTERLOCK_MASK = 1 << RAIL_INTERLOCK_BIT
DIRECTIVE_RECORD_MASK = 1 << DIRECTIVE_RECORD_BIT
ADDRESS_RECORD_MASK = 1 << ADDRESS_RECORD_BIT
LAUNCH_AUTHORIZATION_MASK = 1 << LAUNCH_AUTHORIZATION_BIT
BOSS_DEFEATED_MASK = 1 << BOSS_DEFEATED_BIT
LAUNCH_COMPLETED_MASK = 1 << LAUNCH_COMPLETED_BIT
CITAN_FINAL_ARRIVAL_MASK = 1 << CITAN_FINAL_ARRIVAL_BIT
ELLY_GEAR_STAGED_MASK = 1 << ELLY_GEAR_STAGED_BIT
# Historical names remain importable for the frozen El-Regulus audits.  New
# Mass Driver code uses the pilot-neutral aliases above because this bit tracks
# Elly's currently assigned Gear, which is Vierge in the active build.
EL_REGULUS_STAGED_BIT = ELLY_GEAR_STAGED_BIT
EL_REGULUS_STAGED_MASK = ELLY_GEAR_STAGED_MASK
HISTORICAL_GHOST_SEEN_MASK = 1 << HISTORICAL_GHOST_SEEN_BIT
SUBWAY_ROBOT_REFLECTION_SEEN_MASK = 1 << SUBWAY_ROBOT_REFLECTION_SEEN_BIT
STORAGE_ANNEX_CHEST_OPENED_MASK = 1 << STORAGE_ANNEX_CHEST_OPENED_BIT
CRESCENS_STAGED_MASK = 1 << CRESCENS_STAGED_BIT
ANNEX_TREASURE_A_OPENED_MASK = 1 << ANNEX_TREASURE_A_OPENED_BIT
ANNEX_TREASURE_B_OPENED_MASK = 1 << ANNEX_TREASURE_B_OPENED_BIT
WEST_BULKHEAD_OPENED_MASK = 1 << WEST_BULKHEAD_OPENED_BIT
FACILITY_VIDEO_DISK_ACQUIRED_MASK = 1 << FACILITY_VIDEO_DISK_ACQUIRED_BIT
# Retail object IDs are one-based; system-menu name entry 48 is Omegasol.
OMEGASOL_ITEM_ID = 49
FIXED_BOSS_CONFIGURATION = 15
NORMAL_BATTLE_MUSIC_ID = 0x14
ZEBOIM_GUARDIAN_FORMATION = bytes.fromhex(
    "10 80 0B 00 00 00 00 00 80 FF FF FF FF FF FF FF "
    "00 FF FF FF FF FF FF FF 00 FF FF FF FF FF FF FF"
)


# 720-729 are the retail game's own unused "debug room" slots (the field-name
# table the decomp project ships ends at 729). ETHOS_DUMMY_TARGETS holds field
# IDs that are real, populated content on CD1 but resolve to allocated 24-byte
# "It's CDMAKE Dummy !" placeholder files at the same field number on CD2.
# Fields 360-372, 375-379, and 382-387 were checked directly at their canonical
# Disc 2 IDs. Fields 380 and 381 contain live Disc 2 scenes and are explicitly
# skipped. Field 375's canonical files 1356/1357 are allocated 24-byte CDMAKE
# placeholders and provide the second sealed stair connector without
# overwriting a live Disc 2 story field. Their natural slots leave field 721
# available for the Lighthouse subway terminus and fields 365-371 available
# for reciprocal one-room annexes. Empty field-730 FAT entries are deliberately
# not used because Xenoiso 0.95 cannot promote them into allocated files.
DEBUG_ROOM_TARGETS = frozenset(range(720, 730))
ETHOS_DUMMY_TARGETS: frozenset[int] = frozenset({360, 361, 362, 363, 364})
SIDE_ROOM_DUMMY_TARGETS: frozenset[int] = frozenset(range(365, 372))
ZEBOIM_DUMMY_TARGETS: frozenset[int] = frozenset({372, 375, 387})
POST_GATE_DUMMY_TARGETS: frozenset[int] = frozenset(
    (*range(376, 380), *range(382, 388))
)
SAFE_ROUTE_TARGETS = (
    DEBUG_ROOM_TARGETS
    | ETHOS_DUMMY_TARGETS
    | SIDE_ROOM_DUMMY_TARGETS
    | ZEBOIM_DUMMY_TARGETS
    | POST_GATE_DUMMY_TARGETS
)


def _variable_edits(
    old_variable: int, new_variable: int, *pcs: int
) -> tuple[VariableEdit, ...]:
    return tuple(VariableEdit(pc, old_variable, new_variable) for pc in pcs)


