def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _dialog(block_id: int, *, dialogue_flags: int = 0) -> bytes:
    # Mode 3 is screen-positioned and is the retail form used by invisible
    # field directors.  Our automatic room introductions are owned by those
    # directors, so mode 0's actor projection can leave an otherwise valid
    # window off-screen.  The trailing byte supplies native mode-3 flags; bit
    # 0 keeps WAIT_DIALOG alive when the owning director itself is hidden.
    if not isinstance(dialogue_flags, int) or not 0 <= dialogue_flags <= 0xFF:
        raise DungeonBuildError(
            f"Dialogue flags outside 0..255: {dialogue_flags}"
        )
    return b"\xF5" + _u16(block_id) + bytes((dialogue_flags,))


def _screen_dialogue_calls(body: bytes) -> tuple[tuple[int, int], ...]:
    """Return every four-byte F5 call in one audited generated routine."""

    return tuple(
        (struct.unpack_from("<H", body, offset + 1)[0], body[offset + 3])
        for offset, opcode in enumerate(body[:-3])
        if opcode == 0xF5
    )


def _choice_dialog(block_id: int) -> bytes:
    """Open the retail actor-owned dialogue form used by every choice menu."""

    return b"\xD2" + _u16(block_id) + b"\x00"


def _wait(frames: int = 1) -> bytes:
    if not isinstance(frames, int) or not 1 <= frames <= 0x7FFF:
        raise DungeonBuildError(f"ATEL wait outside 1..32767 frames: {frames}")
    return b"\x26" + _immediate(frames)


def _yield_tick() -> bytes:
    """Encode retail WAIT 0: yield once, then resume on the next VM tick."""

    # OP_WAIT decrements after testing its counter.  WAIT 1 therefore spans
    # two scheduler ticks; retail animation loops use WAIT 0 when they need a
    # true one-tick yield.
    return b"\x26" + _immediate(0)


def _wait_for_pad_release(mask: int, pc: int) -> bytes:
    """Yield until every requested pad bit is physically released."""

    if not isinstance(mask, int) or not 1 <= mask <= 0xFFFF:
        raise DungeonBuildError(f"Pad mask outside 1..65535: {mask}")
    if not isinstance(pc, int) or not 0 <= pc <= 0xFFFF - 11:
        raise DungeonBuildError(f"Pad-release PC outside encodable range: {pc}")
    released_pc = pc + 11
    return (
        # Opcode 0x31 tests the current frame's held-button word. Opcode 0x32
        # tests the persistent accumulated-input mask instead.
        b"\x31"
        + _u16(mask)
        + _u16(released_pc)
        + _wait()
        + _jump(pc)
    )


def _dialogue_sequence(
    block_ids: Iterable[int],
    *,
    dialogue_flags: int = 0,
) -> bytes:
    """Show each dialogue in its own input frame.

    WAIT_DIALOG can finish while the interaction button edge is still live.
    Without a VM yield, the same press immediately dismisses every following
    window in a DIALOG/WAIT_DIALOG sequence.  A one-frame ATEL wait between
    windows prevents that retail input edge from bleeding into the next line.
    """

    ids = tuple(block_ids)
    routine = bytearray()
    for index, block_id in enumerate(ids):
        routine.extend(_dialog(block_id, dialogue_flags=dialogue_flags))
        routine.append(0x9C)
        if index + 1 < len(ids):
            routine.extend(_wait())
    return bytes(routine)


def _actor_dialog_reset_body() -> bytes:
    """Clear stale actor dialogue geometry and any inherited portrait."""

    # F4 01 resets this actor's dialogue window state. Character 0xFC resolves
    # to the engine's -1/no-portrait sentinel; character 0 would select Fei.
    return b"\xF4\x01\xFE\x0D\xFC\x80"


def _automatic_dialogue_body(
    block_ids: Iterable[int],
    *,
    routine_pc: int,
    reset_actor_dialog_state: bool = False,
    dialogue_flags: int = 0,
) -> bytes:
    """Build an input-safe, director-owned automatic dialogue scene."""

    # Clear only the persistent accumulated-input mask, lock control, then
    # sample the separate live held-button word until Cross is released. One
    # additional frame after release drains the old press edge before DIALOG.
    prefix = (
        (_actor_dialog_reset_body() if reset_actor_dialog_state else b"")
        + b"\x33\xFE\x54"
    )
    release_pc = routine_pc + len(prefix)
    return (
        prefix
        + _wait_for_pad_release(PAD_MASK_CROSS, release_pc)
        + _wait()
        + _dialogue_sequence(block_ids, dialogue_flags=dialogue_flags)
        + (_actor_dialog_reset_body() if reset_actor_dialog_state else b"")
        + b"\xFE\x53"
    )


def _facility_video_image_transaction(
    image_file_id: int,
    *,
    sound_id: int,
    dialogue_id: int | None = None,
) -> bytes:
    """Load one still into the retail slideshow plane, then caption it."""

    if not 0 <= image_file_id <= 0x7FFF:
        raise DungeonBuildError("Facility-video field file ID is outside s15")
    if not 0 <= sound_id <= 0x7FFF:
        raise DungeonBuildError("Facility-video sound ID is outside s15")
    transaction = (
        b"\xFE\x77\x00"
        + b"\xFE\x77\x01"
        + _u16(image_file_id)
        # Retail fields 617/618 load their captioned stills at (320,256).
        # The plane samples those two 16-bpp pages while ordinary F5 text
        # continues to use its disjoint 4-bpp scratch slots at x=768.
        + b"\x40\x01\x00\x01\x00\x00\xF0"
        + b"\xFE\x77\x02"
        + _wait(15)
        + b"\x74"
        + _immediate(sound_id)
        + _facility_video_screen_fade_body(0)
    )
    if dialogue_id is not None:
        if not 0 <= dialogue_id <= 0xFFFF:
            raise DungeonBuildError(
                "Facility-video dialogue ID is outside u16"
            )
        # Retail fixed-top mode 1 plus flag 0x40 produces ordinary Xenogears
        # glyphs with no portrait, fill, or border.  Unlike FE9D, the model
        # plane remains visible while WAIT_DIALOG advances every caption page.
        transaction += b"\xF5" + _u16(dialogue_id) + b"\x53\x9C"
    transaction += _facility_video_screen_fade_body(0xFF)
    return transaction


def _facility_video_screen_fade_body(
    value: int,
    frames: int = FACILITY_VIDEO_FRAME_FADE_FRAMES,
) -> bytes:
    """Fade the retail subtractive screen grade to one neutral RGB value."""

    if not 0 <= value <= 0xFF or not 1 <= frames <= 0x7FFF:
        raise DungeonBuildError("Facility-video screen fade is outside range")
    return (
        b"\xF1"
        + _immediate(2)
        + _immediate(value) * 3
        + _immediate(frames)
        + _wait(frames)
    )


def _facility_video_screen_camera_body() -> bytes:
    """Cut to a remote head-on view that fills the native 320x224 frame."""

    return _historical_camera_shot_body(
        HistoricalCameraShot(
            target=FACILITY_VIDEO_SCREEN_CAMERA_TARGET,
            eye=FACILITY_VIDEO_SCREEN_CAMERA_EYE,
            transition_frames=0,
            dialogues=(0,),
        ),
        enter_camera_mode=True,
    )


def _facility_video_screen_init_body() -> bytes:
    """Initialize retail's model actor while retaining its header-hidden state."""

    # This is field 617 entity 25's exact model-plane initializer. The 0x20
    # bit in header flags 0x02B0 keeps it invisible until OP24 during playback.
    return b"\xBC\xD0\x00\x80\x00\x80\x00\x80\x00\x80\x01\x80\x2A\x00"


def _facility_video_playback_body(
    *,
    routine_pc: int,
    startup_dialogue: int,
    clip_dialogues: Sequence[int],
    image_file_ids: Sequence[int],
    screen_entity: int,
    sound_id: int,
) -> bytes:
    """Build a seven-still player with retail simultaneous native captions."""

    if len(clip_dialogues) != 7 or len(image_file_ids) != 7:
        raise DungeonBuildError("Facility video requires exactly seven captioned clips")
    if len(set(image_file_ids)) != 7:
        raise DungeonBuildError("Facility-video image file IDs must be unique")
    if screen_entity != FACILITY_VIDEO_SCREEN_ENTITY:
        raise DungeonBuildError("Facility-video screen entity changed from its audit")

    # Keep control locked from the initial disk message through native screen
    # teardown. The button-release drain prevents the interaction press from
    # immediately closing the first message.
    prefix = _actor_dialog_reset_body() + b"\x33\xFE\x54"
    release_pc = routine_pc + len(prefix)
    result = bytearray(
        prefix
        + _wait_for_pad_release(PAD_MASK_CROSS, release_pc)
        + _wait()
        + _dialogue_sequence((startup_dialogue,))
    )
    # Keep field 394's projector sounds and screen preparation, but cut under
    # black to the remote model plane instead of entering FE9D's 16-bpp screen
    # mode. FE9D owns the same VRAM where normal dialogue glyphs are rendered.
    result.extend(
        b"\x74"
        + _immediate(sound_id)
        + _wait(25)
        + b"\x74"
        + _immediate(sound_id)
        + _wait(12)
        + b"\x74"
        + _immediate(sound_id)
        + _wait(13)
        + b"\xFE\x65\x46\x80\x01\x80"
        + _facility_video_screen_fade_body(0xFF, 50)
        + _facility_video_screen_camera_body()
        + b"\x24"
        + bytes((screen_entity,))
    )
    for image_file_id, dialogue_id in zip(
        image_file_ids,
        clip_dialogues,
        strict=True,
    ):
        result.extend(
            _facility_video_image_transaction(
                image_file_id,
                sound_id=sound_id,
                dialogue_id=dialogue_id,
            )
        )
    # Every transaction ends under black. Hide the remote plane, return to the
    # live party-tracked camera, then reveal the untouched room and controls.
    result.extend(
        b"\x25"
        + bytes((screen_entity,))
        + _historical_camera_release_body()
        + b"\xFE\x65\x00\x80\x01\x80"
        + _facility_video_screen_fade_body(0, 50)
        + _actor_dialog_reset_body()
        + b"\xFE\x53"
    )
    return bytes(result)


def _facility_video_terminal_action(
    video_event: DefenseArchiveVideoEvent,
    routine_pc: int,
) -> bytes:
    """Gate native playback on the real Video Disk inventory item."""

    routine = _RoutineBuilder(routine_pc)
    routine.jump_if_item_absent(video_event.inventory_item_id, "missing_disk")
    # Give the player an immediate, explicit choice.  WAIT_DIALOG writes the
    # absolute selected line to variable 0x0014; with the title on line zero,
    # Insert is line one and Cancel is line two.
    routine.emit(b"\x33\xFE\x54")
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.emit(_wait())
    routine.emit(_choice_dialog(video_event.insert_prompt_dialogue))
    routine.emit(b"\xA9\x12\x9C")
    routine.jump_if_not_equal(0x0014, 1, "decline")
    routine.emit(
        _facility_video_playback_body(
            routine_pc=routine.pc,
            startup_dialogue=video_event.startup_dialogue,
            clip_dialogues=video_event.clip_dialogues,
            image_file_ids=video_event.image_file_ids,
            screen_entity=video_event.screen_entity,
            sound_id=video_event.sound_id,
        )
        + b"\x00"
    )

    routine.label("decline")
    routine.emit(_actor_dialog_reset_body() + b"\xFE\x53\x00")

    routine.label("missing_disk")
    routine.emit(
        _automatic_dialogue_body(
            (video_event.missing_dialogue,),
            routine_pc=routine.pc,
            reset_actor_dialog_state=True,
        )
        + b"\x00"
    )
    return routine.finish()


def _facility_video_disk_init_body(
    video_event: DefenseArchiveVideoEvent,
    routine_pc: int,
) -> bytes:
    """Keep the native disk apparatus available for repeat inspection."""

    disk_x, disk_z = video_event.disk_position
    return _static_door_controller_init(
        disk_x,
        disk_z,
        requires_facing=video_event.controller_requires_facing,
        interaction_half_width=video_event.interaction_half_width,
    )


def _facility_video_disk_action_body(
    video_event: DefenseArchiveVideoEvent,
    routine_pc: int,
) -> bytes:
    """Offer one real disk, then leave the apparatus inspectable."""

    routine = _RoutineBuilder(routine_pc)
    routine.emit(_actor_dialog_reset_body())
    routine.jump_if_item_absent(video_event.inventory_item_id, "pickup")
    routine.emit(
        _automatic_dialogue_body(
            (video_event.damaged_dialogue,),
            routine_pc=routine.pc,
            reset_actor_dialog_state=True,
        )
        + b"\x00"
    )

    # Lock and drain the interaction edge, let Elly examine the media, and ask
    # before changing inventory.  The choice marker begins on absolute line 1,
    # so Take is 1 and Leave is 2 in variable 0x0014.
    routine.label("pickup")
    routine.emit(b"\x33\xFE\x54")
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.emit(_wait())
    routine.emit(_dialogue_sequence((video_event.pickup_dialogue,)))
    routine.emit(_wait())
    routine.emit(_choice_dialog(video_event.pickup_choice_dialogue))
    routine.emit(b"\xA9\x12\x9C")
    routine.jump_if_not_equal(0x0014, 1, "decline")

    # Checking for the item after opcode 8C makes a full-inventory failure
    # retryable and also upgrades v115 saves whose old persistence bit was set
    # without an actual inventory award.
    routine.emit(b"\x8C" + _immediate(video_event.inventory_item_id))
    routine.jump_if_item_absent(video_event.inventory_item_id, "inventory_full")
    routine.emit(
        b"\x74"
        + _immediate(FACILITY_VIDEO_ITEM_ACQUIRED_SOUND_ID)
        + _dialogue_sequence((video_event.pickup_receipt_dialogue,))
        + _set_var_bit(
            video_event.state_variable,
            video_event.acquired_bit,
        )
        + _actor_dialog_reset_body()
        + b"\xFE\x53\x00"
    )

    routine.label("decline")
    routine.emit(_actor_dialog_reset_body() + b"\xFE\x53\x00")

    routine.label("inventory_full")
    routine.emit(
        _dialogue_sequence((video_event.inventory_full_dialogue,))
        + _actor_dialog_reset_body()
        + b"\xFE\x53\x00"
    )
    return routine.finish()


def _change_field(field: int, parameter: int = 0) -> bytes:
    return b"\x98" + _immediate(field) + _immediate(parameter)


def _play_music(music_id: int) -> bytes:
    """Select one retail field/battle music sequence."""

    return b"\x75" + _immediate(music_id)


def _fixed_battle(
    configuration: int,
    next_field: int = 0x7FFF,
    next_parameter: int = 0,
) -> bytes:
    """Start one fixed formation through retail extended opcode FE84.

    The second word is an audited, ignored operand in the US Disc 2 field
    overlay. ``0x7FFF`` is the retail same-field return sentinel and is
    required for Elly's same-field El-Regulus encounter.
    """

    return (
        b"\xFE\x84"
        + _immediate(configuration)
        + _immediate(0)
        + _immediate(next_field)
        + _immediate(next_parameter)
    )


def _custom_field_transition(
    field: int,
    parameter: int = 0,
    mode: int = 0,
    fade: int = 32,
) -> bytes:
    return (
        b"\x12"
        + _immediate(field)
        + _immediate(parameter)
        + _immediate(mode)
        + _immediate(fade)
    )


def _move_player(x: int, z: int) -> bytes:
    """Use the retail blocking player-waypoint opcode."""

    return b"\xFE\x68" + _s16(x) + _s16(z) + b"\xC0"


def _party_actor_waypoint_script(
    x: int,
    z: int,
    max_steps: int = 120,
) -> bytes:
    """Encode a bounded walk followed by its exact-position snap."""

    if not isinstance(max_steps, int) or not 1 <= max_steps <= 0x7FFF:
        raise DungeonBuildError(
            f"Party waypoint step bound outside 1..32767: {max_steps}"
        )
    position = _s16(x) + _s16(z)
    return (
        b"\x4B"
        + position
        + b"\xC0"
        + _immediate(max_steps)
        + b"\x19"
        + position
        + b"\xC0\x00"
    )


def _delayed_door_waypoint_script(x: int, z: int) -> bytes:
    """Wait for the door model, then cross and hard-snap within a fixed time."""

    return (
        _wait(DOOR_ANIMATION_GRACE_FRAMES)
        + _party_actor_waypoint_script(
            x,
            z,
            DOOR_MOVEMENT_MAX_STEPS,
        )
    )


def _worldmap(initial_position: int = 21, mode: int = 1) -> bytes:
    """Enter field-map 0x400 in the retail playable-world-map mode."""

    if not isinstance(initial_position, int) or not 0 <= initial_position <= 0x0FFF:
        raise DungeonBuildError(
            f"World-map initial position outside 0..4095: {initial_position}"
        )
    if not isinstance(mode, int) or not 0 <= mode <= 0xFF:
        raise DungeonBuildError(f"World-map mode outside 0..255: {mode}")
    return b"\x56\x00\x04" + _u16(initial_position) + b"\xFF\xFF" + bytes((mode, 0, 0xF0))


def _jump(pc: int) -> bytes:
    return b"\x01" + _u16(pc)


def _jump_if_not_equal(variable: int, value: int, target: int) -> bytes:
    """Branch unless a signed field variable equals a literal value."""

    if not 0 <= value <= 0x7FFF:
        raise DungeonBuildError(
            f"ATEL signed comparison literal outside 0..32767: {value}"
        )
    # Control 0x40 selects variable/literal operands and equality. JUMP_IF
    # falls through when the comparison succeeds and branches when it fails.
    return b"\x02" + _u16(variable) + _u16(value) + b"\x40" + _u16(target)


def _jump_if_bit_clear(variable: int, mask: int, target: int) -> bytes:
    """Branch when none of the requested bits are set."""

    if not 1 <= mask <= 0xFFFF:
        raise DungeonBuildError(f"ATEL bit mask outside 1..65535: {mask}")
    return b"\x02" + _u16(variable) + _u16(mask) + b"\x46" + _u16(target)


def _increment_variable(variable: int) -> bytes:
    if not 0 <= variable <= 0x07FE or variable & 1:
        raise DungeonBuildError(f"ATEL increment variable is invalid: {variable}")
    return b"\x3C" + _u16(variable)


def _decrement_variable(variable: int) -> bytes:
    if not 0 <= variable <= 0x07FE or variable & 1:
        raise DungeonBuildError(f"ATEL decrement variable is invalid: {variable}")
    return b"\x3D" + _u16(variable)


def _shift_variable_right(variable: int, bits: int) -> bytes:
    if not 0 <= variable <= 0x07FE or variable & 1:
        raise DungeonBuildError(f"ATEL shift variable is invalid: {variable}")
    if not 0 <= bits <= 15:
        raise DungeonBuildError(f"ATEL shift count is outside 0..15: {bits}")
    return b"\x42" + _u16(variable) + _immediate(bits)


def _random_modulo_variable(variable: int, maximum: int) -> bytes:
    """Set one variable to retail RNG output in the inclusive range 0..max."""

    if not 0 <= variable <= 0x07FE or variable & 1:
        raise DungeonBuildError(f"ATEL random variable is invalid: {variable}")
    if not 0 <= maximum <= 0x7FFF:
        raise DungeonBuildError(f"ATEL random maximum is invalid: {maximum}")
    # Opcode A8 scales Xenogears' 15-bit RNG by (maximum + 1).
    return b"\xA8" + _u16(variable) + _immediate(maximum)


@dataclass(frozen=True)
class _AtelVariableOperand:
    address: int

    def __post_init__(self) -> None:
        if not 0 <= self.address <= 0x07FE or self.address & 1:
            raise DungeonBuildError(
                f"ATEL variable operand is invalid: {self.address}"
            )


def _vram_move(
    source_x: int | _AtelVariableOperand,
    source_y: int | _AtelVariableOperand,
    width: int | _AtelVariableOperand,
    height: int | _AtelVariableOperand,
    destination_x: int | _AtelVariableOperand,
    destination_y: int | _AtelVariableOperand,
) -> bytes:
    """Encode retail E1 ``MoveImage`` with six independent literal flags."""

    operands = (
        source_x,
        source_y,
        width,
        height,
        destination_x,
        destination_y,
    )
    literal_bits = (0x80, 0x40, 0x20, 0x10, 0x08, 0x04)
    encoded = bytearray(b"\xE1")
    flags = 0
    for operand, bit in zip(operands, literal_bits, strict=True):
        if isinstance(operand, _AtelVariableOperand):
            encoded.extend(_u16(operand.address))
        else:
            encoded.extend(_s16(operand))
            flags |= bit
    encoded.append(flags)
    return bytes(encoded)


def _call(routine_pc: int) -> bytes:
    if not isinstance(routine_pc, int) or not 0 <= routine_pc <= 0xFFFF:
        raise DungeonBuildError(f"ATEL call target is invalid: {routine_pc}")
    return b"\x05" + _u16(routine_pc)


class _RoutineBuilder:
    """Small absolute-PC label patcher for appended ATEL routines."""

    def __init__(self, base: int):
        if not isinstance(base, int) or not 0 <= base <= 0xFFFF:
            raise DungeonBuildError(f"Routine base outside 0..65535: {base}")
        self.base = base
        self.data = bytearray()
        self.labels: dict[str, int] = {}
        self.fixups: list[tuple[int, str]] = []

    @property
    def pc(self) -> int:
        return self.base + len(self.data)

    def emit(self, encoded: bytes) -> None:
        self.data.extend(encoded)

    def label(self, name: str) -> None:
        if name in self.labels:
            raise DungeonBuildError(f"Duplicate routine label: {name}")
        self.labels[name] = len(self.data)

    def jump(self, label: str) -> None:
        self.data.append(0x01)
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_bit_clear(self, variable: int, mask: int, label: str) -> None:
        if not 1 <= mask <= 0xFFFF:
            raise DungeonBuildError(f"ATEL bit mask outside 1..65535: {mask}")
        self.data.extend(b"\x02" + _u16(variable) + _u16(mask) + b"\x46")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_item_absent(self, item_id: int, label: str) -> None:
        """Branch when an ordinary inventory item is absent."""

        if not 1 <= item_id <= 0x7FFF:
            raise DungeonBuildError(
                f"ATEL ordinary-item ID outside 1..32767: {item_id}"
            )
        self.data.extend(b"\x8B" + _immediate(item_id))
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_not_equal(self, variable: int, value: int, label: str) -> None:
        if not 0 <= value <= 0x7FFF:
            raise DungeonBuildError(
                f"ATEL comparison literal outside 0..32767: {value}"
            )
        self.data.extend(b"\x02" + _u16(variable) + _u16(value) + b"\x40")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_equal(self, variable: int, value: int, label: str) -> None:
        """Branch when one variable equals a signed literal."""

        if not -0x8000 <= value <= 0x7FFF:
            raise DungeonBuildError(
                f"ATEL comparison literal outside s16: {value}"
            )
        # Control 1 falls through for A != B, so its encoded false target is
        # taken precisely when A == B.
        self.data.extend(b"\x02" + _u16(variable) + _s16(value) + b"\x41")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_variables_not_equal(
        self,
        first: int,
        second: int,
        label: str,
    ) -> None:
        """Branch when two field variables differ."""

        self.data.extend(b"\x02" + _u16(first) + _u16(second) + b"\x00")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_variables_equal(
        self,
        first: int,
        second: int,
        label: str,
    ) -> None:
        """Branch when two field variables are equal."""

        self.data.extend(b"\x02" + _u16(first) + _u16(second) + b"\x01")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_not_signed_greater_than(
        self,
        first: int,
        second: int,
        label: str,
    ) -> None:
        """Branch when signed variable ``first`` is not greater than ``second``."""

        # Control 2 falls through only while B < A.  Its false target is
        # therefore the required A <= B branch.
        self.data.extend(b"\x02" + _u16(first) + _u16(second) + b"\x02")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_signed_less_than(
        self,
        variable: int,
        value: int,
        label: str,
    ) -> None:
        """Branch while a signed field variable remains below a literal."""

        if not -0x8000 <= value <= 0x7FFF:
            raise DungeonBuildError(
                f"ATEL signed comparison literal outside s16: {value}"
            )
        # Control 0x44 falls through for A >= B and takes the encoded branch
        # otherwise.  This is the same comparison form used by the checked
        # field-673 north/south edge polls.
        self.data.extend(b"\x02" + _u16(variable) + _s16(value) + b"\x44")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_signed_greater_or_equal(
        self,
        variable: int,
        value: int,
        label: str,
    ) -> None:
        """Branch while a signed field variable is at least a literal."""

        if not -0x8000 <= value <= 0x7FFF:
            raise DungeonBuildError(
                f"ATEL signed comparison literal outside s16: {value}"
            )
        # Control 3 falls through for A < B and takes its false target for
        # A >= B.
        self.data.extend(b"\x02" + _u16(variable) + _s16(value) + b"\x43")
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def jump_if_pad_not_pressed(self, mask: int, label: str) -> None:
        """Branch when none of the requested live pad bits is held."""

        if not 1 <= mask <= 0xFFFF:
            raise DungeonBuildError(f"ATEL pad mask outside 1..65535: {mask}")
        self.data.extend(b"\x31" + _u16(mask))
        self.fixups.append((len(self.data), label))
        self.data.extend(b"\x00\x00")

    def finish(self) -> bytes:
        result = bytearray(self.data)
        for offset, label in self.fixups:
            if label not in self.labels:
                raise DungeonBuildError(f"Undefined routine label: {label}")
            target = self.base + self.labels[label]
            if not 0 <= target <= 0xFFFF:
                raise DungeonBuildError(
                    f"Routine label {label} is outside 16-bit ATEL space"
                )
            result[offset : offset + 2] = _u16(target)
        return bytes(result)


def _nuke_atlas_vram_rect(rect: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
    x, y, width, height = rect
    return (
        NUKE_ATLAS_VRAM_X + x,
        NUKE_ATLAS_VRAM_Y + y,
        width,
        height,
    )


def _nuke_load_tim_body(file_id: int, destination: tuple[int, int]) -> bytes:
    """Load one field-linked TIM at an explicit retail FE77 destination."""

    destination_x, destination_y = destination
    if not 0 <= file_id <= 0x7FFF:
        raise DungeonBuildError(f"Nuke field file ID is invalid: {file_id}")
    if not all(-0x8000 <= value <= 0x7FFF for value in destination):
        raise DungeonBuildError(f"Nuke TIM destination is invalid: {destination}")
    return (
        b"\xFE\x77\x00"
        + b"\xFE\x77\x01"
        + _u16(file_id)
        + _s16(destination_x)
        + _s16(destination_y)
        + b"\x00\x00\xF0"
        + b"\xFE\x77\x02"
        + _wait(15)
    )


def _nuke_fill_screen_rect_body(
    rect: tuple[int, int, int, int],
    tile_name: str,
) -> bytes:
    """Tile one screen-space rectangle from the safe RGB555 Nuke atlas."""

    x, y, width, height = rect
    if (
        x < 0
        or y < 0
        or width <= 0
        or height <= 0
        or x + width > 320
        or y + height > 224
    ):
        raise DungeonBuildError(f"Nuke fill rectangle is invalid: {rect}")
    if tile_name not in NUKE_TILE_RECTS:
        raise DungeonBuildError(f"Nuke fill tile is unknown: {tile_name!r}")
    tile_x, tile_y, tile_width, tile_height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS[tile_name]
    )
    destination_vram_x = NUKE_LIVE_VRAM_ORIGIN[0] + x
    destination_vram_y = NUKE_LIVE_VRAM_ORIGIN[1] + y
    seeded_width = min(width, tile_width)
    seeded_height = min(height, tile_height)
    output = bytearray(
        _vram_move(
            tile_x,
            tile_y,
            seeded_width,
            seeded_height,
            destination_vram_x,
            destination_vram_y,
        )
    )
    # Grow the seed geometrically from the already-written live texture.  All
    # copies are adjacent rather than overlapping, and preserve the tile's
    # exact pixel phase while using O(log width + log height) E1 operations.
    filled_width = seeded_width
    while filled_width < width:
        copy_width = min(filled_width, width - filled_width)
        output.extend(
            _vram_move(
                destination_vram_x,
                destination_vram_y,
                copy_width,
                seeded_height,
                destination_vram_x + filled_width,
                destination_vram_y,
            )
        )
        filled_width += copy_width
    filled_height = seeded_height
    while filled_height < height:
        copy_height = min(filled_height, height - filled_height)
        output.extend(
            _vram_move(
                destination_vram_x,
                destination_vram_y,
                width,
                copy_height,
                destination_vram_x,
                destination_vram_y + filled_height,
            )
        )
        filled_height += copy_height
    return bytes(output)


def _nuke_static_text_body(text_value: str, x: int, y: int) -> bytes:
    """Draw compact atlas text at screen coordinates with retail MoveImage."""

    if not isinstance(text_value, str) or not text_value:
        raise DungeonBuildError("Nuke static text cannot be empty")
    origin_x = x
    cursor_x = x
    cursor_y = y
    output = bytearray()
    for character in text_value.upper():
        if character == "\n":
            cursor_x = origin_x
            cursor_y += NUKE_FONT_CELL_HEIGHT
            continue
        if character == " ":
            cursor_x += NUKE_FONT_CELL_WIDTH
            continue
        if character not in NUKE_GLYPH_RECTS:
            raise DungeonBuildError(
                f"Nuke atlas has no glyph for {character!r}"
            )
        source_x, source_y, width, height = _nuke_atlas_vram_rect(
            NUKE_GLYPH_RECTS[character]
        )
        if (
            cursor_x < 0
            or cursor_y < 0
            or cursor_x + width > 320
            or cursor_y + height > 224
        ):
            raise DungeonBuildError(
                f"Nuke text {text_value!r} leaves the 320x224 screen"
            )
        output.extend(
            _vram_move(
                source_x,
                source_y,
                width,
                height,
                NUKE_LIVE_VRAM_ORIGIN[0] + cursor_x,
                NUKE_LIVE_VRAM_ORIGIN[1] + cursor_y,
            )
        )
        cursor_x += NUKE_FONT_CELL_WIDTH
    return bytes(output)


def _nuke_centered_text_body(text_value: str, y: int) -> bytes:
    """Draw one Nuke label centered on the native 320-pixel display."""

    if not isinstance(text_value, str) or not text_value or "\n" in text_value:
        raise DungeonBuildError("Centered Nuke text must be one nonempty line")
    width = len(text_value) * NUKE_FONT_CELL_WIDTH - 1
    if width > 320:
        raise DungeonBuildError(
            f"Centered Nuke text is wider than the display: {text_value!r}"
        )
    return _nuke_static_text_body(text_value, (320 - width) // 2, y)


def _nuke_cell_to_vram_body() -> bytes:
    """Convert ``NUKE_DRAW_CELL_VARIABLE`` into live VRAM coordinates."""

    return (
        _copy_variable(NUKE_ROW_VARIABLE, NUKE_DRAW_CELL_VARIABLE)
        + _variable_math(0xDF, NUKE_ROW_VARIABLE, NUKE_GRID_WIDTH)
        + _copy_variable(NUKE_COLUMN_VARIABLE, NUKE_DRAW_CELL_VARIABLE)
        + _copy_variable(NUKE_TEMP_0_VARIABLE, NUKE_ROW_VARIABLE)
        + _variable_math(0xDE, NUKE_TEMP_0_VARIABLE, NUKE_GRID_WIDTH)
        + _variable_math(
            0x39,
            NUKE_COLUMN_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(NUKE_DESTINATION_X_VARIABLE, NUKE_COLUMN_VARIABLE)
        + _variable_math(0xDE, NUKE_DESTINATION_X_VARIABLE, NUKE_TILE_SIZE)
        + _variable_math(
            0x38,
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0] + NUKE_GRID_SCREEN_ORIGIN[0],
        )
        + _copy_variable(NUKE_DESTINATION_Y_VARIABLE, NUKE_ROW_VARIABLE)
        + _variable_math(0xDE, NUKE_DESTINATION_Y_VARIABLE, NUKE_TILE_SIZE)
        + _variable_math(
            0x38,
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + NUKE_GRID_SCREEN_ORIGIN[1],
        )
        + b"\x0D"
    )


def _nuke_draw_cell_body(cell_to_vram_pc: int) -> bytes:
    """Draw the tile selected by source-X/Y variables into one logical cell."""

    variable = _AtelVariableOperand
    return (
        _call(cell_to_vram_pc)
        + _vram_move(
            variable(NUKE_SOURCE_X_VARIABLE),
            variable(NUKE_SOURCE_Y_VARIABLE),
            NUKE_TILE_SIZE,
            NUKE_TILE_SIZE,
            variable(NUKE_DESTINATION_X_VARIABLE),
            variable(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _nuke_erase_cell_body(cell_to_vram_pc: int) -> bytes:
    """Restore one logical cell from the atlas' seamless CRT-grain tile."""

    variable = _AtelVariableOperand
    source_x, source_y, _width, _height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS[NUKE_BOARD_BACKGROUND_TILE_NAME]
    )
    return (
        _call(cell_to_vram_pc)
        + _vram_move(
            source_x,
            source_y,
            NUKE_TILE_SIZE,
            NUKE_TILE_SIZE,
            variable(NUKE_DESTINATION_X_VARIABLE),
            variable(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _nuke_draw_digit_body() -> bytes:
    """Draw ``NUKE_DIGIT_VARIABLE`` at the destination-X/Y variables."""

    digit_origin_x, digit_origin_y = NUKE_FONT_DIGIT_ORIGIN
    return (
        _copy_variable(NUKE_SOURCE_X_VARIABLE, NUKE_DIGIT_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_SOURCE_X_VARIABLE,
            NUKE_FONT_CELL_WIDTH,
        )
        + _variable_math(
            0x38,
            NUKE_SOURCE_X_VARIABLE,
            NUKE_ATLAS_VRAM_X + digit_origin_x,
        )
        + _vram_move(
            _AtelVariableOperand(NUKE_SOURCE_X_VARIABLE),
            NUKE_ATLAS_VRAM_Y + digit_origin_y,
            NUKE_GLYPH_WIDTH,
            NUKE_GLYPH_HEIGHT,
            _AtelVariableOperand(NUKE_DESTINATION_X_VARIABLE),
            _AtelVariableOperand(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _nuke_draw_letter_body() -> bytes:
    """Draw zero-based A..Z ``NUKE_DIGIT_VARIABLE`` at destination X/Y."""

    alphabet_origin_x, alphabet_origin_y = NUKE_FONT_ALPHABET_ORIGIN
    return (
        _copy_variable(NUKE_ROW_VARIABLE, NUKE_DIGIT_VARIABLE)
        + _variable_math(
            0xDF,
            NUKE_ROW_VARIABLE,
            NUKE_FONT_ALPHABET_COLUMNS,
        )
        + _copy_variable(NUKE_COLUMN_VARIABLE, NUKE_DIGIT_VARIABLE)
        + _copy_variable(NUKE_TEMP_0_VARIABLE, NUKE_ROW_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            NUKE_FONT_ALPHABET_COLUMNS,
        )
        + _variable_math(
            0x39,
            NUKE_COLUMN_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(NUKE_SOURCE_X_VARIABLE, NUKE_COLUMN_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_SOURCE_X_VARIABLE,
            NUKE_FONT_CELL_WIDTH,
        )
        + _variable_math(
            0x38,
            NUKE_SOURCE_X_VARIABLE,
            NUKE_ATLAS_VRAM_X + alphabet_origin_x,
        )
        + _copy_variable(NUKE_SOURCE_Y_VARIABLE, NUKE_ROW_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_SOURCE_Y_VARIABLE,
            NUKE_FONT_CELL_HEIGHT,
        )
        + _variable_math(
            0x38,
            NUKE_SOURCE_Y_VARIABLE,
            NUKE_ATLAS_VRAM_Y + alphabet_origin_y,
        )
        + _vram_move(
            _AtelVariableOperand(NUKE_SOURCE_X_VARIABLE),
            _AtelVariableOperand(NUKE_SOURCE_Y_VARIABLE),
            NUKE_GLYPH_WIDTH,
            NUKE_GLYPH_HEIGHT,
            _AtelVariableOperand(NUKE_DESTINATION_X_VARIABLE),
            _AtelVariableOperand(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _nuke_draw_number_body(
    value_variable: int,
    digits: int,
    screen_x: int,
    screen_y: int,
    digit_pc: int,
) -> bytes:
    """Draw a fixed-width, leading-zero decimal number into the HUD."""

    if not 1 <= digits <= 5:
        raise DungeonBuildError(f"Nuke number width is invalid: {digits}")
    result = bytearray(
        _copy_variable(NUKE_REMAINDER_VARIABLE, value_variable)
        + _set_variable_s16(
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0] + screen_x,
        )
        + _set_variable_s16(
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + screen_y,
        )
    )
    for power in range(digits - 1, -1, -1):
        divisor = 10**power
        result.extend(_copy_variable(NUKE_DIGIT_VARIABLE, NUKE_REMAINDER_VARIABLE))
        if divisor != 1:
            result.extend(_variable_math(0xDF, NUKE_DIGIT_VARIABLE, divisor))
        result.extend(_call(digit_pc))
        if divisor != 1:
            result.extend(_copy_variable(NUKE_TEMP_0_VARIABLE, NUKE_DIGIT_VARIABLE))
            result.extend(_variable_math(0xDE, NUKE_TEMP_0_VARIABLE, divisor))
            result.extend(
                _variable_math(
                    0x39,
                    NUKE_REMAINDER_VARIABLE,
                    NUKE_TEMP_0_VARIABLE,
                    operand_is_variable=True,
                )
            )
        result.extend(
            _variable_math(
                0x38,
                NUKE_DESTINATION_X_VARIABLE,
                NUKE_FONT_CELL_WIDTH,
            )
        )
    return bytes(result)


def _missile_draw_score_body(
    score_units_variable: int,
    screen_x: int,
    screen_y: int,
    digit_pc: int,
) -> bytes:
    """Draw an exact five-point-unit score as five decimal point digits.

    Runtime and persistence keep Missile Command scores in units of five so
    the authentic 99,995-point range remains positive in a signed ATEL word.
    For units ``u``, ``u * 5`` is ``floor(u / 2) * 10 + (u & 1) * 5``; drawing
    four quotient digits plus the final zero/five avoids a signed overflow.
    """

    return (
        _copy_variable(NUKE_TEMP_2_VARIABLE, score_units_variable)
        + _variable_math(0x3E, NUKE_TEMP_2_VARIABLE, 1)
        + _variable_math(0xDE, NUKE_TEMP_2_VARIABLE, MISSILE_SCORE_UNIT)
        + _copy_variable(NUKE_TEMP_1_VARIABLE, score_units_variable)
        + _variable_math(0xDF, NUKE_TEMP_1_VARIABLE, 2)
        + _nuke_draw_number_body(
            NUKE_TEMP_1_VARIABLE,
            4,
            screen_x,
            screen_y,
            digit_pc,
        )
        + _copy_variable(NUKE_DIGIT_VARIABLE, NUKE_TEMP_2_VARIABLE)
        + _set_variable_s16(
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0]
            + screen_x
            + 4 * NUKE_FONT_CELL_WIDTH,
        )
        + _set_variable_s16(
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + screen_y,
        )
        + _call(digit_pc)
    )


def _nuke_unpack_initials_body(nuke_game: DefenseArchiveNukeGame) -> bytes:
    return (
        _copy_variable(
            NUKE_NAME_0_VARIABLE,
            nuke_game.initials_packed_variable,
        )
        + _variable_math(0x3E, NUKE_NAME_0_VARIABLE, 0x1F)
        + _copy_variable(
            NUKE_NAME_1_VARIABLE,
            nuke_game.initials_packed_variable,
        )
        + _shift_variable_right(NUKE_NAME_1_VARIABLE, 5)
        + _variable_math(0x3E, NUKE_NAME_1_VARIABLE, 0x1F)
        + _copy_variable(
            NUKE_NAME_2_VARIABLE,
            nuke_game.initials_packed_variable,
        )
        + _shift_variable_right(NUKE_NAME_2_VARIABLE, 10)
        + _variable_math(0x3E, NUKE_NAME_2_VARIABLE, 0x1F)
        + _copy_variable(
            NUKE_NAME_3_VARIABLE,
            nuke_game.initial_fourth_variable,
        )
        + _variable_math(0x3E, NUKE_NAME_3_VARIABLE, 0x1F)
    )


def _arcade_unpack_records_body(
    nuke_game: DefenseArchiveNukeGame,
    missile_game: DefenseArchiveMissileCommandGame,
) -> bytes:
    """Expand V2's split five-point Missile score and both best-level words."""

    return (
        _copy_variable(
            nuke_game.best_level_variable,
            nuke_game.best_level_packed_variable,
        )
        + _variable_math(0x3E, nuke_game.best_level_variable, 0x1F)
        + _copy_variable(
            missile_game.best_wave_variable,
            nuke_game.best_level_packed_variable,
        )
        + _shift_variable_right(missile_game.best_wave_variable, 5)
        + _variable_math(0x3E, missile_game.best_wave_variable, 0x1F)
        + _copy_variable(
            missile_game.high_score_variable,
            nuke_game.initial_fourth_variable,
        )
        + _shift_variable_right(missile_game.high_score_variable, 5)
        + _variable_math(0x3E, missile_game.high_score_variable, 0x03FF)
        + _copy_variable(NUKE_TEMP_0_VARIABLE, nuke_game.best_level_packed_variable)
        + _shift_variable_right(NUKE_TEMP_0_VARIABLE, 10)
        + _variable_math(0x3E, NUKE_TEMP_0_VARIABLE, 0x1F)
        + _variable_math(0xDE, NUKE_TEMP_0_VARIABLE, 1 << 10)
        + _variable_math(
            0x38,
            missile_game.high_score_variable,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
    )


def _arcade_unpack_v1_records_body(
    nuke_game: DefenseArchiveNukeGame,
    missile_game: DefenseArchiveMissileCommandGame,
) -> bytes:
    """Decode v129/v130's score-in-tens directly into five-point units."""

    return (
        _copy_variable(
            nuke_game.best_level_variable,
            nuke_game.best_level_packed_variable,
        )
        + _variable_math(0x3E, nuke_game.best_level_variable, 0x1F)
        + _copy_variable(
            missile_game.best_wave_variable,
            nuke_game.best_level_packed_variable,
        )
        + _shift_variable_right(missile_game.best_wave_variable, 5)
        + _variable_math(0x3E, missile_game.best_wave_variable, 0x1F)
        + _copy_variable(
            missile_game.high_score_variable,
            nuke_game.initial_fourth_variable,
        )
        + _shift_variable_right(missile_game.high_score_variable, 5)
        + _variable_math(0x3E, missile_game.high_score_variable, 0x03FF)
        + _variable_math(0xDE, missile_game.high_score_variable, 2)
    )


def _nuke_draw_initials_body(letter_pc: int, screen_x: int, screen_y: int) -> bytes:
    result = bytearray(
        _set_variable_s16(
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0] + screen_x,
        )
        + _set_variable_s16(
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + screen_y,
        )
    )
    for variable in (
        NUKE_NAME_0_VARIABLE,
        NUKE_NAME_1_VARIABLE,
        NUKE_NAME_2_VARIABLE,
        NUKE_NAME_3_VARIABLE,
    ):
        result.extend(_copy_variable(NUKE_DIGIT_VARIABLE, variable))
        result.extend(_call(letter_pc))
        result.extend(
            _variable_math(
                0x38,
                NUKE_DESTINATION_X_VARIABLE,
                NUKE_FONT_CELL_WIDTH,
            )
        )
    return bytes(result)


def _nuke_hud_body(
    nuke_game: DefenseArchiveNukeGame,
    digit_pc: int,
    _letter_pc: int,
) -> bytes:
    """Refresh a two-row score, level, record, and target-progress HUD."""

    return (
        _nuke_fill_screen_rect_body(
            NUKE_HUD_SCREEN_RECT,
            NUKE_PANEL_BACKGROUND_TILE_NAME,
        )
        + _nuke_static_text_body("SCORE", 78, 18)
        + _nuke_draw_number_body(
            NUKE_SCORE_VARIABLE,
            5,
            108,
            18,
            digit_pc,
        )
        + _nuke_static_text_body("BEST", 174, 18)
        + _nuke_draw_number_body(
            nuke_game.high_score_variable,
            5,
            199,
            18,
            digit_pc,
        )
        + _nuke_static_text_body("LEVEL", 78, 27)
        + _nuke_draw_number_body(
            NUKE_LEVEL_VARIABLE,
            2,
            108,
            27,
            digit_pc,
        )
        + _nuke_static_text_body("TARGET", 174, 27)
        + _nuke_draw_number_body(
            NUKE_LEVEL_TARGETS_VARIABLE,
            1,
            208,
            27,
            digit_pc,
        )
        + _nuke_static_text_body("/5", 214, 27)
        + b"\x0D"
    )


def _nuke_set_tile_source_body(tile_name: str) -> bytes:
    """Select one atlas tile for the dynamic cell-drawing helper."""

    if tile_name not in NUKE_TILE_RECTS:
        raise DungeonBuildError(f"Nuke atlas tile is unknown: {tile_name!r}")
    source_x, source_y, width, height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS[tile_name]
    )
    if width != NUKE_TILE_SIZE or height != NUKE_TILE_SIZE:
        raise DungeonBuildError(
            f"Nuke gameplay tile {tile_name!r} is not {NUKE_TILE_SIZE}x"
            f"{NUKE_TILE_SIZE}"
        )
    return _set_variable_s16(
        NUKE_SOURCE_X_VARIABLE,
        source_x,
    ) + _set_variable_s16(NUKE_SOURCE_Y_VARIABLE, source_y)


def _nuke_draw_variable_cell_body(
    cell_variable: int,
    tile_name: str,
    draw_cell_pc: int,
) -> bytes:
    return (
        _copy_variable(NUKE_DRAW_CELL_VARIABLE, cell_variable)
        + _nuke_set_tile_source_body(tile_name)
        + _call(draw_cell_pc)
    )


def _nuke_board_fill_body() -> bytes:
    result = bytearray()
    for frame_rect in NUKE_BOARD_FRAME_SCREEN_RECTS:
        result.extend(_nuke_fill_screen_rect_body(frame_rect, "frame"))
    result.extend(
        _nuke_fill_screen_rect_body(
            (
                NUKE_GRID_SCREEN_ORIGIN[0],
                NUKE_GRID_SCREEN_ORIGIN[1],
                NUKE_GRID_WIDTH * NUKE_TILE_SIZE,
                NUKE_GRID_HEIGHT * NUKE_TILE_SIZE,
            ),
            NUKE_BOARD_BACKGROUND_TILE_NAME,
        )
    )
    result.extend(b"\x0D")
    return bytes(result)


def _nuke_panel_fill_body() -> bytes:
    return (
        _nuke_fill_screen_rect_body(
            NUKE_MESSAGE_FRAME_SCREEN_RECT,
            "frame",
        )
        + _nuke_fill_screen_rect_body(
            NUKE_MESSAGE_SCREEN_RECT,
            NUKE_PANEL_BACKGROUND_TILE_NAME,
        )
        + b"\x0D"
    )


def _nuke_spawn_target_body(base: int, draw_cell_pc: int) -> bytes:
    """Choose and draw a target on a cell not occupied by the active Nuke."""

    routine = _RoutineBuilder(base)
    routine.label("retry")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _random_modulo_variable(
            NUKE_TARGET_CELL_VARIABLE,
            NUKE_GRID_CELLS - 1,
        )
    )
    for index, tail_variable in enumerate(NUKE_TAIL_VARIABLES):
        routine.jump_if_signed_less_than(
            NUKE_LENGTH_VARIABLE,
            index + 1,
            "accept",
        )
        routine.jump_if_variables_equal(
            NUKE_TARGET_CELL_VARIABLE,
            tail_variable,
            "occupied",
        )
    routine.label("accept")
    routine.emit(
        _nuke_draw_variable_cell_body(
            NUKE_TARGET_CELL_VARIABLE,
            "target",
            draw_cell_pc,
        )
        + b"\x0D"
    )
    routine.label("occupied")
    # A one-tick yield makes even an adversarial RNG sequence unable to trip
    # the engine's absolute 1024-opcode per-frame guard without adding a
    # second idle tick before the next boosted retry.
    routine.emit(_yield_tick())
    routine.jump("retry")
    return routine.finish()


def _nuke_setup_round_body(
    base: int,
    *,
    board_fill_pc: int,
    hud_pc: int,
    draw_cell_pc: int,
    spawn_target_pc: int,
) -> bytes:
    """Reset deterministic round state and draw the complete initial frame."""

    routine = _RoutineBuilder(base)
    routine.emit(b"\xC6" * NUKE_VM_CYCLE_BOOSTERS)
    routine.emit(
        _set_variable_s16(NUKE_ACTIVE_VARIABLE, 1)
        + _set_variable_s16(NUKE_OUTCOME_VARIABLE, 0)
        + _set_variable_s16(NUKE_SCORE_VARIABLE, 0)
        + _set_variable_s16(NUKE_LEVEL_VARIABLE, 1)
        + _set_variable_s16(NUKE_LENGTH_VARIABLE, NUKE_INITIAL_LENGTH)
        + _set_variable_s16(
            NUKE_DIRECTION_VARIABLE,
            NUKE_INITIAL_DIRECTION,
        )
        + _set_variable_s16(
            NUKE_QUEUED_DIRECTION_VARIABLE,
            4,
        )
        + _set_variable_s16(
            NUKE_HEAD_CELL_VARIABLE,
            NUKE_INITIAL_HEAD_CELL,
        )
        + _set_variable_s16(
            NUKE_TICK_DELAY_VARIABLE,
            NUKE_INITIAL_TICK_DELAY,
        )
        + _set_variable_s16(
            NUKE_TICK_VARIABLE,
            NUKE_INITIAL_TICK_DELAY,
        )
        + _set_variable_s16(NUKE_LEVEL_TARGETS_VARIABLE, 0)
    )
    for tail_variable in NUKE_TAIL_VARIABLES:
        routine.emit(_set_variable_s16(tail_variable, -1))
    for index in range(NUKE_INITIAL_LENGTH):
        routine.emit(
            _set_variable_s16(
                NUKE_TAIL_VARIABLES[index],
                NUKE_INITIAL_HEAD_CELL - index,
            )
        )
    routine.emit(_call(board_fill_pc) + _call(hud_pc))
    # Draw far-to-near so the immediate exhaust plume is brightest.
    routine.emit(
        _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[3],
            "trail_dim",
            draw_cell_pc,
        )
        + _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[2],
            "trail_dim",
            draw_cell_pc,
        )
        + _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[1],
            "trail_bright",
            draw_cell_pc,
        )
        + _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[0],
            "head_right",
            draw_cell_pc,
        )
        + _call(spawn_target_pc)
        + b"\x0D"
    )
    return routine.finish()


def _nuke_name_draw_body(
    *,
    panel_fill_pc: int,
    letter_pc: int,
) -> bytes:
    """Render the four-letter high-score editor from transient name words."""

    cursor_x, cursor_y, cursor_width, cursor_height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS["cursor"]
    )
    result = bytearray(
        _call(panel_fill_pc)
        + _nuke_centered_text_body("NEW HIGH SCORE", 48)
        + _nuke_centered_text_body("ENTER 4 LETTER NAME", 59)
        + _copy_variable(
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_NAME_POSITION_VARIABLE,
        )
        + _variable_math(0xDE, NUKE_DESTINATION_X_VARIABLE, 12)
        + _variable_math(
            0x38,
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0] + 139,
        )
        + _set_variable_s16(
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + 76,
        )
        + _vram_move(
            cursor_x,
            cursor_y,
            cursor_width,
            cursor_height,
            _AtelVariableOperand(NUKE_DESTINATION_X_VARIABLE),
            _AtelVariableOperand(NUKE_DESTINATION_Y_VARIABLE),
        )
    )
    for index, name_variable in enumerate(
        (
            NUKE_NAME_0_VARIABLE,
            NUKE_NAME_1_VARIABLE,
            NUKE_NAME_2_VARIABLE,
            NUKE_NAME_3_VARIABLE,
        )
    ):
        result.extend(
            _copy_variable(NUKE_DIGIT_VARIABLE, name_variable)
            + _set_variable_s16(
                NUKE_DESTINATION_X_VARIABLE,
                NUKE_LIVE_VRAM_ORIGIN[0] + 140 + index * 12,
            )
            + _set_variable_s16(
                NUKE_DESTINATION_Y_VARIABLE,
                NUKE_LIVE_VRAM_ORIGIN[1] + 76,
            )
            + _call(letter_pc)
        )
    result.extend(
        _nuke_centered_text_body("UP/DOWN CHANGE", 91)
        + _nuke_centered_text_body("LEFT/RIGHT MOVE", 100)
        + _nuke_centered_text_body("CROSS NEXT / SAVE", 109)
        + _nuke_centered_text_body("CIRCLE BACK", 118)
        + b"\x0D"
    )
    return bytes(result)


def _nuke_pack_initials_body(nuke_game: DefenseArchiveNukeGame) -> bytes:
    return (
        _copy_variable(NUKE_TEMP_0_VARIABLE, NUKE_NAME_0_VARIABLE)
        + _copy_variable(NUKE_TEMP_1_VARIABLE, NUKE_NAME_1_VARIABLE)
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, 1 << 5)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(NUKE_TEMP_1_VARIABLE, NUKE_NAME_2_VARIABLE)
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, 1 << 10)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(
            nuke_game.initials_packed_variable,
            NUKE_TEMP_0_VARIABLE,
        )
        + _copy_variable(
            NUKE_TEMP_0_VARIABLE,
            nuke_game.initial_fourth_variable,
        )
        + _variable_math(0x3E, NUKE_TEMP_0_VARIABLE, -32)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_NAME_3_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(nuke_game.initial_fourth_variable, NUKE_TEMP_0_VARIABLE)
    )


def _nuke_pack_best_level_body(nuke_game: DefenseArchiveNukeGame) -> bytes:
    """Persist Nuke's low-five-bit level without touching Missile's wave."""

    return (
        _copy_variable(
            NUKE_TEMP_0_VARIABLE,
            nuke_game.best_level_packed_variable,
        )
        + _variable_math(0x3E, NUKE_TEMP_0_VARIABLE, -32)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            nuke_game.best_level_variable,
            operand_is_variable=True,
        )
        + _copy_variable(
            nuke_game.best_level_packed_variable,
            NUKE_TEMP_0_VARIABLE,
        )
    )


def _missile_pack_records_body(
    nuke_game: DefenseArchiveNukeGame,
    missile_game: DefenseArchiveMissileCommandGame,
) -> bytes:
    """Persist an exact five-point score across the two arcade-owned words."""

    return (
        _copy_variable(
            NUKE_TEMP_0_VARIABLE,
            nuke_game.initial_fourth_variable,
        )
        + _variable_math(0x3E, NUKE_TEMP_0_VARIABLE, 0x1F)
        + _copy_variable(
            NUKE_TEMP_1_VARIABLE,
            missile_game.high_score_variable,
        )
        + _variable_math(0x3E, NUKE_TEMP_1_VARIABLE, 0x03FF)
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, 32)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(nuke_game.initial_fourth_variable, NUKE_TEMP_0_VARIABLE)
        + _copy_variable(
            NUKE_TEMP_0_VARIABLE,
            nuke_game.best_level_packed_variable,
        )
        + _variable_math(0x3E, NUKE_TEMP_0_VARIABLE, 0x1F)
        + _copy_variable(
            NUKE_TEMP_1_VARIABLE,
            missile_game.best_wave_variable,
        )
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, 32)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(
            NUKE_TEMP_1_VARIABLE,
            missile_game.high_score_variable,
        )
        + _shift_variable_right(NUKE_TEMP_1_VARIABLE, 10)
        + _variable_math(0x3E, NUKE_TEMP_1_VARIABLE, 0x1F)
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, 1 << 10)
        + _variable_math(
            0x38,
            NUKE_TEMP_0_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(
            nuke_game.best_level_packed_variable,
            NUKE_TEMP_0_VARIABLE,
        )
        + _set_variable_s16(nuke_game.signature_variable, NUKE_SIGNATURE)
    )


def _missile_xy_to_cell_body(x_variable: int, y_variable: int) -> bytes:
    """Store one Missile Command grid coordinate in the shared draw word."""

    return (
        _copy_variable(NUKE_DRAW_CELL_VARIABLE, y_variable)
        + _variable_math(0xDE, NUKE_DRAW_CELL_VARIABLE, NUKE_GRID_WIDTH)
        + _variable_math(
            0x38,
            NUKE_DRAW_CELL_VARIABLE,
            x_variable,
            operand_is_variable=True,
        )
    )


def _missile_draw_offset_body(
    explosion_cell_variable: int,
    offset: int,
    tile_name: str,
    draw_cell_pc: int,
) -> bytes:
    result = bytearray(
        _copy_variable(NUKE_DRAW_CELL_VARIABLE, explosion_cell_variable)
    )
    if offset:
        result.extend(_variable_math(0x38, NUKE_DRAW_CELL_VARIABLE, offset))
    result.extend(_nuke_set_tile_source_body(tile_name) + _call(draw_cell_pc))
    return bytes(result)


def _missile_erase_offset_body(
    explosion_cell_variable: int,
    offset: int,
    erase_cell_pc: int,
) -> bytes:
    result = bytearray(
        _copy_variable(NUKE_DRAW_CELL_VARIABLE, explosion_cell_variable)
    )
    if offset:
        result.extend(_variable_math(0x38, NUKE_DRAW_CELL_VARIABLE, offset))
    result.extend(_call(erase_cell_pc))
    return bytes(result)


def _missile_hud_body(
    missile_game: DefenseArchiveMissileCommandGame,
    digit_pc: int,
) -> bytes:
    """Draw score, record, wave, surviving cities, and center-base stock."""

    return (
        _nuke_fill_screen_rect_body(
            NUKE_HUD_SCREEN_RECT,
            NUKE_PANEL_BACKGROUND_TILE_NAME,
        )
        + _nuke_static_text_body("SCORE", 78, 18)
        + _missile_draw_score_body(
            MISSILE_SCORE_VARIABLE,
            108,
            18,
            digit_pc,
        )
        + _nuke_static_text_body("BEST", 174, 18)
        + _missile_draw_score_body(
            missile_game.high_score_variable,
            199,
            18,
            digit_pc,
        )
        + _nuke_static_text_body("WAVE", 78, 27)
        + _nuke_draw_number_body(
            MISSILE_WAVE_VARIABLE,
            2,
            103,
            27,
            digit_pc,
        )
        + _nuke_static_text_body("CITY", 119, 27)
        + _nuke_draw_number_body(
            MISSILE_CITIES_VARIABLE,
            1,
            144,
            27,
            digit_pc,
        )
        + _nuke_static_text_body("MISSILES", 156, 27)
        + _nuke_draw_number_body(
            MISSILE_AMMO_VARIABLE,
            2,
            196,
            27,
            digit_pc,
        )
        + b"\x0D"
    )


def _missile_draw_terrain_body(
    base: int,
    *,
    draw_cell_pc: int,
) -> bytes:
    """Render six persistent cities and the single center missile base."""

    routine = _RoutineBuilder(base)
    for index, column in enumerate(MISSILE_CITY_COLUMNS):
        ruin_label = f"city_{index}_ruin"
        done_label = f"city_{index}_done"
        routine.jump_if_bit_clear(
            MISSILE_CITY_MASK_VARIABLE,
            1 << index,
            ruin_label,
        )
        routine.emit(
            _set_variable_s16(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_GROUND_ROW * NUKE_GRID_WIDTH + column,
            )
            + _nuke_set_tile_source_body("city")
            + _call(draw_cell_pc)
        )
        routine.jump(done_label)
        routine.label(ruin_label)
        routine.emit(
            _set_variable_s16(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_GROUND_ROW * NUKE_GRID_WIDTH + column,
            )
            + _nuke_set_tile_source_body("city_ruin")
            + _call(draw_cell_pc)
        )
        routine.label(done_label)

    for index, (column, ammo_variable) in enumerate(
        zip(
            MISSILE_BATTERY_COLUMNS,
            MISSILE_BATTERY_AMMO_VARIABLES,
            strict=True,
        )
    ):
        empty_label = f"battery_{index}_empty"
        done_label = f"battery_{index}_done"
        routine.jump_if_equal(ammo_variable, 0, empty_label)
        routine.emit(
            _set_variable_s16(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_GROUND_ROW * NUKE_GRID_WIDTH + column,
            )
            + _nuke_set_tile_source_body("battery")
            + _call(draw_cell_pc)
        )
        routine.jump(done_label)
        routine.label(empty_label)
        routine.emit(
            _set_variable_s16(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_GROUND_ROW * NUKE_GRID_WIDTH + column,
            )
            + _nuke_set_tile_source_body("battery_empty")
            + _call(draw_cell_pc)
        )
        routine.label(done_label)
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_setup_wave_body(
    base: int,
    *,
    board_fill_pc: int,
    missile_hud_pc: int,
    draw_cell_pc: int,
) -> bytes:
    """Reset bounded wave objects while retaining score, cities, and wave."""

    routine = _RoutineBuilder(base)
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _set_variable_s16(MISSILE_AMMO_VARIABLE, MISSILE_INITIAL_AMMO)
        + _set_variable_s16(
            MISSILE_BATTERY_AMMO_VARIABLES[0],
            MISSILE_BATTERY_AMMO,
        )
        + b"".join(
            _set_variable_s16(variable, 0)
            for variable in MISSILE_FIRE_LATCH_VARIABLES
        )
        + _set_variable_s16(
            MISSILE_CURSOR_CELL_VARIABLE,
            MISSILE_INITIAL_CURSOR_CELL,
        )
        + _set_variable_s16(MISSILE_CURSOR_DELAY_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PLAYER_DIRTY_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_SPAWN_TIMER_VARIABLE,
            MISSILE_INITIAL_SPAWN_TIMER,
        )
        + _set_variable_s16(MISSILE_SPAWNED_VARIABLE, 0)
        + _set_variable_s16(MISSILE_ACTIVE_ENEMIES_VARIABLE, 0)
        + _set_variable_s16(MISSILE_WAVE_CITY_LOSSES_VARIABLE, 0)
        + _set_variable_s16(MISSILE_BONUS_AWARDED_VARIABLE, 0)
        + _copy_variable(
            MISSILE_SCORE_MULTIPLIER_VARIABLE,
            MISSILE_WAVE_VARIABLE,
        )
        + _variable_math(0x38, MISSILE_SCORE_MULTIPLIER_VARIABLE, 1)
        + _variable_math(0xDF, MISSILE_SCORE_MULTIPLIER_VARIABLE, 2)
        + _set_variable_s16(
            MISSILE_ENEMY_DELAY_VARIABLE,
            MISSILE_INITIAL_ENEMY_DELAY,
        )
    )
    routine.jump_if_signed_less_than(
        MISSILE_SCORE_MULTIPLIER_VARIABLE,
        7,
        "score_multiplier_ready",
    )
    routine.emit(_set_variable_s16(MISSILE_SCORE_MULTIPLIER_VARIABLE, 6))
    routine.label("score_multiplier_ready")

    # Rev-3's ordinary-missile quota gives the embedded game its recognizable
    # alternating pressure curve instead of the old five-to-fourteen ramp.
    for wave in range(1, len(MISSILE_WAVE_QUOTAS)):
        routine.jump_if_equal(
            MISSILE_WAVE_VARIABLE,
            wave,
            f"wave_quota_{wave}",
        )
    routine.emit(
        _set_variable_s16(
            MISSILE_WAVE_QUOTA_VARIABLE,
            MISSILE_WAVE_QUOTAS[-1],
        )
    )
    routine.jump("wave_quota_ready")
    for wave, quota in enumerate(MISSILE_WAVE_QUOTAS[:-1], start=1):
        routine.label(f"wave_quota_{wave}")
        routine.emit(_set_variable_s16(MISSILE_WAVE_QUOTA_VARIABLE, quota))
        routine.jump("wave_quota_ready")
    routine.label("wave_quota_ready")
    routine.jump_if_signed_less_than(
        MISSILE_WAVE_VARIABLE,
        MISSILE_ENEMY_FAST_WAVE,
        "enemy_delay_ready",
    )
    routine.emit(
        _set_variable_s16(
            MISSILE_ENEMY_DELAY_VARIABLE,
            MISSILE_MINIMUM_ENEMY_DELAY,
        )
    )
    routine.label("enemy_delay_ready")
    routine.emit(
        _copy_variable(
            MISSILE_ENEMY_TICK_VARIABLE,
            MISSILE_ENEMY_DELAY_VARIABLE,
        )
    )
    for variables in zip(
        MISSILE_ENEMY_ACTIVE_VARIABLES,
        MISSILE_ENEMY_START_X_VARIABLES,
        MISSILE_ENEMY_X_VARIABLES,
        MISSILE_ENEMY_Y_VARIABLES,
        MISSILE_ENEMY_TARGET_X_VARIABLES,
        MISSILE_ENEMY_TARGET_INDEX_VARIABLES,
        strict=True,
    ):
        for variable in variables:
            routine.emit(_set_variable_s16(variable, 0))
    for x_variables, y_variables in zip(
        MISSILE_ENEMY_TRAIL_X_VARIABLES,
        MISSILE_ENEMY_TRAIL_Y_VARIABLES,
        strict=True,
    ):
        for x_variable, y_variable in zip(
            x_variables,
            y_variables,
            strict=True,
        ):
            routine.emit(
                _set_variable_s16(x_variable, MISSILE_TRAIL_EMPTY)
                + _set_variable_s16(y_variable, MISSILE_TRAIL_EMPTY)
            )
    for variables in zip(
        MISSILE_INTERCEPTOR_ACTIVE_VARIABLES,
        MISSILE_INTERCEPTOR_X_VARIABLES,
        MISSILE_INTERCEPTOR_Y_VARIABLES,
        MISSILE_INTERCEPTOR_TARGET_X_VARIABLES,
        MISSILE_INTERCEPTOR_TARGET_Y_VARIABLES,
        MISSILE_INTERCEPTOR_STEP_VARIABLES,
        MISSILE_INTERCEPTOR_TOTAL_VARIABLES,
        MISSILE_INTERCEPTOR_TICK_VARIABLES,
        MISSILE_EXPLOSION_PHASE_VARIABLES,
        MISSILE_EXPLOSION_TICK_VARIABLES,
        MISSILE_EXPLOSION_CELL_VARIABLES,
        strict=True,
    ):
        for variable in variables:
            routine.emit(_set_variable_s16(variable, 0))
    for variables in MISSILE_TRAIL_CELL_VARIABLES:
        for variable in variables:
            routine.emit(
                _set_variable_s16(variable, MISSILE_TRAIL_EMPTY)
            )
    routine.emit(
        _set_variable_s16(MISSILE_TRAIL_DIRTY_VARIABLE, 0)
        + _set_variable_s16(MISSILE_MODE_REQUEST_VARIABLE, MISSILE_MODE_STOPPED)
        + _set_variable_s16(MISSILE_RUN_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 0)
        + _set_variable_s16(MISSILE_MODE_ACK_VARIABLE, MISSILE_MODE_STOPPED)
        + _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0)
        + _set_variable_s16(MISSILE_WAVE_COMPLETE_VARIABLE, 0)
        + _set_variable_s16(MISSILE_CURSOR_COLUMN_VARIABLE, 14)
        + _set_variable_s16(MISSILE_CURSOR_ROW_VARIABLE, 7)
        + _set_variable_s16(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_TRAIL_EMPTY,
        )
        + _set_variable_s16(MISSILE_INTERCEPTOR_OLD_DIRTY_VARIABLE, 0)
        + _set_variable_s16(MISSILE_TRAIL_CLEAR_VARIABLE, 0)
    )
    for variable in (
        *MISSILE_BLAST_PHASE_SNAPSHOT_VARIABLES,
        *MISSILE_INTERCEPTOR_OLD_X_VARIABLES,
        *MISSILE_INTERCEPTOR_OLD_Y_VARIABLES,
        *MISSILE_BLAST_GRID_X_VARIABLES,
        *MISSILE_BLAST_GRID_Y_VARIABLES,
    ):
        routine.emit(_set_variable_s16(variable, 0))
    for variable in MISSILE_TRAIL_DIRTY_CELL_VARIABLES:
        routine.emit(_set_variable_s16(variable, MISSILE_TRAIL_EMPTY))
    for variables in zip(
        MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES,
        MISSILE_CHAIN_EXPLOSION_TICK_VARIABLES,
        MISSILE_CHAIN_EXPLOSION_CELL_VARIABLES,
        MISSILE_CHAIN_EXPLOSION_X_VARIABLES,
        MISSILE_CHAIN_EXPLOSION_Y_VARIABLES,
        strict=True,
    ):
        for variable in variables:
            routine.emit(_set_variable_s16(variable, 0))
    routine.emit(
        _call(board_fill_pc)
        + _call(missile_hud_pc)
        + _nuke_draw_variable_cell_body(
            MISSILE_CURSOR_CELL_VARIABLE,
            "cursor",
            draw_cell_pc,
        )
        + b"\x0D"
    )
    return routine.finish()


def _missile_setup_game_body() -> bytes:
    return (
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _set_variable_s16(MISSILE_ACTIVE_VARIABLE, 1)
        + _set_variable_s16(MISSILE_OUTCOME_VARIABLE, 0)
        + _set_variable_s16(MISSILE_SCORE_VARIABLE, 0)
        + _set_variable_s16(MISSILE_WAVE_VARIABLE, 1)
        + _set_variable_s16(MISSILE_CITY_MASK_VARIABLE, 0x3F)
        + _set_variable_s16(MISSILE_CITIES_VARIABLE, len(MISSILE_CITY_COLUMNS))
        + _set_variable_s16(
            MISSILE_NEXT_BONUS_SCORE_VARIABLE,
            MISSILE_BONUS_CITY_INTERVAL_UNITS,
        )
        + _set_variable_s16(MISSILE_RESERVE_CITIES_VARIABLE, 0)
        + _set_variable_s16(MISSILE_BONUS_AWARDED_VARIABLE, 0)
        + b"\x0D"
    )


def _missile_spawn_enemy_body(base: int) -> bytes:
    """Publish one pixel-space warhead into the first free enemy slot."""

    routine = _RoutineBuilder(base)
    routine.jump_if_signed_greater_or_equal(
        MISSILE_SPAWNED_VARIABLE,
        MISSILE_MAX_WAVE_ENEMIES,
        "spawn_done",
    )
    routine.jump_if_variables_equal(
        MISSILE_SPAWNED_VARIABLE,
        MISSILE_WAVE_QUOTA_VARIABLE,
        "spawn_done",
    )
    routine.jump_if_signed_greater_or_equal(
        MISSILE_ACTIVE_ENEMIES_VARIABLE,
        MISSILE_MAX_ENEMIES,
        "spawn_retry",
    )
    for index, active_variable in enumerate(MISSILE_ENEMY_ACTIVE_VARIABLES):
        routine.jump_if_equal(active_variable, 0, f"spawn_slot_{index}")
    routine.jump("spawn_retry")

    for slot in range(MISSILE_MAX_ENEMIES):
        active_variable = MISSILE_ENEMY_ACTIVE_VARIABLES[slot]
        start_x_variable = MISSILE_ENEMY_START_X_VARIABLES[slot]
        x_variable = MISSILE_ENEMY_X_VARIABLES[slot]
        y_variable = MISSILE_ENEMY_Y_VARIABLES[slot]
        target_x_variable = MISSILE_ENEMY_TARGET_X_VARIABLES[slot]
        target_index_variable = MISSILE_ENEMY_TARGET_INDEX_VARIABLES[slot]
        trail_x_variables = MISSILE_ENEMY_TRAIL_X_VARIABLES[slot]
        trail_y_variables = MISSILE_ENEMY_TRAIL_Y_VARIABLES[slot]
        routine.label(f"spawn_slot_{slot}")
        routine.emit(
            b"".join(
                _set_variable_s16(variable, MISSILE_TRAIL_EMPTY)
                for variables in zip(
                    trail_x_variables,
                    trail_y_variables,
                    strict=True,
                )
                for variable in variables
            )
            + _set_variable_s16(active_variable, 1)
            + _random_modulo_variable(start_x_variable, 25)
            + _increment_variable(start_x_variable)
            + _variable_math(0xDE, start_x_variable, NUKE_TILE_SIZE)
            + _copy_variable(x_variable, start_x_variable)
            + _set_variable_s16(y_variable, 0)
            + _random_modulo_variable(
                target_index_variable,
                len(MISSILE_TARGET_COLUMNS) - 1,
            )
        )
        for target_index in range(len(MISSILE_TARGET_COLUMNS) - 1):
            routine.jump_if_equal(
                target_index_variable,
                target_index,
                f"spawn_{slot}_target_{target_index}",
            )
        routine.emit(
            _set_variable_s16(
                target_x_variable,
                MISSILE_TARGET_COLUMNS[-1] * NUKE_TILE_SIZE,
            )
        )
        routine.jump(f"spawn_{slot}_target_ready")
        for target_index, column in enumerate(MISSILE_TARGET_COLUMNS[:-1]):
            routine.label(f"spawn_{slot}_target_{target_index}")
            routine.emit(
                _set_variable_s16(
                    target_x_variable,
                    column * NUKE_TILE_SIZE,
                )
            )
            routine.jump(f"spawn_{slot}_target_ready")
        routine.label(f"spawn_{slot}_target_ready")
        routine.emit(
            _increment_variable(MISSILE_SPAWNED_VARIABLE)
            + _increment_variable(MISSILE_ACTIVE_ENEMIES_VARIABLE)
            + _set_variable_s16(NUKE_TEMP_0_VARIABLE, 18)
            + _variable_math(
                0x39,
                NUKE_TEMP_0_VARIABLE,
                MISSILE_WAVE_VARIABLE,
                operand_is_variable=True,
            )
            + _variable_math(0xDE, NUKE_TEMP_0_VARIABLE, 3)
        )
        routine.jump_if_signed_greater_or_equal(
            NUKE_TEMP_0_VARIABLE,
            MISSILE_MINIMUM_SPAWN_TIMER,
            f"spawn_{slot}_timer_ready",
        )
        routine.emit(
            _set_variable_s16(
                NUKE_TEMP_0_VARIABLE,
                MISSILE_MINIMUM_SPAWN_TIMER,
            )
        )
        routine.label(f"spawn_{slot}_timer_ready")
        routine.emit(
            _copy_variable(MISSILE_SPAWN_TIMER_VARIABLE, NUKE_TEMP_0_VARIABLE)
        )
        routine.jump("spawn_done")

    routine.label("spawn_retry")
    routine.emit(_set_variable_s16(MISSILE_SPAWN_TIMER_VARIABLE, 6))
    routine.label("spawn_done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_update_enemies_body(
    base: int,
    *,
    draw_cell_pc: int,
) -> bytes:
    """Advance six integer-DDA warheads and resolve ground impacts."""

    routine = _RoutineBuilder(base)
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _set_variable_s16(MISSILE_TERRAIN_DIRTY_VARIABLE, 0)
    )
    for slot in range(MISSILE_MAX_ENEMIES):
        active_variable = MISSILE_ENEMY_ACTIVE_VARIABLES[slot]
        start_x_variable = MISSILE_ENEMY_START_X_VARIABLES[slot]
        x_variable = MISSILE_ENEMY_X_VARIABLES[slot]
        y_variable = MISSILE_ENEMY_Y_VARIABLES[slot]
        target_x_variable = MISSILE_ENEMY_TARGET_X_VARIABLES[slot]
        target_index_variable = MISSILE_ENEMY_TARGET_INDEX_VARIABLES[slot]
        next_label = f"enemy_{slot}_next"
        impact_label = f"enemy_{slot}_impact"
        routine.jump_if_not_equal(active_variable, 1, next_label)
        routine.emit(
            _missile_xy_to_cell_body(x_variable, y_variable)
            + _nuke_set_tile_source_body("enemy_trail")
            + _call(draw_cell_pc)
            + _increment_variable(y_variable)
        )
        routine.jump_if_signed_greater_or_equal(
            y_variable,
            MISSILE_GROUND_ROW,
            impact_label,
        )
        routine.emit(
            _copy_variable(NUKE_TEMP_0_VARIABLE, target_x_variable)
            + _variable_math(
                0x39,
                NUKE_TEMP_0_VARIABLE,
                start_x_variable,
                operand_is_variable=True,
            )
            + _variable_math(
                0xDE,
                NUKE_TEMP_0_VARIABLE,
                y_variable,
                operand_is_variable=True,
            )
            + _variable_math(0xDF, NUKE_TEMP_0_VARIABLE, MISSILE_GROUND_ROW)
            + _copy_variable(x_variable, start_x_variable)
            + _variable_math(
                0x38,
                x_variable,
                NUKE_TEMP_0_VARIABLE,
                operand_is_variable=True,
            )
            + _missile_xy_to_cell_body(x_variable, y_variable)
            + _nuke_set_tile_source_body("warhead")
            + _call(draw_cell_pc)
        )
        routine.jump(next_label)

        routine.label(impact_label)
        routine.emit(
            _set_variable_s16(active_variable, 0)
            + _decrement_variable(MISSILE_ACTIVE_ENEMIES_VARIABLE)
            + _set_variable_s16(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_GROUND_ROW * NUKE_GRID_WIDTH,
            )
            + _variable_math(
                0x38,
                NUKE_DRAW_CELL_VARIABLE,
                target_x_variable,
                operand_is_variable=True,
            )
            + _nuke_set_tile_source_body("explosion")
            + _call(draw_cell_pc)
            + b"\x74"
            + _immediate(MISSILE_SOUND_EXPLOSION)
            + _set_variable_s16(MISSILE_TERRAIN_DIRTY_VARIABLE, 1)
        )
        for city_index in range(len(MISSILE_CITY_COLUMNS)):
            routine.jump_if_equal(
                target_index_variable,
                city_index,
                f"enemy_{slot}_city_{city_index}",
            )
        for battery_index in range(len(MISSILE_BATTERY_COLUMNS)):
            routine.jump_if_equal(
                target_index_variable,
                len(MISSILE_CITY_COLUMNS) + battery_index,
                f"enemy_{slot}_battery_{battery_index}",
            )
        routine.jump(next_label)
        for city_index in range(len(MISSILE_CITY_COLUMNS)):
            city_done = f"enemy_{slot}_city_{city_index}_done"
            routine.label(f"enemy_{slot}_city_{city_index}")
            routine.jump_if_signed_greater_or_equal(
                MISSILE_WAVE_CITY_LOSSES_VARIABLE,
                3,
                city_done,
            )
            routine.jump_if_bit_clear(
                MISSILE_CITY_MASK_VARIABLE,
                1 << city_index,
                city_done,
            )
            routine.emit(
                _clear_var_bit(MISSILE_CITY_MASK_VARIABLE, city_index)
                + _decrement_variable(MISSILE_CITIES_VARIABLE)
                + _increment_variable(MISSILE_WAVE_CITY_LOSSES_VARIABLE)
            )
            routine.label(city_done)
            routine.jump(next_label)
        for battery_index, ammo_variable in enumerate(
            MISSILE_BATTERY_AMMO_VARIABLES
        ):
            reserve_empty_label = (
                f"enemy_{slot}_battery_{battery_index}_reserve_empty"
            )
            routine.label(f"enemy_{slot}_battery_{battery_index}")
            routine.emit(
                _copy_variable(NUKE_TEMP_0_VARIABLE, ammo_variable)
                + _variable_math(
                    0x39,
                    MISSILE_AMMO_VARIABLE,
                    NUKE_TEMP_0_VARIABLE,
                    operand_is_variable=True,
                )
                + _set_variable_s16(ammo_variable, 0)
            )
            routine.jump_if_equal(
                MISSILE_AMMO_VARIABLE,
                0,
                reserve_empty_label,
            )
            routine.emit(
                _set_variable_s16(
                    ammo_variable,
                    MISSILE_BATTERY_AMMO,
                )
            )
            routine.label(reserve_empty_label)
            routine.jump(next_label)
        routine.label(next_label)
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_redraw_dynamic_body(
    base: int,
    *,
    draw_cell_pc: int,
) -> bytes:
    """Recompose retained trails, moving heads, and every live fireball."""

    routine = _RoutineBuilder(base)

    # Trails sit below heads and fireballs. Redrawing in this order repairs
    # overlap after either a three-cell FIFO cleanup or a shrinking blast.
    trail_tiles = ("trail_hot", "trail_bright", "trail_dim")
    for slot, variables in enumerate(MISSILE_TRAIL_CELL_VARIABLES):
        for index in reversed(range(MISSILE_TRAIL_LENGTH)):
            variable = variables[index]
            next_label = f"redraw_trail_{slot}_{index}_next"
            routine.jump_if_equal(variable, MISSILE_TRAIL_EMPTY, next_label)
            routine.emit(
                _copy_variable(NUKE_DRAW_CELL_VARIABLE, variable)
                + _nuke_set_tile_source_body(trail_tiles[index])
                + _call(draw_cell_pc)
            )
            routine.label(next_label)

    for slot, active_variable in enumerate(MISSILE_ENEMY_ACTIVE_VARIABLES):
        next_label = f"redraw_enemy_{slot}_next"
        routine.jump_if_not_equal(active_variable, 1, next_label)
        routine.emit(
            _missile_xy_to_cell_body(
                MISSILE_ENEMY_X_VARIABLES[slot],
                MISSILE_ENEMY_Y_VARIABLES[slot],
            )
            + _nuke_set_tile_source_body("warhead")
            + _call(draw_cell_pc)
        )
        routine.label(next_label)

    for slot, active_variable in enumerate(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES):
        next_label = f"redraw_interceptor_{slot}_next"
        routine.jump_if_not_equal(active_variable, 1, next_label)
        routine.emit(
            _missile_xy_to_cell_body(
                MISSILE_INTERCEPTOR_X_VARIABLES[slot],
                MISSILE_INTERCEPTOR_Y_VARIABLES[slot],
            )
            + _nuke_set_tile_source_body("interceptor")
            + _call(draw_cell_pc)
        )
        routine.label(next_label)

    for slot, (phase_variable, cell_variable) in enumerate(
        zip(
            MISSILE_BLAST_PHASE_VARIABLES,
            MISSILE_BLAST_CELL_VARIABLES,
            strict=True,
        )
    ):
        next_label = f"redraw_blast_{slot}_next"
        yield_label = f"redraw_blast_{slot}_yield"
        routine.jump_if_equal(phase_variable, 0, next_label)
        routine.emit(
            _missile_draw_offset_body(
                cell_variable,
                0,
                "explosion",
                draw_cell_pc,
            )
        )
        routine.jump_if_equal(phase_variable, 1, yield_label)
        routine.jump_if_equal(phase_variable, 5, yield_label)
        for offset in MISSILE_BLAST_CROSS_OFFSETS:
            routine.emit(
                _missile_draw_offset_body(
                    cell_variable,
                    offset,
                    "explosion",
                    draw_cell_pc,
                )
            )
        routine.label(yield_label)
        # One compact-cross redraw is bounded. Split concurrent fireballs across
        # scheduler slices to remain below ATEL's 1024-op execution guard.
        routine.emit(_yield_tick() + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS)
        routine.label(next_label)

    routine.emit(b"\x0D")
    return routine.finish()


def _missile_update_interceptor_body(
    base: int,
    *,
    draw_cell_pc: int,
    erase_cell_pc: int,
    redraw_dynamic_pc: int,
) -> bytes:
    """Advance three center-launched ABMs with bounded three-cell trails."""

    routine = _RoutineBuilder(base)
    routine.emit(_set_variable_s16(MISSILE_TRAIL_DIRTY_VARIABLE, 0))
    for slot in range(len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES)):
        battery_column = MISSILE_BATTERY_COLUMN
        active_variable = MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[slot]
        x_variable = MISSILE_INTERCEPTOR_X_VARIABLES[slot]
        y_variable = MISSILE_INTERCEPTOR_Y_VARIABLES[slot]
        target_x_variable = MISSILE_INTERCEPTOR_TARGET_X_VARIABLES[slot]
        target_y_variable = MISSILE_INTERCEPTOR_TARGET_Y_VARIABLES[slot]
        step_variable = MISSILE_INTERCEPTOR_STEP_VARIABLES[slot]
        total_variable = MISSILE_INTERCEPTOR_TOTAL_VARIABLES[slot]
        interceptor_tick_variable = MISSILE_INTERCEPTOR_TICK_VARIABLES[slot]
        explosion_phase_variable = MISSILE_EXPLOSION_PHASE_VARIABLES[slot]
        explosion_tick_variable = MISSILE_EXPLOSION_TICK_VARIABLES[slot]
        explosion_cell_variable = MISSILE_EXPLOSION_CELL_VARIABLES[slot]
        trail_variables = MISSILE_TRAIL_CELL_VARIABLES[slot]
        next_label = f"interceptor_{slot}_next"
        detonate_label = f"interceptor_{slot}_detonate"
        trail_shift_label = f"interceptor_{slot}_trail_shift"

        routine.jump_if_not_equal(active_variable, 1, next_label)
        routine.emit(_decrement_variable(interceptor_tick_variable))
        routine.jump_if_not_equal(interceptor_tick_variable, 0, next_label)
        routine.emit(
            _set_variable_s16(
                interceptor_tick_variable,
                MISSILE_INTERCEPTOR_DELAYS[slot],
            )
        )
        routine.jump_if_equal(
            trail_variables[-1],
            MISSILE_TRAIL_EMPTY,
            trail_shift_label,
        )
        routine.emit(
            _copy_variable(
                NUKE_DRAW_CELL_VARIABLE,
                trail_variables[-1],
            )
            + _set_variable_s16(
                trail_variables[-1],
                MISSILE_TRAIL_EMPTY,
            )
            + _call(erase_cell_pc)
            + _set_variable_s16(MISSILE_TRAIL_DIRTY_VARIABLE, 1)
        )
        routine.label(trail_shift_label)
        routine.emit(
            _copy_variable(trail_variables[2], trail_variables[1])
            + _copy_variable(trail_variables[1], trail_variables[0])
            + _missile_xy_to_cell_body(x_variable, y_variable)
            + _copy_variable(trail_variables[0], NUKE_DRAW_CELL_VARIABLE)
        )
        trail_tiles = ("trail_hot", "trail_bright", "trail_dim")
        for trail_index in reversed(range(MISSILE_TRAIL_LENGTH)):
            trail_draw_done_label = (
                f"interceptor_{slot}_trail_{trail_index}_draw_done"
            )
            routine.jump_if_equal(
                trail_variables[trail_index],
                MISSILE_TRAIL_EMPTY,
                trail_draw_done_label,
            )
            routine.emit(
                _copy_variable(
                    NUKE_DRAW_CELL_VARIABLE,
                    trail_variables[trail_index],
                )
                + _nuke_set_tile_source_body(trail_tiles[trail_index])
                + _call(draw_cell_pc)
            )
            routine.label(trail_draw_done_label)
        routine.emit(_increment_variable(step_variable))
        routine.jump_if_variables_equal(
            step_variable,
            total_variable,
            detonate_label,
        )
        routine.emit(
            _set_variable_s16(y_variable, MISSILE_GROUND_ROW - 1)
            + _set_variable_s16(
                NUKE_TEMP_1_VARIABLE,
                MISSILE_GROUND_ROW - 1,
            )
            + _variable_math(
                0x39,
                NUKE_TEMP_1_VARIABLE,
                target_y_variable,
                operand_is_variable=True,
            )
            + _variable_math(
                0xDE,
                NUKE_TEMP_1_VARIABLE,
                step_variable,
                operand_is_variable=True,
            )
            + _variable_math(
                0xDF,
                NUKE_TEMP_1_VARIABLE,
                total_variable,
                operand_is_variable=True,
            )
            + _variable_math(
                0x39,
                y_variable,
                NUKE_TEMP_1_VARIABLE,
                operand_is_variable=True,
            )
            + _copy_variable(NUKE_TEMP_0_VARIABLE, target_x_variable)
            + _variable_math(0x39, NUKE_TEMP_0_VARIABLE, battery_column)
            + _variable_math(
                0xDE,
                NUKE_TEMP_0_VARIABLE,
                step_variable,
                operand_is_variable=True,
            )
            + _variable_math(
                0xDF,
                NUKE_TEMP_0_VARIABLE,
                total_variable,
                operand_is_variable=True,
            )
            + _set_variable_s16(x_variable, battery_column)
            + _variable_math(
                0x38,
                x_variable,
                NUKE_TEMP_0_VARIABLE,
                operand_is_variable=True,
            )
            + _missile_xy_to_cell_body(x_variable, y_variable)
            + _nuke_set_tile_source_body("interceptor")
            + _call(draw_cell_pc)
        )
        routine.jump(next_label)

        routine.label(detonate_label)
        routine.emit(_set_variable_s16(active_variable, 0))
        for trail_index, trail_variable in enumerate(trail_variables):
            cleanup_done_label = (
                f"interceptor_{slot}_trail_{trail_index}_cleanup_done"
            )
            routine.jump_if_equal(
                trail_variable,
                MISSILE_TRAIL_EMPTY,
                cleanup_done_label,
            )
            routine.emit(
                _copy_variable(NUKE_DRAW_CELL_VARIABLE, trail_variable)
                + _set_variable_s16(
                    trail_variable,
                    MISSILE_TRAIL_EMPTY,
                )
                + _call(erase_cell_pc)
                + _set_variable_s16(MISSILE_TRAIL_DIRTY_VARIABLE, 1)
            )
            routine.label(cleanup_done_label)
        routine.emit(
            _set_variable_s16(explosion_phase_variable, 1)
            + _set_variable_s16(
                explosion_tick_variable,
                MISSILE_EXPLOSION_DELAY,
            )
            + _copy_variable(explosion_cell_variable, target_y_variable)
            + _variable_math(
                0xDE,
                explosion_cell_variable,
                NUKE_GRID_WIDTH,
            )
            + _variable_math(
                0x38,
                explosion_cell_variable,
                target_x_variable,
                operand_is_variable=True,
            )
            + _missile_draw_offset_body(
                explosion_cell_variable,
                0,
                "explosion",
                draw_cell_pc,
            )
            + b"\x74"
            + _immediate(MISSILE_SOUND_EXPLOSION)
            # A legal dense frame can combine cursor movement, an enemy
            # spawn, six enemy updates, and three full-tail detonations.
            # Split only real detonations so that rare combination remains
            # below ATEL's absolute 1024-opcode scheduler guard without
            # slowing ordinary interceptor movement.
            + _yield_tick()
            + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        )
        routine.label(next_label)
    routine.jump_if_equal(
        MISSILE_TRAIL_DIRTY_VARIABLE,
        0,
        "interceptor_update_done",
    )
    # Trail erasure can cross another trail, moving head, or fireball. Move
    # the full recomposition to a fresh scheduler slice before returning to
    # collision and explosion updates.
    routine.emit(
        _yield_tick()
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(redraw_dynamic_pc)
    )
    routine.label("interceptor_update_done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_update_explosion_body(
    base: int,
    *,
    draw_cell_pc: int,
    erase_cell_pc: int,
    redraw_dynamic_pc: int,
) -> bytes:
    """Animate every player and chain fireball through a compact cross."""

    routine = _RoutineBuilder(base)
    # Recompose live heads and surviving fireballs only on frames where an
    # ending blast restores background cells.  This keeps overlapping blasts
    # visually consistent without paying for a whole-board redraw every tick.
    routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 0))
    for slot, (
        phase_variable,
        tick_variable,
        cell_variable,
    ) in enumerate(
        zip(
            MISSILE_BLAST_PHASE_VARIABLES,
            MISSILE_BLAST_TICK_VARIABLES,
            MISSILE_BLAST_CELL_VARIABLES,
            strict=True,
        )
    ):
        next_label = f"blast_{slot}_next"
        transition_done_label = f"blast_{slot}_transition_done"
        routine.jump_if_equal(phase_variable, 0, next_label)
        routine.emit(_decrement_variable(tick_variable))
        routine.jump_if_not_equal(tick_variable, 0, next_label)
        routine.emit(
            _set_variable_s16(tick_variable, MISSILE_EXPLOSION_DELAY)
            + _increment_variable(phase_variable)
        )
        for phase in range(2, 7):
            routine.jump_if_equal(
                phase_variable,
                phase,
                f"blast_{slot}_phase_{phase}",
            )
        routine.emit(_set_variable_s16(phase_variable, 0))
        routine.jump(transition_done_label)

        routine.label(f"blast_{slot}_phase_2")
        for offset in MISSILE_BLAST_CROSS_OFFSETS:
            routine.emit(
                _missile_draw_offset_body(
                    cell_variable,
                    offset,
                    "explosion",
                    draw_cell_pc,
                )
            )
        routine.jump(transition_done_label)
        routine.label(f"blast_{slot}_phase_3")
        routine.jump(transition_done_label)
        routine.label(f"blast_{slot}_phase_4")
        routine.jump(transition_done_label)
        routine.label(f"blast_{slot}_phase_5")
        routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 1))
        for offset in MISSILE_BLAST_CROSS_OFFSETS:
            routine.emit(
                _missile_erase_offset_body(
                    cell_variable,
                    offset,
                    erase_cell_pc,
                )
            )
        routine.jump(transition_done_label)
        routine.label(f"blast_{slot}_phase_6")
        routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 1))
        routine.emit(
            _missile_erase_offset_body(
                cell_variable,
                0,
                erase_cell_pc,
            )
        )
        routine.emit(_set_variable_s16(phase_variable, 0))
        routine.label(transition_done_label)
        # Drawing or erasing one compact blast is bounded, but letting all
        # six synchronized fireballs transition in a single VM tick can cross
        # ATEL's 1024-opcode execution guard.  Yield after each actual phase
        # change so every fireball remains concurrent without combining their
        # blitter cost into one oversized scheduler slice.
        routine.emit(_yield_tick() + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS)
        routine.label(next_label)

    routine.jump_if_equal(NUKE_TEMP_2_VARIABLE, 0, "blast_refresh_done")
    # The shared compositor also restores capped interceptor trails that a
    # shrinking fireball may have crossed.
    routine.emit(_call(redraw_dynamic_pc))
    routine.label("blast_refresh_done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_explosion_collision_body(
    base: int,
    *,
    draw_cell_pc: int,
    missile_hud_pc: int,
) -> bytes:
    """Resolve phase-matched blast hits and seed bounded chain reactions."""

    routine = _RoutineBuilder(base)
    routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 0))
    for slot in range(MISSILE_MAX_ENEMIES):
        active_variable = MISSILE_ENEMY_ACTIVE_VARIABLES[slot]
        x_variable = MISSILE_ENEMY_X_VARIABLES[slot]
        y_variable = MISSILE_ENEMY_Y_VARIABLES[slot]
        next_label = f"blast_enemy_{slot}_next"
        hit_label = f"blast_enemy_{slot}_hit"
        routine.jump_if_not_equal(active_variable, 1, next_label)
        for blast, (
            phase_variable,
            blast_x_variable,
            blast_y_variable,
        ) in enumerate(
            zip(
                MISSILE_BLAST_PHASE_VARIABLES,
                MISSILE_BLAST_X_VARIABLES,
                MISSILE_BLAST_Y_VARIABLES,
                strict=True,
            )
        ):
            blast_next = f"blast_enemy_{slot}_source_{blast}_next"
            x_ready = f"blast_enemy_{slot}_source_{blast}_x_ready"
            y_ready = f"blast_enemy_{slot}_source_{blast}_y_ready"
            routine.jump_if_equal(phase_variable, 0, blast_next)
            routine.emit(
                _copy_variable(NUKE_TEMP_0_VARIABLE, x_variable)
                + _variable_math(
                    0x39,
                    NUKE_TEMP_0_VARIABLE,
                    blast_x_variable,
                    operand_is_variable=True,
                )
            )
            routine.jump_if_signed_greater_or_equal(
                NUKE_TEMP_0_VARIABLE,
                0,
                x_ready,
            )
            routine.emit(_variable_math(0xDE, NUKE_TEMP_0_VARIABLE, -1))
            routine.label(x_ready)
            routine.jump_if_signed_greater_or_equal(
                NUKE_TEMP_0_VARIABLE,
                2,
                blast_next,
            )
            routine.emit(
                _copy_variable(NUKE_TEMP_1_VARIABLE, y_variable)
                + _variable_math(
                    0x39,
                    NUKE_TEMP_1_VARIABLE,
                    blast_y_variable,
                    operand_is_variable=True,
                )
            )
            routine.jump_if_signed_greater_or_equal(
                NUKE_TEMP_1_VARIABLE,
                0,
                y_ready,
            )
            routine.emit(_variable_math(0xDE, NUKE_TEMP_1_VARIABLE, -1))
            routine.label(y_ready)
            routine.emit(
                _variable_math(
                    0x38,
                    NUKE_TEMP_0_VARIABLE,
                    NUKE_TEMP_1_VARIABLE,
                    operand_is_variable=True,
                )
            )
            routine.jump_if_signed_greater_or_equal(
                NUKE_TEMP_0_VARIABLE,
                2,
                blast_next,
            )
            routine.jump_if_equal(NUKE_TEMP_0_VARIABLE, 0, hit_label)
            routine.jump_if_equal(phase_variable, 1, blast_next)
            routine.jump_if_equal(phase_variable, 5, blast_next)
            routine.jump(hit_label)
            routine.label(blast_next)
        routine.jump(next_label)
        routine.label(hit_label)
        routine.emit(
            _set_variable_s16(active_variable, 0)
            + _decrement_variable(MISSILE_ACTIVE_ENEMIES_VARIABLE)
            + _missile_xy_to_cell_body(x_variable, y_variable)
            # Restore the head to its existing contrail first.  A successful
            # chain-slot claim below replaces it with an owned explosion;
            # edge hits or a full pool therefore cannot strand an un-timed
            # explosion tile on the board.
            + _nuke_set_tile_source_body("enemy_trail")
            + _call(draw_cell_pc)
            + _copy_variable(
                NUKE_TEMP_1_VARIABLE,
                MISSILE_SCORE_MULTIPLIER_VARIABLE,
            )
            + _variable_math(
                0xDE,
                NUKE_TEMP_1_VARIABLE,
                MISSILE_ENEMY_SCORE_UNITS,
            )
            + _variable_math(
                0x38,
                MISSILE_SCORE_VARIABLE,
                NUKE_TEMP_1_VARIABLE,
                operand_is_variable=True,
            )
        )
        routine.jump_if_signed_greater_or_equal(
            MISSILE_SCORE_VARIABLE,
            MISSILE_MAX_SCORE_UNITS + 1,
            f"blast_enemy_{slot}_clamp",
        )
        routine.jump(f"blast_enemy_{slot}_scored")
        routine.label(f"blast_enemy_{slot}_clamp")
        routine.emit(
            _set_variable_s16(MISSILE_SCORE_VARIABLE, MISSILE_MAX_SCORE_UNITS)
        )
        routine.label(f"blast_enemy_{slot}_scored")
        routine.emit(
            b"\x74"
            + _immediate(MISSILE_SOUND_EXPLOSION)
            + _set_variable_s16(NUKE_TEMP_2_VARIABLE, 1)
        )
        chain_done = f"blast_enemy_{slot}_chain_done"
        # Keep every compact cross inside the frame and above the ground row;
        # the smaller footprint safely admits one more cell around each edge.
        routine.jump_if_signed_less_than(x_variable, 1, chain_done)
        routine.jump_if_signed_greater_or_equal(x_variable, 27, chain_done)
        routine.jump_if_signed_less_than(y_variable, 1, chain_done)
        routine.jump_if_signed_greater_or_equal(y_variable, 14, chain_done)
        for chain_slot, phase_variable in enumerate(
            MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES
        ):
            routine.jump_if_equal(
                phase_variable,
                0,
                f"blast_enemy_{slot}_chain_{chain_slot}",
            )
        routine.jump(chain_done)
        for chain_slot in range(MISSILE_CHAIN_EXPLOSION_COUNT):
            routine.label(f"blast_enemy_{slot}_chain_{chain_slot}")
            routine.emit(
                _set_variable_s16(
                    MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES[chain_slot],
                    1,
                )
                + _set_variable_s16(
                    MISSILE_CHAIN_EXPLOSION_TICK_VARIABLES[chain_slot],
                    MISSILE_EXPLOSION_DELAY,
                )
                + _copy_variable(
                    MISSILE_CHAIN_EXPLOSION_CELL_VARIABLES[chain_slot],
                    NUKE_DRAW_CELL_VARIABLE,
                )
                + _copy_variable(
                    MISSILE_CHAIN_EXPLOSION_X_VARIABLES[chain_slot],
                    x_variable,
                )
                + _copy_variable(
                    MISSILE_CHAIN_EXPLOSION_Y_VARIABLES[chain_slot],
                    y_variable,
                )
                + _nuke_set_tile_source_body("explosion")
                + _call(draw_cell_pc)
            )
            routine.jump(chain_done)
        routine.label(chain_done)
        routine.label(next_label)
    routine.jump_if_equal(NUKE_TEMP_2_VARIABLE, 0, "done")
    # A dense chain reaction can resolve several enemies in one helper pass.
    # Split the HUD refresh onto the next scheduler tick so even the maximum
    # six-enemy movement/collision frame stays below ATEL's 1024-op guard.
    routine.emit(
        _yield_tick()
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(missile_hud_pc)
    )
    routine.label("done")
    # Keep the six-enemy by six-fireball scan in a separate scheduler slice
    # from the potentially dense animation/redraw helper that follows it.
    routine.emit(
        _yield_tick() + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS + b"\x0D"
    )
    return routine.finish()


def _missile_set_pixel_destination_body(
    x_variable: int,
    y_variable: int,
) -> bytes:
    """Map pixel offsets inside the CRT grid to live VRAM coordinates."""

    return (
        _copy_variable(NUKE_DESTINATION_X_VARIABLE, x_variable)
        + _variable_math(
            0x38,
            NUKE_DESTINATION_X_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[0] + NUKE_GRID_SCREEN_ORIGIN[0],
        )
        + _copy_variable(NUKE_DESTINATION_Y_VARIABLE, y_variable)
        + _variable_math(
            0x38,
            NUKE_DESTINATION_Y_VARIABLE,
            NUKE_LIVE_VRAM_ORIGIN[1] + NUKE_GRID_SCREEN_ORIGIN[1],
        )
    )


def _missile_draw_pixel_body() -> bytes:
    """Draw one foreground point at the prepared pixel destination."""

    variable = _AtelVariableOperand
    return (
        _vram_move(
            variable(NUKE_SOURCE_X_VARIABLE),
            variable(NUKE_SOURCE_Y_VARIABLE),
            1,
            1,
            variable(NUKE_DESTINATION_X_VARIABLE),
            variable(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _missile_draw_interceptor_body(cell_to_vram_pc: int) -> bytes:
    """Draw only the foreground of the existing upright interceptor tile."""

    source_x, source_y, width, height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS["interceptor"]
    )
    if (width, height) != (NUKE_TILE_SIZE, NUKE_TILE_SIZE):
        raise DungeonBuildError("Missile interceptor tile is not a 6x6 cell")
    variable = _AtelVariableOperand
    return (
        _call(cell_to_vram_pc)
        # The exact colored bitmap decomposes into a one-by-five centerline
        # (white nose, green body, amber exhaust) and one three-pixel fin row.
        # Copying only those strips writes no baked CRT-background texels.
        + _variable_math(0x38, NUKE_DESTINATION_X_VARIABLE, 2)
        + _vram_move(
            source_x + 2,
            source_y,
            1,
            5,
            variable(NUKE_DESTINATION_X_VARIABLE),
            variable(NUKE_DESTINATION_Y_VARIABLE),
        )
        + _variable_math(0x39, NUKE_DESTINATION_X_VARIABLE, 1)
        + _variable_math(0x38, NUKE_DESTINATION_Y_VARIABLE, 1)
        + _vram_move(
            source_x + 1,
            source_y + 1,
            3,
            1,
            variable(NUKE_DESTINATION_X_VARIABLE),
            variable(NUKE_DESTINATION_Y_VARIABLE),
        )
        + b"\x0D"
    )


def _missile_draw_pixel_at_body(
    x_variable: int,
    y_variable: int,
    tile_name: str,
    draw_pixel_pc: int,
) -> bytes:
    # Pixel-space enemies cannot use the ordinary opaque 6x6 tiles: their
    # baked CRT grain is phase-correct only at grid-aligned destinations and
    # otherwise stamps visible squares into the monitor.  Reuse one exact
    # foreground texel from each existing tile so only the intended point is
    # written.  E27 recomposes at most three retained red points per enemy,
    # then paints every current head white in a separate final pass.
    point_offsets = {
        "enemy_trail": (2, 1),
        "warhead": (1, 1),
    }
    if tile_name not in point_offsets:
        raise DungeonBuildError(
            f"Missile pixel marker has no audited foreground point: {tile_name!r}"
        )
    tile_x, tile_y, _width, _height = _nuke_atlas_vram_rect(
        NUKE_TILE_RECTS[tile_name]
    )
    point_x, point_y = point_offsets[tile_name]
    return (
        _missile_set_pixel_destination_body(x_variable, y_variable)
        + _set_variable_s16(NUKE_SOURCE_X_VARIABLE, tile_x + point_x)
        + _set_variable_s16(NUKE_SOURCE_Y_VARIABLE, tile_y + point_y)
        + _call(draw_pixel_pc)
    )


def _missile_pixel_xy_to_cell_body(
    x_variable: int,
    y_variable: int,
) -> bytes:
    """Convert pixel-space object coordinates into shared grid scratch."""

    return (
        _copy_variable(MISSILE_LOGIC_X_VARIABLE, x_variable)
        + _variable_math(0xDF, MISSILE_LOGIC_X_VARIABLE, NUKE_TILE_SIZE)
        + _copy_variable(MISSILE_LOGIC_Y_VARIABLE, y_variable)
        + _variable_math(0xDF, MISSILE_LOGIC_Y_VARIABLE, NUKE_TILE_SIZE)
        + _copy_variable(MISSILE_LOGIC_CELL_VARIABLE, MISSILE_LOGIC_Y_VARIABLE)
        + _variable_math(0xDE, MISSILE_LOGIC_CELL_VARIABLE, NUKE_GRID_WIDTH)
        + _variable_math(
            0x38,
            MISSILE_LOGIC_CELL_VARIABLE,
            MISSILE_LOGIC_X_VARIABLE,
            operand_is_variable=True,
        )
    )


def _missile_erase_pixel_cell_body(
    x_variable: int,
    y_variable: int,
    erase_cell_pc: int,
) -> bytes:
    """Restore the complete grid cell containing one transient pixel."""

    # Retained trail points stay above the ground row, where the static layer
    # is the repeating CRT-grain cell.  An impacting current head can occupy
    # the ground row, whose owner also publishes terrain dirty for e26.  The
    # ordered e24/e25/e26/e27 compositors therefore repair every static and
    # dynamic layer that may share the restored cell in the same field frame.
    return (
        _missile_pixel_xy_to_cell_body(x_variable, y_variable)
        + _copy_variable(NUKE_DRAW_CELL_VARIABLE, MISSILE_LOGIC_CELL_VARIABLE)
        + _call(erase_cell_pc)
    )


def _missile_clock_worker_body(base: int, *, spawn_enemy_pc: int) -> bytes:
    """Commit lifecycle requests, snapshot blasts, and publish frame clocks."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "inactive")
    routine.jump_if_equal(
        MISSILE_MODE_REQUEST_VARIABLE,
        MISSILE_MODE_STOPPED,
        "stop_requested",
    )
    routine.jump_if_equal(
        MISSILE_MODE_REQUEST_VARIABLE,
        MISSILE_MODE_PAUSED,
        "pause_requested",
    )
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "arm_requested")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "arm_requested")

    routine.emit(b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS)
    for snapshot, phase in zip(
        MISSILE_BLAST_PHASE_SNAPSHOT_VARIABLES,
        MISSILE_BLAST_PHASE_VARIABLES,
        strict=True,
    ):
        routine.emit(_copy_variable(snapshot, phase))
    routine.emit(_set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0))
    routine.jump_if_equal(MISSILE_SPAWN_TIMER_VARIABLE, 0, "spawn")
    routine.emit(_decrement_variable(MISSILE_SPAWN_TIMER_VARIABLE))
    routine.jump("enemy_clock")
    routine.label("spawn")
    routine.emit(_call(spawn_enemy_pc))

    routine.label("enemy_clock")
    routine.jump_if_equal(MISSILE_ENEMY_TICK_VARIABLE, 0, "enemy_step")
    routine.emit(_decrement_variable(MISSILE_ENEMY_TICK_VARIABLE))
    routine.jump("done")
    routine.label("enemy_step")
    routine.emit(
        _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 1)
        + _copy_variable(
            MISSILE_ENEMY_TICK_VARIABLE,
            MISSILE_ENEMY_DELAY_VARIABLE,
        )
    )
    routine.jump("done")

    routine.label("arm_requested")
    routine.emit(
        b"\xC6"
        + _set_variable_s16(MISSILE_RUN_VARIABLE, 1)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_MODE_ACK_VARIABLE,
            MISSILE_MODE_ARMING,
        )
        + _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0)
        + b"".join(
            _copy_variable(snapshot, phase)
            for snapshot, phase in zip(
                MISSILE_BLAST_PHASE_SNAPSHOT_VARIABLES,
                MISSILE_BLAST_PHASE_VARIABLES,
                strict=True,
            )
        )
    )
    routine.jump("done")
    routine.label("pause_requested")
    routine.emit(
        b"\xC6"
        + _set_variable_s16(MISSILE_RUN_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 1)
        + _set_variable_s16(
            MISSILE_MODE_ACK_VARIABLE,
            MISSILE_MODE_PAUSED,
        )
        + _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0)
    )
    routine.jump("done")
    routine.label("stop_requested")
    routine.emit(
        _set_variable_s16(MISSILE_RUN_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_MODE_ACK_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
        + _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0)
    )
    routine.jump("done")
    routine.label("inactive")
    routine.emit(
        _set_variable_s16(MISSILE_RUN_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_MODE_ACK_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
        + _set_variable_s16(MISSILE_ENEMY_STEP_VARIABLE, 0)
    )
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _missile_enemy_slot_worker_body(
    base: int,
    slot: int,
    *,
    erase_cell_pc: int,
) -> bytes:
    """Advance and collide one pixel-space enemy slot without yielding."""

    if not 0 <= slot < MISSILE_MAX_ENEMIES:
        raise DungeonBuildError(f"Missile enemy worker slot is invalid: {slot}")
    active_variable = MISSILE_ENEMY_ACTIVE_VARIABLES[slot]
    start_x_variable = MISSILE_ENEMY_START_X_VARIABLES[slot]
    x_variable = MISSILE_ENEMY_X_VARIABLES[slot]
    y_variable = MISSILE_ENEMY_Y_VARIABLES[slot]
    target_x_variable = MISSILE_ENEMY_TARGET_X_VARIABLES[slot]
    target_index_variable = MISSILE_ENEMY_TARGET_INDEX_VARIABLES[slot]
    trail_x_variables = MISSILE_ENEMY_TRAIL_X_VARIABLES[slot]
    trail_y_variables = MISSILE_ENEMY_TRAIL_Y_VARIABLES[slot]
    routine = _RoutineBuilder(base)

    routine.jump_if_not_equal(active_variable, 1, "done")
    routine.jump_if_not_equal(MISSILE_ENEMY_STEP_VARIABLE, 1, "collision")
    routine.jump_if_equal(
        trail_x_variables[-1],
        MISSILE_TRAIL_EMPTY,
        "oldest_trail_clean",
    )
    routine.emit(
        _missile_erase_pixel_cell_body(
            trail_x_variables[-1],
            trail_y_variables[-1],
            erase_cell_pc,
        )
    )
    routine.label("oldest_trail_clean")
    routine.emit(
        _copy_variable(trail_x_variables[2], trail_x_variables[1])
        + _copy_variable(trail_y_variables[2], trail_y_variables[1])
        + _copy_variable(trail_x_variables[1], trail_x_variables[0])
        + _copy_variable(trail_y_variables[1], trail_y_variables[0])
        + _copy_variable(trail_x_variables[0], x_variable)
        + _copy_variable(trail_y_variables[0], y_variable)
        + _increment_variable(y_variable)
    )
    routine.jump_if_signed_greater_or_equal(
        y_variable,
        MISSILE_ENEMY_PIXEL_GROUND,
        "impact",
    )
    routine.emit(
        _copy_variable(NUKE_TEMP_0_VARIABLE, target_x_variable)
        + _variable_math(
            0x39,
            NUKE_TEMP_0_VARIABLE,
            start_x_variable,
            operand_is_variable=True,
        )
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            y_variable,
            operand_is_variable=True,
        )
        + _variable_math(0xDF, NUKE_TEMP_0_VARIABLE, MISSILE_ENEMY_PIXEL_GROUND)
        + _copy_variable(x_variable, start_x_variable)
        + _variable_math(
            0x38,
            x_variable,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
    )
    routine.jump("collision")

    routine.label("impact")
    routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 0))
    routine.jump("retire")

    routine.label("collision")
    routine.emit(_missile_pixel_xy_to_cell_body(x_variable, y_variable))
    # The clock captured all six phases before any owner could advance one.
    # Treat that snapshot as the complete frame's collision footprint: a
    # shrink or expiry later in entity order therefore cannot make otherwise
    # identical enemies observe different radii.
    for blast, phase_snapshot in enumerate(
        MISSILE_BLAST_PHASE_SNAPSHOT_VARIABLES
    ):
        next_label = f"blast_{blast}_next"
        x_ready = f"blast_{blast}_x_ready"
        y_ready = f"blast_{blast}_y_ready"
        routine.jump_if_equal(phase_snapshot, 0, next_label)
        routine.emit(
            _copy_variable(NUKE_TEMP_0_VARIABLE, MISSILE_LOGIC_X_VARIABLE)
            + _variable_math(
                0x39,
                NUKE_TEMP_0_VARIABLE,
                MISSILE_BLAST_GRID_X_VARIABLES[blast],
                operand_is_variable=True,
            )
        )
        routine.jump_if_signed_greater_or_equal(NUKE_TEMP_0_VARIABLE, 0, x_ready)
        routine.emit(_variable_math(0xDE, NUKE_TEMP_0_VARIABLE, -1))
        routine.label(x_ready)
        routine.jump_if_signed_greater_or_equal(
            NUKE_TEMP_0_VARIABLE,
            2,
            next_label,
        )
        routine.emit(
            _copy_variable(NUKE_TEMP_1_VARIABLE, MISSILE_LOGIC_Y_VARIABLE)
            + _variable_math(
                0x39,
                NUKE_TEMP_1_VARIABLE,
                MISSILE_BLAST_GRID_Y_VARIABLES[blast],
                operand_is_variable=True,
            )
        )
        routine.jump_if_signed_greater_or_equal(NUKE_TEMP_1_VARIABLE, 0, y_ready)
        routine.emit(_variable_math(0xDE, NUKE_TEMP_1_VARIABLE, -1))
        routine.label(y_ready)
        routine.emit(
            _variable_math(
                0x38,
                NUKE_TEMP_0_VARIABLE,
                NUKE_TEMP_1_VARIABLE,
                operand_is_variable=True,
            )
        )
        routine.jump_if_signed_greater_or_equal(
            NUKE_TEMP_0_VARIABLE,
            2,
            next_label,
        )
        routine.jump_if_equal(NUKE_TEMP_0_VARIABLE, 0, "hit")
        routine.jump_if_equal(phase_snapshot, 1, next_label)
        routine.jump_if_equal(phase_snapshot, 5, next_label)
        routine.jump("hit")
        routine.label(next_label)
    routine.jump("done")

    routine.label("hit")
    routine.emit(_set_variable_s16(NUKE_TEMP_2_VARIABLE, 1))
    routine.label("retire")
    # Clear the current white head and every retained red point before this
    # slot is released.  These whole-cell restores occur before the later
    # player/blast/enemy compositors, so an overlapping live object is painted
    # back in the same frame instead of leaving either a hole or a ghost line.
    routine.emit(
        _missile_erase_pixel_cell_body(
            x_variable,
            y_variable,
            erase_cell_pc,
        )
    )
    for trail_index, (trail_x_variable, trail_y_variable) in enumerate(
        zip(trail_x_variables, trail_y_variables, strict=True)
    ):
        clean_label = f"retire_trail_{trail_index}_clean"
        routine.jump_if_equal(
            trail_x_variable,
            MISSILE_TRAIL_EMPTY,
            clean_label,
        )
        routine.emit(
            _missile_erase_pixel_cell_body(
                trail_x_variable,
                trail_y_variable,
                erase_cell_pc,
            )
            + _set_variable_s16(trail_x_variable, MISSILE_TRAIL_EMPTY)
            + _set_variable_s16(trail_y_variable, MISSILE_TRAIL_EMPTY)
        )
        routine.label(clean_label)
    routine.emit(
        _set_variable_s16(active_variable, 0)
        + _decrement_variable(MISSILE_ACTIVE_ENEMIES_VARIABLE)
    )
    routine.jump_if_equal(NUKE_TEMP_2_VARIABLE, 1, "hit_award")

    routine.emit(
        b"\x74"
        + _immediate(MISSILE_SOUND_EXPLOSION)
        + _set_variable_s16(MISSILE_TERRAIN_DIRTY_VARIABLE, 1)
        + _set_variable_s16(MISSILE_PLAYER_DIRTY_VARIABLE, 1)
    )
    for city_index in range(len(MISSILE_CITY_COLUMNS)):
        routine.jump_if_equal(
            target_index_variable,
            city_index,
            f"city_{city_index}",
        )
    routine.jump("battery")
    for city_index in range(len(MISSILE_CITY_COLUMNS)):
        routine.label(f"city_{city_index}")
        routine.jump_if_signed_greater_or_equal(
            MISSILE_WAVE_CITY_LOSSES_VARIABLE,
            3,
            "done",
        )
        routine.jump_if_bit_clear(
            MISSILE_CITY_MASK_VARIABLE,
            1 << city_index,
            "done",
        )
        routine.emit(
            _clear_var_bit(MISSILE_CITY_MASK_VARIABLE, city_index)
            + _decrement_variable(MISSILE_CITIES_VARIABLE)
            + _increment_variable(MISSILE_WAVE_CITY_LOSSES_VARIABLE)
        )
        routine.jump("done")
    routine.label("battery")
    routine.emit(
        _copy_variable(
            NUKE_TEMP_0_VARIABLE,
            MISSILE_BATTERY_AMMO_VARIABLES[0],
        )
        + _variable_math(
            0x39,
            MISSILE_AMMO_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _set_variable_s16(MISSILE_BATTERY_AMMO_VARIABLES[0], 0)
    )
    routine.jump_if_equal(MISSILE_AMMO_VARIABLE, 0, "done")
    routine.emit(
        _set_variable_s16(
            MISSILE_BATTERY_AMMO_VARIABLES[0],
            MISSILE_BATTERY_AMMO,
        )
    )
    routine.jump("done")

    routine.label("hit_award")
    routine.emit(
        _missile_pixel_xy_to_cell_body(x_variable, y_variable)
        + _copy_variable(
            NUKE_TEMP_1_VARIABLE,
            MISSILE_SCORE_MULTIPLIER_VARIABLE,
        )
        + _variable_math(0xDE, NUKE_TEMP_1_VARIABLE, MISSILE_ENEMY_SCORE_UNITS)
        + _variable_math(
            0x38,
            MISSILE_SCORE_VARIABLE,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _set_variable_s16(MISSILE_PLAYER_DIRTY_VARIABLE, 1)
        + b"\x74"
        + _immediate(MISSILE_SOUND_EXPLOSION)
    )
    routine.jump_if_signed_greater_or_equal(
        MISSILE_SCORE_VARIABLE,
        MISSILE_MAX_SCORE_UNITS + 1,
        "score_clamp",
    )
    routine.jump("chain_bounds")
    routine.label("score_clamp")
    routine.emit(_set_variable_s16(MISSILE_SCORE_VARIABLE, MISSILE_MAX_SCORE_UNITS))
    routine.label("chain_bounds")
    # The compact radius-one cross needs one clear cell on every side and may
    # now seed safely in the ring that the former radius-two diamond excluded.
    routine.jump_if_signed_less_than(MISSILE_LOGIC_X_VARIABLE, 1, "done")
    routine.jump_if_signed_greater_or_equal(MISSILE_LOGIC_X_VARIABLE, 27, "done")
    routine.jump_if_signed_less_than(MISSILE_LOGIC_Y_VARIABLE, 1, "done")
    routine.jump_if_signed_greater_or_equal(MISSILE_LOGIC_Y_VARIABLE, 14, "done")
    for chain_slot, phase_variable in enumerate(
        MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES
    ):
        routine.jump_if_equal(phase_variable, 0, f"chain_{chain_slot}")
    routine.jump("done")
    for chain_slot in range(MISSILE_CHAIN_EXPLOSION_COUNT):
        blast_slot = len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES) + chain_slot
        routine.label(f"chain_{chain_slot}")
        routine.emit(
            _set_variable_s16(
                MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES[chain_slot],
                1,
            )
            + _set_variable_s16(
                MISSILE_CHAIN_EXPLOSION_TICK_VARIABLES[chain_slot],
                MISSILE_EXPLOSION_DELAY,
            )
            + _copy_variable(
                MISSILE_CHAIN_EXPLOSION_CELL_VARIABLES[chain_slot],
                MISSILE_LOGIC_CELL_VARIABLE,
            )
            + _copy_variable(
                MISSILE_CHAIN_EXPLOSION_X_VARIABLES[chain_slot],
                x_variable,
            )
            + _copy_variable(
                MISSILE_CHAIN_EXPLOSION_Y_VARIABLES[chain_slot],
                y_variable,
            )
            + _copy_variable(
                MISSILE_BLAST_GRID_X_VARIABLES[blast_slot],
                MISSILE_LOGIC_X_VARIABLE,
            )
            + _copy_variable(
                MISSILE_BLAST_GRID_Y_VARIABLES[blast_slot],
                MISSILE_LOGIC_Y_VARIABLE,
            )
        )
        routine.jump("done")
    routine.label("done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_interceptor_slot_worker_body(base: int, slot: int) -> bytes:
    """Advance one ABM and retain three exhaust cells behind its missile head."""

    if not 0 <= slot < len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES):
        raise DungeonBuildError(f"Missile interceptor worker slot is invalid: {slot}")
    active_variable = MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[slot]
    x_variable = MISSILE_INTERCEPTOR_X_VARIABLES[slot]
    y_variable = MISSILE_INTERCEPTOR_Y_VARIABLES[slot]
    target_x_variable = MISSILE_INTERCEPTOR_TARGET_X_VARIABLES[slot]
    target_y_variable = MISSILE_INTERCEPTOR_TARGET_Y_VARIABLES[slot]
    step_variable = MISSILE_INTERCEPTOR_STEP_VARIABLES[slot]
    total_variable = MISSILE_INTERCEPTOR_TOTAL_VARIABLES[slot]
    phase_variable = MISSILE_EXPLOSION_PHASE_VARIABLES[slot]
    tick_variable = MISSILE_EXPLOSION_TICK_VARIABLES[slot]
    cell_variable = MISSILE_EXPLOSION_CELL_VARIABLES[slot]
    head_cell_variable = MISSILE_INTERCEPTOR_HEAD_CELL_VARIABLES[slot]
    trail_variables = MISSILE_TRAIL_CELL_VARIABLES[slot]
    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(active_variable, 1, "done")
    for _pixel in range(MISSILE_INTERCEPTOR_PIXEL_SPEED):
        routine.emit(_increment_variable(step_variable))
        routine.jump_if_variables_equal(step_variable, total_variable, "detonate")
    routine.emit(
        _set_variable_s16(
            y_variable,
            (MISSILE_GROUND_ROW - 1) * NUKE_TILE_SIZE,
        )
        + _set_variable_s16(
            NUKE_TEMP_1_VARIABLE,
            (MISSILE_GROUND_ROW - 1) * NUKE_TILE_SIZE,
        )
        + _variable_math(
            0x39,
            NUKE_TEMP_1_VARIABLE,
            target_y_variable,
            operand_is_variable=True,
        )
        + _variable_math(
            0xDE,
            NUKE_TEMP_1_VARIABLE,
            step_variable,
            operand_is_variable=True,
        )
        + _variable_math(
            0xDF,
            NUKE_TEMP_1_VARIABLE,
            total_variable,
            operand_is_variable=True,
        )
        + _variable_math(
            0x39,
            y_variable,
            NUKE_TEMP_1_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(NUKE_TEMP_0_VARIABLE, target_x_variable)
        + _variable_math(
            0x39,
            NUKE_TEMP_0_VARIABLE,
            MISSILE_BATTERY_COLUMN * NUKE_TILE_SIZE,
        )
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            step_variable,
            operand_is_variable=True,
        )
        + _variable_math(
            0xDF,
            NUKE_TEMP_0_VARIABLE,
            total_variable,
            operand_is_variable=True,
        )
        + _set_variable_s16(
            x_variable,
            MISSILE_BATTERY_COLUMN * NUKE_TILE_SIZE,
        )
        + _variable_math(
            0x38,
            x_variable,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _missile_pixel_xy_to_cell_body(x_variable, y_variable)
    )
    routine.jump_if_variables_equal(
        MISSILE_LOGIC_CELL_VARIABLE,
        head_cell_variable,
        "done",
    )
    # Publish only after the three-pixel DDA advance.  The old grid-aligned
    # missile cell becomes the hot exhaust, the retained exhaust shifts toward
    # dim, and the new cell owns the distinct interceptor sprite.  Rendering
    # remains snapped to the 6x6 board phase even though collision motion keeps
    # its smooth three-pixel cadence.
    routine.emit(
        _copy_variable(
            MISSILE_TRAIL_DIRTY_CELL_VARIABLES[slot],
            trail_variables[-1],
        )
        + _copy_variable(trail_variables[2], trail_variables[1])
        + _copy_variable(trail_variables[1], trail_variables[0])
        + _copy_variable(trail_variables[0], head_cell_variable)
        + _copy_variable(head_cell_variable, MISSILE_LOGIC_CELL_VARIABLE)
    )
    routine.jump("done")

    routine.label("detonate")
    routine.emit(
        _set_variable_s16(active_variable, 0)
        + _set_var_bit(MISSILE_TRAIL_CLEAR_VARIABLE, slot)
        + _copy_variable(
            MISSILE_TRAIL_DIRTY_CELL_VARIABLES[slot],
            head_cell_variable,
        )
        + _set_variable_s16(phase_variable, 1)
        + _set_variable_s16(tick_variable, MISSILE_EXPLOSION_DELAY)
        + _copy_variable(
            cell_variable,
            MISSILE_BLAST_GRID_Y_VARIABLES[slot],
        )
        + _variable_math(0xDE, cell_variable, NUKE_GRID_WIDTH)
        + _variable_math(
            0x38,
            cell_variable,
            MISSILE_BLAST_GRID_X_VARIABLES[slot],
            operand_is_variable=True,
        )
        + b"\x74"
        + _immediate(MISSILE_SOUND_EXPLOSION)
    )
    routine.label("done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_blast_slot_worker_body(
    base: int,
    slot: int,
    *,
    draw_cell_pc: int,
    erase_cell_pc: int,
) -> bytes:
    """Advance one compact five-beat blast without a scheduler yield."""

    if not 0 <= slot < len(MISSILE_BLAST_PHASE_VARIABLES):
        raise DungeonBuildError(f"Missile blast worker slot is invalid: {slot}")
    phase_variable = MISSILE_BLAST_PHASE_VARIABLES[slot]
    tick_variable = MISSILE_BLAST_TICK_VARIABLES[slot]
    cell_variable = MISSILE_BLAST_CELL_VARIABLES[slot]
    routine = _RoutineBuilder(base)
    # Only blasts present in e16's frame-start snapshot age this frame. A
    # player detonation or chain claim therefore receives the same full delay
    # regardless of which owner entity created it.
    routine.jump_if_equal(
        MISSILE_BLAST_PHASE_SNAPSHOT_VARIABLES[slot],
        0,
        "done",
    )
    routine.jump_if_equal(phase_variable, 0, "done")
    routine.emit(_decrement_variable(tick_variable))
    routine.jump_if_not_equal(tick_variable, 0, "done")
    routine.emit(
        _set_variable_s16(tick_variable, MISSILE_EXPLOSION_DELAY)
        + _increment_variable(phase_variable)
    )
    for phase in range(2, 7):
        routine.jump_if_equal(phase_variable, phase, f"phase_{phase}")
    routine.emit(_set_variable_s16(phase_variable, 0))
    routine.jump("done")
    routine.label("phase_2")
    routine.jump("done")
    routine.label("phase_3")
    routine.jump("done")
    routine.label("phase_4")
    routine.jump("done")
    routine.label("phase_5")
    # Phase five visibly contracts from the five-cell cross to its center.
    # Owners run before every compositor, so restoring the four arms here is
    # repaired by e24/e25/e27 if another live object shares one of those cells.
    for offset in MISSILE_BLAST_CROSS_OFFSETS:
        routine.emit(_missile_erase_offset_body(cell_variable, offset, erase_cell_pc))
    routine.jump("done")
    routine.label("phase_6")
    routine.emit(_missile_erase_offset_body(cell_variable, 0, erase_cell_pc))
    routine.emit(_set_variable_s16(phase_variable, 0))
    routine.label("done")
    routine.emit(b"\x0D")
    return routine.finish()


def _missile_slot_worker_body(
    base: int,
    *,
    enemy_worker_pc: int,
    blast_worker_pc: int,
    interceptor_worker_pc: int | None,
) -> bytes:
    """Run one enemy/blast pair, plus its paired player ABM when present."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "done")
    routine.emit(
        b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS
        + _call(enemy_worker_pc)
    )
    if interceptor_worker_pc is not None:
        routine.emit(_call(interceptor_worker_pc))
    routine.emit(_call(blast_worker_pc))
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _missile_redraw_one_blast(
    routine: _RoutineBuilder,
    *,
    label_prefix: str,
    phase_variable: int,
    cell_variable: int,
    draw_cell_pc: int,
    done_label: str,
) -> None:
    """Append one mutually exclusive current-phase blast redraw."""

    def draw_offset(offset: int) -> bytes:
        output = bytearray(_copy_variable(NUKE_DRAW_CELL_VARIABLE, cell_variable))
        if offset:
            output.extend(_variable_math(0x38, NUKE_DRAW_CELL_VARIABLE, offset))
        output.extend(_call(draw_cell_pc))
        return bytes(output)

    # The source tile is invariant across the compact cross.  Phase one is the
    # center, phases two through four add four arms, and phase five contracts
    # to the center again.  Collision consumes the same phase table.
    routine.emit(_nuke_set_tile_source_body("explosion") + draw_offset(0))
    routine.jump_if_equal(phase_variable, 1, done_label)
    routine.jump_if_equal(phase_variable, 5, done_label)
    for offset in MISSILE_BLAST_CROSS_OFFSETS:
        routine.emit(draw_offset(offset))
    routine.jump(done_label)


def _missile_player_redraw_worker_body(
    base: int,
    *,
    draw_cell_pc: int,
    erase_cell_pc: int,
    draw_interceptor_pc: int,
) -> bytes:
    """Restore cleanup, then draw a missile with three exhaust cells or a blast."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "done")
    routine.emit(b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS)
    routine.jump_if_equal(
        MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
        MISSILE_TRAIL_EMPTY,
        "cursor_clean",
    )
    routine.emit(
        _copy_variable(
            NUKE_DRAW_CELL_VARIABLE,
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
        )
        + _call(erase_cell_pc)
        + _set_variable_s16(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_TRAIL_EMPTY,
        )
    )
    routine.label("cursor_clean")

    for slot in range(len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES)):
        cleanup_allowed = f"player_{slot}_cleanup_allowed"
        cleanup_done = f"player_{slot}_cleanup_done"
        # Moving ABMs have phase zero; a detonation publishes phase one in
        # the same owner worker that publishes its final trail cleanup.  Once
        # a blast has expanded beyond phase one no stale player pixels can
        # legally remain, so bypass the cleanup blitters entirely.  Besides
        # documenting that state invariant, this keeps even a corrupted
        # phase/dirty combination below the renderer's hard 1024-op guard.
        routine.jump_if_equal(
            MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            0,
            cleanup_allowed,
        )
        routine.jump_if_equal(
            MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            1,
            cleanup_allowed,
        )
        routine.jump(cleanup_done)
        routine.label(cleanup_allowed)
        trail_clean = f"player_{slot}_trail_clean"
        routine.jump_if_bit_clear(
            MISSILE_TRAIL_CLEAR_VARIABLE,
            1 << slot,
            trail_clean,
        )
        for trail_index, trail_variable in enumerate(
            MISSILE_TRAIL_CELL_VARIABLES[slot]
        ):
            clear_next = f"player_{slot}_clear_{trail_index}_next"
            routine.jump_if_equal(trail_variable, MISSILE_TRAIL_EMPTY, clear_next)
            routine.emit(
                _copy_variable(NUKE_DRAW_CELL_VARIABLE, trail_variable)
                + _call(erase_cell_pc)
                + _set_variable_s16(trail_variable, MISSILE_TRAIL_EMPTY)
            )
            routine.label(clear_next)
        routine.emit(_clear_var_bit(MISSILE_TRAIL_CLEAR_VARIABLE, slot))
        routine.label(trail_clean)
        dirty_clean = f"player_{slot}_dirty_clean"
        routine.jump_if_equal(
            MISSILE_TRAIL_DIRTY_CELL_VARIABLES[slot],
            MISSILE_TRAIL_EMPTY,
            dirty_clean,
        )
        routine.emit(
            _copy_variable(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_TRAIL_DIRTY_CELL_VARIABLES[slot],
            )
            + _call(erase_cell_pc)
            + _set_variable_s16(
                MISSILE_TRAIL_DIRTY_CELL_VARIABLES[slot],
                MISSILE_TRAIL_EMPTY,
            )
        )
        routine.label(dirty_clean)
        routine.label(cleanup_done)

    # Compose every exhaust plume before any missile body.  This prevents a
    # later slot's opaque, phase-matched trail tile from hiding an earlier
    # slot's interceptor when two center-launched shots cross the same cell.
    trail_tiles = ("trail_hot", "trail_bright", "trail_dim")
    for slot in range(len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES)):
        next_label = f"player_{slot}_exhaust_next"
        routine.jump_if_not_equal(
            MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            0,
            next_label,
        )
        routine.jump_if_not_equal(
            MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[slot],
            1,
            next_label,
        )
        for trail_index in reversed(range(MISSILE_TRAIL_LENGTH)):
            trail_variable = MISSILE_TRAIL_CELL_VARIABLES[slot][trail_index]
            trail_next = f"player_{slot}_trail_{trail_index}_next"
            routine.jump_if_equal(trail_variable, MISSILE_TRAIL_EMPTY, trail_next)
            routine.emit(
                _copy_variable(NUKE_DRAW_CELL_VARIABLE, trail_variable)
                + _nuke_set_tile_source_body(trail_tiles[trail_index])
                + _call(draw_cell_pc)
            )
            routine.label(trail_next)
        routine.label(next_label)

    # Draw all active missile bodies in a second pass so every three-cell plume
    # remains behind a crisp, existing interceptor sprite.  Its helper copies
    # only the exact 3x5 foreground silhouette, never baked background grain.
    for slot in range(len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES)):
        next_label = f"player_{slot}_head_next"
        routine.jump_if_not_equal(
            MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            0,
            next_label,
        )
        routine.jump_if_not_equal(
            MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[slot],
            1,
            next_label,
        )
        routine.emit(
            _copy_variable(
                NUKE_DRAW_CELL_VARIABLE,
                MISSILE_INTERCEPTOR_HEAD_CELL_VARIABLES[slot],
            )
            + _call(draw_interceptor_pc)
        )
        routine.label(next_label)

    # Player fireballs are a distinct final layer and are the only time the
    # explosion tile is selected by this compositor.
    for slot in range(len(MISSILE_EXPLOSION_PHASE_VARIABLES)):
        next_label = f"player_{slot}_blast_next"
        routine.jump_if_equal(
            MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            0,
            next_label,
        )
        _missile_redraw_one_blast(
            routine,
            label_prefix=f"player_{slot}",
            phase_variable=MISSILE_EXPLOSION_PHASE_VARIABLES[slot],
            cell_variable=MISSILE_EXPLOSION_CELL_VARIABLES[slot],
            draw_cell_pc=draw_cell_pc,
            done_label=next_label,
        )
        routine.label(next_label)
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _missile_chain_redraw_worker_body(
    base: int,
    *,
    draw_cell_pc: int,
) -> bytes:
    """Redraw all three chain blasts after their independently owned updates."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "done")
    routine.emit(b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS)
    for slot in range(MISSILE_CHAIN_EXPLOSION_COUNT):
        next_label = f"chain_{slot}_next"
        phase_variable = MISSILE_CHAIN_EXPLOSION_PHASE_VARIABLES[slot]
        routine.jump_if_equal(phase_variable, 0, next_label)
        _missile_redraw_one_blast(
            routine,
            label_prefix=f"chain_{slot}",
            phase_variable=phase_variable,
            cell_variable=MISSILE_CHAIN_EXPLOSION_CELL_VARIABLES[slot],
            draw_cell_pc=draw_cell_pc,
            done_label=next_label,
        )
        routine.label(next_label)
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _missile_refresh_worker_body(
    base: int,
    *,
    missile_terrain_pc: int,
    missile_hud_pc: int,
) -> bytes:
    """Consume coalesced terrain/HUD damage without stalling simulation."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "done")
    routine.emit(b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS)
    routine.jump_if_equal(MISSILE_TERRAIN_DIRTY_VARIABLE, 0, "hud")
    routine.emit(
        _call(missile_terrain_pc)
        + _set_variable_s16(MISSILE_TERRAIN_DIRTY_VARIABLE, 0)
    )
    routine.label("hud")
    routine.jump_if_equal(MISSILE_PLAYER_DIRTY_VARIABLE, 0, "done")
    routine.emit(
        _call(missile_hud_pc)
        + _set_variable_s16(MISSILE_PLAYER_DIRTY_VARIABLE, 0)
    )
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _missile_cursor_worker_body(
    base: int,
    *,
    draw_cell_pc: int,
    draw_pixel_pc: int,
) -> bytes:
    """Recompose every enemy point, draw the cursor, and publish completion."""

    routine = _RoutineBuilder(base)
    routine.jump_if_not_equal(MISSILE_ACTIVE_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_RUN_VARIABLE, 1, "done")
    routine.jump_if_not_equal(MISSILE_PAUSED_VARIABLE, 0, "done")
    routine.emit(b"\xC6" * MISSILE_WORKER_CYCLE_BOOSTERS)

    # All slot-owner erases and both blast compositors have finished.  Draw
    # every retained red point first so overlapping enemy heads can then be
    # repaired white in one final pass.
    for slot, active_variable in enumerate(MISSILE_ENEMY_ACTIVE_VARIABLES):
        inactive_label = f"enemy_{slot}_trail_inactive"
        routine.jump_if_not_equal(active_variable, 1, inactive_label)
        for trail_index in reversed(range(MISSILE_ENEMY_TRAIL_LENGTH)):
            trail_x_variable = MISSILE_ENEMY_TRAIL_X_VARIABLES[slot][trail_index]
            trail_y_variable = MISSILE_ENEMY_TRAIL_Y_VARIABLES[slot][trail_index]
            next_label = f"enemy_{slot}_trail_{trail_index}_next"
            routine.jump_if_equal(
                trail_x_variable,
                MISSILE_TRAIL_EMPTY,
                next_label,
            )
            routine.emit(
                _missile_draw_pixel_at_body(
                    trail_x_variable,
                    trail_y_variable,
                    "enemy_trail",
                    draw_pixel_pc,
                )
            )
            routine.label(next_label)
        routine.label(inactive_label)

    for slot, active_variable in enumerate(MISSILE_ENEMY_ACTIVE_VARIABLES):
        next_label = f"enemy_{slot}_next"
        routine.jump_if_not_equal(active_variable, 1, next_label)
        routine.emit(
            _missile_draw_pixel_at_body(
                MISSILE_ENEMY_X_VARIABLES[slot],
                MISSILE_ENEMY_Y_VARIABLES[slot],
                "warhead",
                draw_pixel_pc,
            )
        )
        routine.label(next_label)
    routine.emit(
        _nuke_draw_variable_cell_body(
            MISSILE_CURSOR_CELL_VARIABLE,
            "cursor",
            draw_cell_pc,
        )
        + _set_variable_s16(MISSILE_WAVE_COMPLETE_VARIABLE, 0)
    )
    routine.jump_if_variables_not_equal(
        MISSILE_SPAWNED_VARIABLE,
        MISSILE_WAVE_QUOTA_VARIABLE,
        "done",
    )
    routine.jump_if_not_equal(MISSILE_ACTIVE_ENEMIES_VARIABLE, 0, "done")
    for active_variable in MISSILE_INTERCEPTOR_ACTIVE_VARIABLES:
        routine.jump_if_not_equal(active_variable, 0, "done")
    for phase_variable in MISSILE_BLAST_PHASE_VARIABLES:
        routine.jump_if_not_equal(phase_variable, 0, "done")
    routine.emit(_set_variable_s16(MISSILE_WAVE_COMPLETE_VARIABLE, 1))
    routine.label("done")
    routine.emit(b"\x00")
    return routine.finish()


def _nuke_teardown_body(screen_entity: int) -> bytes:
    """Leave the remote console plane and restore every field control mode."""

    return (
        _facility_video_screen_fade_body(0xFF, 20)
        + b"\x25"
        + bytes((screen_entity,))
        + _historical_camera_release_body()
        + b"\xFE\x65\x00\x80\x01\x80"
        + _facility_video_screen_fade_body(0, 20)
        + b"\xFE\xE0\x00"
        + _actor_dialog_reset_body()
        + b"\xFE\x53\x00"
    )


def _nuke_terminal_action(
    nuke_game: DefenseArchiveNukeGame,
    missile_game: DefenseArchiveMissileCommandGame,
    video_event: DefenseArchiveVideoEvent,
    routine_pc: int,
    *,
    cell_to_vram_pc: int,
    draw_cell_pc: int,
    erase_cell_pc: int,
    digit_pc: int,
    letter_pc: int,
    hud_pc: int,
    panel_fill_pc: int,
    spawn_target_pc: int,
    setup_round_pc: int,
    name_draw_pc: int,
    missile_hud_pc: int,
    missile_terrain_pc: int,
    missile_setup_wave_pc: int,
    missile_setup_game_pc: int,
) -> bytes:
    """Build the shared arcade/video console and both complete game loops."""

    if (
        nuke_game.terminal_entity != video_event.computer_entity
        or missile_game.terminal_entity != nuke_game.terminal_entity
        or nuke_game.screen_entity != FACILITY_VIDEO_SCREEN_ENTITY
        or nuke_game.screen_entity != video_event.screen_entity
    ):
        raise DungeonBuildError(
            "Nuke must share the audited Video Disk computer and screen plane"
        )

    cancel_mask = PAD_MASK_CIRCLE
    menu_mask = PAD_MASK_CROSS | cancel_mask
    missile_pause_mask = PAD_MASK_TRIANGLE
    missile_intro_mask = PAD_MASK_CROSS | missile_pause_mask
    routine = _RoutineBuilder(routine_pc)

    # Keep the root compact and future-proof: the first choice opens a nested
    # arcade directory, while Video Disk and Leave retain their direct paths.
    routine.label("root_menu")
    routine.emit(_actor_dialog_reset_body() + b"\x33\xFE\x54")
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.emit(_wait() + _choice_dialog(nuke_game.prompt_dialogue))
    routine.emit(b"\xA9\x13\x9C")
    routine.jump_if_equal(0x0014, 2, "video_disk")
    routine.jump_if_not_equal(0x0014, 1, "leave")
    routine.emit(_actor_dialog_reset_body() + b"\x33\xFE\x54")
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.emit(_wait() + _choice_dialog(nuke_game.arcade_prompt_dialogue))
    routine.emit(b"\xA9\x13\x9C")
    routine.jump_if_equal(0x0014, 1, "select_nuke")
    routine.jump_if_equal(0x0014, 2, "select_missile")
    routine.jump("root_menu")

    routine.label("select_nuke")
    routine.emit(_set_variable_s16(MISSILE_OUTCOME_VARIABLE, 0))
    routine.jump("persistence_entry")
    routine.label("select_missile")
    routine.emit(_set_variable_s16(MISSILE_OUTCOME_VARIABLE, 1))

    routine.label("persistence_entry")

    # A signature plus tight value ranges prevents coincidental words in an
    # old retail save from being accepted as an arcade scoreboard.  V1 is the
    # released v129/v130 ten-point Missile layout; migrate it losslessly into
    # V2's split five-point-unit score before performing the common checks.
    routine.jump_if_equal(
        nuke_game.signature_variable,
        NUKE_SIGNATURE,
        "unpack_v2_persistence",
    )
    routine.jump_if_equal(
        nuke_game.signature_variable,
        NUKE_SIGNATURE_V1,
        "migrate_v1_persistence",
    )
    routine.jump("reset_persistence")
    routine.label("migrate_v1_persistence")
    routine.emit(
        _arcade_unpack_v1_records_body(nuke_game, missile_game)
        + _nuke_unpack_initials_body(nuke_game)
        + _missile_pack_records_body(nuke_game, missile_game)
    )
    routine.jump("validate_persistence")
    routine.label("unpack_v2_persistence")
    routine.emit(
        _arcade_unpack_records_body(nuke_game, missile_game)
        + _nuke_unpack_initials_body(nuke_game)
    )
    routine.label("validate_persistence")
    routine.jump_if_signed_less_than(
        nuke_game.high_score_variable,
        0,
        "reset_persistence",
    )
    routine.jump_if_signed_greater_or_equal(
        nuke_game.high_score_variable,
        8931,
        "reset_persistence",
    )
    routine.jump_if_signed_less_than(
        nuke_game.best_level_variable,
        1,
        "reset_persistence",
    )
    routine.jump_if_signed_greater_or_equal(
        nuke_game.best_level_variable,
        20,
        "reset_persistence",
    )
    routine.jump_if_signed_less_than(
        missile_game.high_score_variable,
        0,
        "reset_persistence",
    )
    routine.jump_if_signed_greater_or_equal(
        missile_game.high_score_variable,
        MISSILE_MAX_SCORE_UNITS + 1,
        "reset_persistence",
    )
    routine.jump_if_signed_less_than(
        missile_game.best_wave_variable,
        0,
        "reset_persistence",
    )
    routine.jump_if_signed_greater_or_equal(
        missile_game.best_wave_variable,
        MISSILE_MAX_WAVE + 1,
        "reset_persistence",
    )
    for name_variable in (
        NUKE_NAME_0_VARIABLE,
        NUKE_NAME_1_VARIABLE,
        NUKE_NAME_2_VARIABLE,
        NUKE_NAME_3_VARIABLE,
    ):
        routine.jump_if_signed_greater_or_equal(
            name_variable,
            26,
            "reset_persistence",
        )
    routine.jump("persistence_ready")

    routine.label("reset_persistence")
    routine.emit(
        _set_variable_s16(nuke_game.high_score_variable, 0)
        + _set_variable_s16(
            nuke_game.initials_packed_variable,
            NUKE_DEFAULT_INITIALS_PACKED,
        )
        + _set_variable_s16(
            nuke_game.initial_fourth_variable,
            NUKE_DEFAULT_INITIALS[3],
        )
        + _set_variable_s16(nuke_game.best_level_packed_variable, 1)
        + _set_variable_s16(
            nuke_game.signature_variable,
            NUKE_SIGNATURE,
        )
        + _arcade_unpack_records_body(nuke_game, missile_game)
        + _nuke_unpack_initials_body(nuke_game)
    )
    routine.label("persistence_ready")

    # Disable the engine's native Start menu before the atlas occupies its
    # scratch page.  Every in-game exit converges on the matching enable.
    routine.emit(
        b"\xFE\xE0\x01"
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + b"\xFE\x65\x46\x80\x01\x80"
        + _facility_video_screen_fade_body(0xFF, 20)
        + _facility_video_screen_camera_body()
        + b"\x25"
        + bytes((nuke_game.screen_entity,))
        + _nuke_load_tim_body(
            nuke_game.background_file_id,
            NUKE_LIVE_VRAM_ORIGIN,
        )
        + _nuke_load_tim_body(
            nuke_game.atlas_file_id,
            (NUKE_ATLAS_VRAM_X, NUKE_ATLAS_VRAM_Y),
        )
    )
    routine.jump_if_equal(
        MISSILE_OUTCOME_VARIABLE,
        1,
        "missile_intro_render",
    )
    routine.emit(
        _set_variable_s16(NUKE_SCORE_VARIABLE, 0)
        + _set_variable_s16(NUKE_LEVEL_VARIABLE, 1)
        + _set_variable_s16(NUKE_LEVEL_TARGETS_VARIABLE, 0)
        + _call(hud_pc)
        + _call(panel_fill_pc)
        + _nuke_centered_text_body("NUKE", 47)
        + _nuke_centered_text_body("----------------------", 56)
        + _nuke_static_text_body("D-PAD", 101, 67)
        + _nuke_static_text_body("STEER", 176, 67)
        + _nuke_static_text_body("CROSS", 101, 76)
        + _nuke_static_text_body("LAUNCH/PAUSE", 166, 76)
        + _nuke_static_text_body("CIRCLE", 101, 85)
        + _nuke_static_text_body("EXIT", 176, 85)
        + _nuke_centered_text_body("----------------------", 94)
        + _nuke_static_text_body("RECORD", 101, 103)
        + _nuke_draw_number_body(
            nuke_game.high_score_variable,
            5,
            176,
            103,
            digit_pc,
        )
        + _nuke_static_text_body("PILOT", 101, 112)
        + _nuke_unpack_initials_body(nuke_game)
        + _nuke_draw_initials_body(letter_pc, 176, 112)
        + _nuke_static_text_body("LV", 202, 112)
        + _nuke_draw_number_body(
            nuke_game.best_level_variable,
            2,
            216,
            112,
            digit_pc,
        )
        + b"\x24"
        + bytes((nuke_game.screen_entity,))
        + _facility_video_screen_fade_body(0, 20)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(menu_mask, release_pc))

    routine.label("intro_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "intro_check_launch")
    routine.jump("exit_game")
    routine.label("intro_check_launch")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "intro_loop")
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.emit(
        b"\x74"
        + _immediate(NUKE_SOUND_LAUNCH)
        + _call(setup_round_pc)
    )
    routine.jump("frame_loop")

    # Poll every video frame instead of blocking for the movement delay. This
    # preserves quick D-pad taps and queues exactly one legal turn per tick.
    routine.label("frame_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "frame_check_pause")
    routine.jump("exit_game")
    routine.label("frame_check_pause")
    # Start is reserved by the field engine before actor bytecode can consume
    # it. Cross is otherwise idle during flight, so it reliably provides the
    # launch/pause/resume action on both real hardware and emulators.
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "direction_up")
    routine.jump("pause_game")

    routine.label("direction_up")
    routine.jump_if_pad_not_pressed(PAD_MASK_UP, "direction_right")
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_DOWN,
        "direction_right",
    )
    routine.emit(
        _set_variable_s16(
            NUKE_QUEUED_DIRECTION_VARIABLE,
            NUKE_DIRECTION_UP,
        )
    )
    routine.jump("direction_done")

    routine.label("direction_right")
    routine.jump_if_pad_not_pressed(PAD_MASK_RIGHT, "direction_down")
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_LEFT,
        "direction_down",
    )
    routine.emit(
        _set_variable_s16(
            NUKE_QUEUED_DIRECTION_VARIABLE,
            NUKE_DIRECTION_RIGHT,
        )
    )
    routine.jump("direction_done")

    routine.label("direction_down")
    routine.jump_if_pad_not_pressed(PAD_MASK_DOWN, "direction_left")
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_UP,
        "direction_left",
    )
    routine.emit(
        _set_variable_s16(
            NUKE_QUEUED_DIRECTION_VARIABLE,
            NUKE_DIRECTION_DOWN,
        )
    )
    routine.jump("direction_done")

    routine.label("direction_left")
    routine.jump_if_pad_not_pressed(PAD_MASK_LEFT, "direction_done")
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_RIGHT,
        "direction_done",
    )
    routine.emit(
        _set_variable_s16(
            NUKE_QUEUED_DIRECTION_VARIABLE,
            NUKE_DIRECTION_LEFT,
        )
    )

    routine.label("direction_done")
    routine.emit(_decrement_variable(NUKE_TICK_VARIABLE))
    routine.jump_if_not_equal(NUKE_TICK_VARIABLE, 0, "frame_loop")
    routine.emit(
        _copy_variable(
            NUKE_TICK_VARIABLE,
            NUKE_TICK_DELAY_VARIABLE,
        )
    )
    routine.jump_if_equal(
        NUKE_QUEUED_DIRECTION_VARIABLE,
        4,
        "direction_applied",
    )
    routine.emit(
        _copy_variable(
            NUKE_DIRECTION_VARIABLE,
            NUKE_QUEUED_DIRECTION_VARIABLE,
        )
    )
    routine.label("direction_applied")
    routine.emit(
        _set_variable_s16(NUKE_QUEUED_DIRECTION_VARIABLE, 4)
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _copy_variable(
            NUKE_DRAW_CELL_VARIABLE,
            NUKE_HEAD_CELL_VARIABLE,
        )
        + _call(cell_to_vram_pc)
    )

    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_RIGHT,
        "move_right",
    )
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_DOWN,
        "move_down",
    )
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_LEFT,
        "move_left",
    )
    routine.jump("move_up")

    routine.label("move_right")
    routine.jump_if_equal(NUKE_COLUMN_VARIABLE, NUKE_GRID_WIDTH - 1, "crash")
    routine.emit(_increment_variable(NUKE_HEAD_CELL_VARIABLE))
    routine.jump("moved")

    routine.label("move_down")
    routine.jump_if_equal(NUKE_ROW_VARIABLE, NUKE_GRID_HEIGHT - 1, "crash")
    routine.emit(
        _variable_math(
            0x38,
            NUKE_HEAD_CELL_VARIABLE,
            NUKE_GRID_WIDTH,
        )
    )
    routine.jump("moved")

    routine.label("move_left")
    routine.jump_if_equal(NUKE_COLUMN_VARIABLE, 0, "crash")
    routine.emit(_decrement_variable(NUKE_HEAD_CELL_VARIABLE))
    routine.jump("moved")

    routine.label("move_up")
    routine.jump_if_equal(NUKE_ROW_VARIABLE, 0, "crash")
    routine.emit(
        _variable_math(
            0x39,
            NUKE_HEAD_CELL_VARIABLE,
            NUKE_GRID_WIDTH,
        )
    )

    # Capture the current tip before shifting. Active rounds end immediately
    # on reaching length 96, so lengths 4..95 are the complete legal set.
    routine.label("moved")
    for length in range(NUKE_INITIAL_LENGTH, NUKE_MAX_LENGTH):
        routine.jump_if_equal(
            NUKE_LENGTH_VARIABLE,
            length,
            f"tip_length_{length}",
        )
    routine.jump("crash")
    for length in range(NUKE_INITIAL_LENGTH, NUKE_MAX_LENGTH):
        routine.label(f"tip_length_{length}")
        routine.emit(
            _copy_variable(
                NUKE_TIP_CELL_VARIABLE,
                NUKE_TAIL_VARIABLES[length - 1],
            )
        )
        routine.jump("tip_ready")

    routine.label("tip_ready")
    for index in range(NUKE_MAX_LENGTH - 1, 0, -1):
        routine.emit(
            _copy_variable(
                NUKE_TAIL_VARIABLES[index],
                NUKE_TAIL_VARIABLES[index - 1],
            )
        )
    routine.emit(
        _copy_variable(
            NUKE_TAIL_VARIABLES[0],
            NUKE_HEAD_CELL_VARIABLE,
        )
    )

    # Only body slots 1..length-1 collide. The old tip now sits just beyond
    # that active range, making a legal turn into the cell it vacated possible.
    for index in range(1, NUKE_MAX_LENGTH):
        routine.jump_if_signed_less_than(
            NUKE_LENGTH_VARIABLE,
            index + 1,
            "collision_clear",
        )
        routine.jump_if_variables_equal(
            NUKE_HEAD_CELL_VARIABLE,
            NUKE_TAIL_VARIABLES[index],
            "crash",
        )
    routine.label("collision_clear")
    routine.jump_if_variables_equal(
        NUKE_HEAD_CELL_VARIABLE,
        NUKE_TARGET_CELL_VARIABLE,
        "target_hit",
    )

    routine.emit(
        _copy_variable(
            NUKE_DRAW_CELL_VARIABLE,
            NUKE_TIP_CELL_VARIABLE,
        )
        + _call(erase_cell_pc)
    )
    routine.jump("draw_moved_nuke")

    routine.label("target_hit")
    routine.emit(
        _copy_variable(NUKE_TEMP_0_VARIABLE, NUKE_LEVEL_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            NUKE_POINTS_PER_LEVEL,
        )
        + _variable_math(
            0x38,
            NUKE_SCORE_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _increment_variable(NUKE_LENGTH_VARIABLE)
        + _increment_variable(NUKE_LEVEL_TARGETS_VARIABLE)
        + b"\x74"
        + _immediate(NUKE_SOUND_LAUNCH)
    )
    routine.jump_if_not_equal(
        NUKE_LEVEL_TARGETS_VARIABLE,
        NUKE_TARGETS_PER_LEVEL,
        "target_level_done",
    )
    routine.emit(
        _set_variable_s16(NUKE_LEVEL_TARGETS_VARIABLE, 0)
        + _increment_variable(NUKE_LEVEL_VARIABLE)
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
    )
    routine.jump_if_equal(
        NUKE_TICK_DELAY_VARIABLE,
        NUKE_MINIMUM_TICK_DELAY,
        "target_level_done",
    )
    routine.emit(_decrement_variable(NUKE_TICK_DELAY_VARIABLE))

    routine.label("target_level_done")
    # Split the worst-case 94-cell growth scan across one deliberate eat
    # frame before the HUD refresh.  Besides giving the hit a readable beat,
    # this keeps both scheduled halves comfortably below EVENTLOOP's soft
    # cycle budget (and its absolute 1024-instruction guard).
    routine.emit(
        _yield_tick()
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(hud_pc)
    )
    routine.jump_if_signed_greater_or_equal(
        NUKE_LENGTH_VARIABLE,
        NUKE_MAX_LENGTH,
        "mission_complete",
    )
    routine.emit(_call(spawn_target_pc))
    routine.jump("draw_moved_nuke")

    routine.label("mission_complete")
    routine.emit(_set_variable_s16(NUKE_OUTCOME_VARIABLE, 2))

    routine.label("draw_moved_nuke")
    routine.emit(
        _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[3],
            "trail_dim",
            draw_cell_pc,
        )
        + _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[2],
            "trail_bright",
            draw_cell_pc,
        )
        + _nuke_draw_variable_cell_body(
            NUKE_TAIL_VARIABLES[1],
            "trail_hot",
            draw_cell_pc,
        )
    )
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_RIGHT,
        "draw_head_right",
    )
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_DOWN,
        "draw_head_down",
    )
    routine.jump_if_equal(
        NUKE_DIRECTION_VARIABLE,
        NUKE_DIRECTION_LEFT,
        "draw_head_left",
    )
    routine.jump("draw_head_up")

    for direction_name, tile_name in (
        ("right", "head_right"),
        ("down", "head_down"),
        ("left", "head_left"),
        ("up", "head_up"),
    ):
        routine.label(f"draw_head_{direction_name}")
        routine.emit(
            _nuke_draw_variable_cell_body(
                NUKE_HEAD_CELL_VARIABLE,
                tile_name,
                draw_cell_pc,
            )
        )
        routine.jump("head_drawn")

    routine.label("head_drawn")
    routine.jump_if_equal(
        NUKE_OUTCOME_VARIABLE,
        2,
        "mission_animation",
    )
    routine.jump("frame_loop")

    routine.label("mission_animation")
    routine.emit(
        b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _wait(18)
    )
    routine.jump("finish_round")

    routine.label("crash")
    routine.emit(
        _nuke_draw_variable_cell_body(
            NUKE_HEAD_CELL_VARIABLE,
            "explosion",
            draw_cell_pc,
        )
        + b"\x74"
        + _immediate(NUKE_SOUND_EXPLOSION)
        + _wait(18)
    )

    routine.label("finish_round")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _set_variable_s16(NUKE_ACTIVE_VARIABLE, 0)
    )
    routine.jump_if_not_signed_greater_than(
        NUKE_LEVEL_VARIABLE,
        nuke_game.best_level_variable,
        "best_level_done",
    )
    routine.emit(
        _copy_variable(
            nuke_game.best_level_variable,
            NUKE_LEVEL_VARIABLE,
        )
        + _nuke_pack_best_level_body(nuke_game)
    )
    routine.label("best_level_done")
    routine.jump_if_not_signed_greater_than(
        NUKE_SCORE_VARIABLE,
        nuke_game.high_score_variable,
        "score_entry_done",
    )
    routine.emit(
        _copy_variable(
            nuke_game.high_score_variable,
            NUKE_SCORE_VARIABLE,
        )
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _nuke_unpack_initials_body(nuke_game)
        + _set_variable_s16(NUKE_NAME_POSITION_VARIABLE, 0)
        + _call(name_draw_pc)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(menu_mask | PAD_MASK_UP | PAD_MASK_DOWN | PAD_MASK_LEFT | PAD_MASK_RIGHT, release_pc))

    routine.label("name_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(PAD_MASK_UP, "name_check_down")
    routine.jump("name_up")
    routine.label("name_check_down")
    routine.jump_if_pad_not_pressed(PAD_MASK_DOWN, "name_check_left")
    routine.jump("name_down")
    routine.label("name_check_left")
    routine.jump_if_pad_not_pressed(PAD_MASK_LEFT, "name_check_right")
    routine.jump("name_left")
    routine.label("name_check_right")
    routine.jump_if_pad_not_pressed(PAD_MASK_RIGHT, "name_check_cross")
    routine.jump("name_right")
    routine.label("name_check_cross")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "name_check_commit")
    routine.jump("name_cross")
    routine.label("name_check_commit")
    routine.jump_if_pad_not_pressed(PAD_MASK_CIRCLE, "name_loop")
    routine.jump("name_left")

    name_variables = (
        NUKE_NAME_0_VARIABLE,
        NUKE_NAME_1_VARIABLE,
        NUKE_NAME_2_VARIABLE,
        NUKE_NAME_3_VARIABLE,
    )
    routine.label("name_up")
    for index in range(4):
        routine.jump_if_equal(
            NUKE_NAME_POSITION_VARIABLE,
            index,
            f"name_up_{index}",
        )
    routine.jump("name_loop")
    for index, name_variable in enumerate(name_variables):
        routine.label(f"name_up_{index}")
        routine.emit(_increment_variable(name_variable))
        routine.jump_if_signed_less_than(name_variable, 26, "name_changed")
        routine.emit(_set_variable_s16(name_variable, 0))
        routine.jump("name_changed")

    routine.label("name_down")
    for index in range(4):
        routine.jump_if_equal(
            NUKE_NAME_POSITION_VARIABLE,
            index,
            f"name_down_{index}",
        )
    routine.jump("name_loop")
    for index, name_variable in enumerate(name_variables):
        routine.label(f"name_down_{index}")
        routine.jump_if_equal(name_variable, 0, f"name_down_wrap_{index}")
        routine.emit(_decrement_variable(name_variable))
        routine.jump("name_changed")
        routine.label(f"name_down_wrap_{index}")
        routine.emit(_set_variable_s16(name_variable, 25))
        routine.jump("name_changed")

    routine.label("name_left")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 0, "name_loop")
    routine.emit(_decrement_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("name_changed")

    routine.label("name_right")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 3, "name_loop")
    routine.emit(_increment_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("name_changed")

    routine.label("name_cross")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 3, "name_commit")
    routine.emit(_increment_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("name_changed")

    routine.label("name_changed")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _call(name_draw_pc)
        + _wait(4)
    )
    routine.jump("name_loop")

    routine.label("name_commit")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _nuke_pack_initials_body(nuke_game)
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(menu_mask | PAD_MASK_UP | PAD_MASK_DOWN | PAD_MASK_LEFT | PAD_MASK_RIGHT, release_pc))

    routine.label("score_entry_done")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(hud_pc)
        + _call(panel_fill_pc)
    )
    routine.jump_if_equal(
        NUKE_OUTCOME_VARIABLE,
        2,
        "game_over_mission",
    )
    routine.emit(_nuke_centered_text_body("NUKE DESTROYED", 49))
    routine.jump("game_over_common")
    routine.label("game_over_mission")
    routine.emit(_nuke_centered_text_body("MISSION COMPLETE", 49))

    routine.label("game_over_common")
    routine.emit(
        _nuke_centered_text_body("----------------------", 59)
        + _nuke_static_text_body("SCORE", 104, 70)
        + _nuke_draw_number_body(
            NUKE_SCORE_VARIABLE,
            5,
            165,
            70,
            digit_pc,
        )
        + _nuke_static_text_body("LEVEL", 104, 79)
        + _nuke_draw_number_body(
            NUKE_LEVEL_VARIABLE,
            2,
            165,
            79,
            digit_pc,
        )
        + _nuke_static_text_body("BEST", 104, 88)
        + _nuke_draw_number_body(
            nuke_game.high_score_variable,
            5,
            165,
            88,
            digit_pc,
        )
        + _nuke_centered_text_body("----------------------", 98)
        + _nuke_centered_text_body("CROSS RETRY", 109)
        + _nuke_centered_text_body("CIRCLE EXIT", 118)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(menu_mask, release_pc))

    routine.label("game_over_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "game_over_retry")
    routine.jump("exit_game")
    routine.label("game_over_retry")
    routine.jump_if_pad_not_pressed(
        PAD_MASK_CROSS,
        "game_over_loop",
    )
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(
            PAD_MASK_CROSS,
            release_pc,
        )
        + b"\x74"
        + _immediate(NUKE_SOUND_LAUNCH)
        + _call(setup_round_pc)
    )
    routine.jump("frame_loop")

    routine.label("pause_game")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _nuke_fill_screen_rect_body(
            NUKE_HUD_SCREEN_RECT,
            NUKE_PANEL_BACKGROUND_TILE_NAME,
        )
        + _nuke_centered_text_body("GAME PAUSED", 18)
        + _nuke_centered_text_body(
            "CROSS RESUME  CIRCLE EXIT",
            27,
        )
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(PAD_MASK_CROSS, release_pc))
    routine.label("pause_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "pause_check_resume")
    routine.jump("exit_game")
    routine.label("pause_check_resume")
    routine.jump_if_pad_not_pressed(
        PAD_MASK_CROSS,
        "pause_loop",
    )
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(
            PAD_MASK_CROSS,
            release_pc,
        )
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(hud_pc)
    )
    routine.jump("frame_loop")

    # Missile Command shares the remote CRT and low-level blitters, but owns
    # independent state, scoring, waves, collision, and pause/retry flows.
    routine.label("missile_intro_render")
    routine.emit(
        _set_variable_s16(MISSILE_ACTIVE_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
        + _set_variable_s16(MISSILE_RUN_VARIABLE, 0)
        + _set_variable_s16(MISSILE_PAUSED_VARIABLE, 0)
        + _set_variable_s16(
            MISSILE_MODE_ACK_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
        + _set_variable_s16(MISSILE_SCORE_VARIABLE, 0)
        + _set_variable_s16(MISSILE_WAVE_VARIABLE, 1)
        + _set_variable_s16(
            MISSILE_CITIES_VARIABLE,
            len(MISSILE_CITY_COLUMNS),
        )
        + _set_variable_s16(MISSILE_AMMO_VARIABLE, MISSILE_INITIAL_AMMO)
        + _set_variable_s16(
            MISSILE_BATTERY_AMMO_VARIABLES[0],
            MISSILE_BATTERY_AMMO,
        )
        + _call(missile_hud_pc)
        + _call(panel_fill_pc)
        + _nuke_centered_text_body("MISSILE COMMAND", 47)
        + _nuke_centered_text_body("----------------------", 56)
        + _nuke_static_text_body("D-PAD", 101, 67)
        + _nuke_static_text_body("AIM", 176, 67)
        + _nuke_static_text_body("CROSS", 91, 76)
        + _nuke_static_text_body("CENTER FIRE", 166, 76)
        + _nuke_static_text_body("TRIANGLE", 91, 85)
        + _nuke_static_text_body("PAUSE", 176, 85)
        + _nuke_centered_text_body("ONE BASE  30 MISSILES", 98)
        + _nuke_static_text_body("BEST", 91, 108)
        + _missile_draw_score_body(
            missile_game.high_score_variable,
            116,
            108,
            digit_pc,
        )
        + _nuke_static_text_body("WAVE", 171, 108)
        + _nuke_draw_number_body(
            missile_game.best_wave_variable,
            2,
            196,
            108,
            digit_pc,
        )
        + _nuke_centered_text_body("CROSS START  TRIANGLE EXIT", 121)
        + b"\x24"
        + bytes((nuke_game.screen_entity,))
        + _facility_video_screen_fade_body(0, 20)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(missile_intro_mask, release_pc))
    routine.label("missile_intro_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(
        missile_pause_mask,
        "missile_intro_check_launch",
    )
    routine.jump("exit_game")
    routine.label("missile_intro_check_launch")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "missile_intro_loop")
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(PAD_MASK_CROSS, release_pc)
        + b"\x74"
        + _immediate(NUKE_SOUND_LAUNCH)
        + _call(missile_setup_game_pc)
        + _call(missile_setup_wave_pc)
        + _call(missile_terrain_pc)
        + _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_ARMING,
        )
    )
    routine.jump("missile_frame_loop")

    routine.label("missile_frame_loop")
    # Two boosters give the longest pooled-fire plus cursor path 72 soft
    # cycles; its emitted maximum is 53.  The action therefore always reaches
    # the next outer WAIT in one field frame instead of silently carrying a
    # launch calculation into the next scheduler pass.
    routine.emit(
        _yield_tick() + b"\xC6" * MISSILE_INPUT_CYCLE_BOOSTERS
    )
    routine.jump_if_not_equal(
        MISSILE_MODE_ACK_VARIABLE,
        MISSILE_MODE_ARMING,
        "missile_frame_loop",
    )
    routine.jump_if_equal(
        MISSILE_WAVE_COMPLETE_VARIABLE,
        1,
        "missile_request_wave_stop",
    )
    routine.jump_if_pad_not_pressed(missile_pause_mask, "missile_check_fire")
    routine.emit(
        _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_PAUSED,
        )
    )
    routine.jump("missile_pause_wait_ack")

    routine.label("missile_request_wave_stop")
    routine.emit(
        _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
    )
    routine.jump("missile_wave_stop_wait")

    routine.label("missile_check_fire")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "missile_fire_released")
    routine.jump_if_not_equal(
        MISSILE_FIRE_LATCH_VARIABLE,
        0,
        "missile_fire_done",
    )
    routine.emit(_set_variable_s16(MISSILE_FIRE_LATCH_VARIABLE, 1))
    routine.jump_if_equal(
        MISSILE_AMMO_VARIABLE,
        0,
        "missile_fire_done",
    )
    routine.jump_if_equal(
        MISSILE_BATTERY_AMMO_VARIABLES[0],
        0,
        "missile_fire_done",
    )
    for slot in range(len(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES)):
        slot_next_label = f"missile_fire_{slot}_slot_next"
        dx_ready_label = f"missile_fire_{slot}_dx_ready"
        total_ready_label = f"missile_fire_{slot}_total_ready"
        reload_done_label = f"missile_fire_{slot}_reload_done"
        active_variable = MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[slot]
        x_variable = MISSILE_INTERCEPTOR_X_VARIABLES[slot]
        y_variable = MISSILE_INTERCEPTOR_Y_VARIABLES[slot]
        target_x_variable = MISSILE_INTERCEPTOR_TARGET_X_VARIABLES[slot]
        target_y_variable = MISSILE_INTERCEPTOR_TARGET_Y_VARIABLES[slot]
        step_variable = MISSILE_INTERCEPTOR_STEP_VARIABLES[slot]
        total_variable = MISSILE_INTERCEPTOR_TOTAL_VARIABLES[slot]
        interceptor_tick_variable = MISSILE_INTERCEPTOR_TICK_VARIABLES[slot]
        explosion_phase_variable = MISSILE_EXPLOSION_PHASE_VARIABLES[slot]

        routine.jump_if_not_equal(active_variable, 0, slot_next_label)
        routine.jump_if_not_equal(
            explosion_phase_variable,
            0,
            slot_next_label,
        )
        routine.emit(
            _copy_variable(
                target_x_variable,
                MISSILE_CURSOR_COLUMN_VARIABLE,
            )
            + _variable_math(0xDE, target_x_variable, NUKE_TILE_SIZE)
            + _copy_variable(
                target_y_variable,
                MISSILE_CURSOR_ROW_VARIABLE,
            )
            + _variable_math(0xDE, target_y_variable, NUKE_TILE_SIZE)
            + _copy_variable(
                MISSILE_BLAST_GRID_X_VARIABLES[slot],
                MISSILE_CURSOR_COLUMN_VARIABLE,
            )
            + _copy_variable(
                MISSILE_BLAST_GRID_Y_VARIABLES[slot],
                MISSILE_CURSOR_ROW_VARIABLE,
            )
            + _set_variable_s16(
                x_variable,
                MISSILE_BATTERY_COLUMN * NUKE_TILE_SIZE,
            )
            + _set_variable_s16(
                y_variable,
                (MISSILE_GROUND_ROW - 1) * NUKE_TILE_SIZE,
            )
            + _set_variable_s16(step_variable, 0)
            + b"".join(
                _set_variable_s16(variable, MISSILE_TRAIL_EMPTY)
                for variable in MISSILE_TRAIL_CELL_VARIABLES[slot]
            )
            + _set_variable_s16(
                MISSILE_INTERCEPTOR_HEAD_CELL_VARIABLES[slot],
                (MISSILE_GROUND_ROW - 1) * NUKE_GRID_WIDTH
                + MISSILE_BATTERY_COLUMN,
            )
            + _set_variable_s16(
                total_variable,
                (MISSILE_GROUND_ROW - 1) * NUKE_TILE_SIZE,
            )
            + _variable_math(
                0x39,
                total_variable,
                target_y_variable,
                operand_is_variable=True,
            )
            + _copy_variable(NUKE_TEMP_0_VARIABLE, target_x_variable)
            + _variable_math(
                0x39,
                NUKE_TEMP_0_VARIABLE,
                MISSILE_BATTERY_COLUMN * NUKE_TILE_SIZE,
            )
        )
        routine.jump_if_signed_greater_or_equal(
            NUKE_TEMP_0_VARIABLE,
            0,
            dx_ready_label,
        )
        routine.emit(_variable_math(0xDE, NUKE_TEMP_0_VARIABLE, -1))
        routine.label(dx_ready_label)
        routine.jump_if_not_signed_greater_than(
            NUKE_TEMP_0_VARIABLE,
            total_variable,
            total_ready_label,
        )
        routine.emit(
            _copy_variable(total_variable, NUKE_TEMP_0_VARIABLE)
        )
        routine.label(total_ready_label)
        routine.emit(
            _set_variable_s16(active_variable, 1)
            + _set_variable_s16(interceptor_tick_variable, 0)
            + _decrement_variable(MISSILE_BATTERY_AMMO_VARIABLES[0])
            + _decrement_variable(MISSILE_AMMO_VARIABLE)
            + _set_variable_s16(MISSILE_PLAYER_DIRTY_VARIABLE, 1)
            + b"\x74"
            + _immediate(NUKE_SOUND_LAUNCH)
        )
        routine.jump_if_not_equal(
            MISSILE_BATTERY_AMMO_VARIABLES[0],
            0,
            reload_done_label,
        )
        routine.jump_if_equal(
            MISSILE_AMMO_VARIABLE,
            0,
            reload_done_label,
        )
        routine.emit(
            _set_variable_s16(
                MISSILE_BATTERY_AMMO_VARIABLES[0],
                MISSILE_BATTERY_AMMO,
            )
        )
        routine.label(reload_done_label)
        routine.jump_if_not_equal(
            MISSILE_AMMO_VARIABLE,
            0,
            f"missile_fire_{slot}_terrain_ready",
        )
        routine.emit(_set_variable_s16(MISSILE_TERRAIN_DIRTY_VARIABLE, 1))
        routine.label(f"missile_fire_{slot}_terrain_ready")
        routine.jump("missile_fire_done")
        routine.label(slot_next_label)
    routine.jump("missile_fire_done")
    routine.label("missile_fire_released")
    routine.emit(_set_variable_s16(MISSILE_FIRE_LATCH_VARIABLE, 0))
    routine.label("missile_fire_done")

    routine.label("missile_cursor")
    routine.jump_if_equal(MISSILE_CURSOR_DELAY_VARIABLE, 0, "missile_cursor_ready")
    routine.emit(_decrement_variable(MISSILE_CURSOR_DELAY_VARIABLE))
    routine.jump("missile_frame_loop")
    routine.label("missile_cursor_ready")
    routine.jump_if_pad_not_pressed(PAD_MASK_UP, "missile_cursor_right")
    routine.jump_if_equal(
        MISSILE_CURSOR_ROW_VARIABLE,
        MISSILE_CURSOR_MIN_ROW,
        "missile_cursor_right",
    )
    routine.emit(
        _copy_variable(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_CURSOR_CELL_VARIABLE,
        )
        + _variable_math(
            0x39,
            MISSILE_CURSOR_CELL_VARIABLE,
            NUKE_GRID_WIDTH,
        )
        + _decrement_variable(MISSILE_CURSOR_ROW_VARIABLE)
    )
    routine.jump("missile_cursor_moved")
    routine.label("missile_cursor_right")
    routine.jump_if_pad_not_pressed(PAD_MASK_RIGHT, "missile_cursor_down")
    routine.jump_if_equal(
        MISSILE_CURSOR_COLUMN_VARIABLE,
        MISSILE_CURSOR_MAX_COLUMN,
        "missile_cursor_down",
    )
    routine.emit(
        _copy_variable(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_CURSOR_CELL_VARIABLE,
        )
        + _increment_variable(MISSILE_CURSOR_CELL_VARIABLE)
        + _increment_variable(MISSILE_CURSOR_COLUMN_VARIABLE)
    )
    routine.jump("missile_cursor_moved")
    routine.label("missile_cursor_down")
    routine.jump_if_pad_not_pressed(PAD_MASK_DOWN, "missile_cursor_left")
    routine.jump_if_equal(
        MISSILE_CURSOR_ROW_VARIABLE,
        MISSILE_CURSOR_MAX_ROW,
        "missile_cursor_left",
    )
    routine.emit(
        _copy_variable(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_CURSOR_CELL_VARIABLE,
        )
        + _variable_math(
            0x38,
            MISSILE_CURSOR_CELL_VARIABLE,
            NUKE_GRID_WIDTH,
        )
        + _increment_variable(MISSILE_CURSOR_ROW_VARIABLE)
    )
    routine.jump("missile_cursor_moved")
    routine.label("missile_cursor_left")
    routine.jump_if_pad_not_pressed(PAD_MASK_LEFT, "missile_frame_loop")
    routine.jump_if_equal(
        MISSILE_CURSOR_COLUMN_VARIABLE,
        MISSILE_CURSOR_MIN_COLUMN,
        "missile_frame_loop",
    )
    routine.emit(
        _copy_variable(
            MISSILE_CURSOR_DIRTY_CELL_VARIABLE,
            MISSILE_CURSOR_CELL_VARIABLE,
        )
        + _decrement_variable(MISSILE_CURSOR_CELL_VARIABLE)
        + _decrement_variable(MISSILE_CURSOR_COLUMN_VARIABLE)
    )
    routine.label("missile_cursor_moved")
    routine.emit(
        _set_variable_s16(
            MISSILE_CURSOR_DELAY_VARIABLE,
            MISSILE_CURSOR_REPEAT_DELAY,
        )
    )
    routine.jump("missile_frame_loop")

    routine.label("missile_wave_stop_wait")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_not_equal(
        MISSILE_MODE_ACK_VARIABLE,
        MISSILE_MODE_STOPPED,
        "missile_wave_stop_wait",
    )

    routine.label("missile_wave_clear")
    routine.emit(
        _copy_variable(NUKE_TEMP_0_VARIABLE, MISSILE_CITIES_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            MISSILE_CITY_BONUS_UNITS,
        )
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            MISSILE_SCORE_MULTIPLIER_VARIABLE,
            operand_is_variable=True,
        )
        + _variable_math(
            0x38,
            MISSILE_SCORE_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
        + _copy_variable(NUKE_TEMP_0_VARIABLE, MISSILE_AMMO_VARIABLE)
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            MISSILE_AMMO_BONUS_UNITS,
        )
        + _variable_math(
            0xDE,
            NUKE_TEMP_0_VARIABLE,
            MISSILE_SCORE_MULTIPLIER_VARIABLE,
            operand_is_variable=True,
        )
        + _variable_math(
            0x38,
            MISSILE_SCORE_VARIABLE,
            NUKE_TEMP_0_VARIABLE,
            operand_is_variable=True,
        )
    )
    routine.jump_if_signed_greater_or_equal(
        MISSILE_SCORE_VARIABLE,
        MISSILE_MAX_SCORE_UNITS + 1,
        "missile_wave_score_clamp",
    )
    routine.jump("missile_wave_score_ready")
    routine.label("missile_wave_score_clamp")
    routine.emit(
        _set_variable_s16(MISSILE_SCORE_VARIABLE, MISSILE_MAX_SCORE_UNITS)
    )
    routine.label("missile_wave_score_ready")

    # Award every crossed 10,000-point threshold into a reserve, then rebuild
    # cratered cities before deciding whether the command has finally ended.
    routine.label("missile_bonus_city_check")
    routine.jump_if_not_signed_greater_than(
        MISSILE_NEXT_BONUS_SCORE_VARIABLE,
        MISSILE_SCORE_VARIABLE,
        "missile_bonus_city_award",
    )
    routine.jump("missile_bonus_city_ready")
    routine.label("missile_bonus_city_award")
    routine.emit(
        _increment_variable(MISSILE_RESERVE_CITIES_VARIABLE)
        + _variable_math(
            0x38,
            MISSILE_NEXT_BONUS_SCORE_VARIABLE,
            MISSILE_BONUS_CITY_INTERVAL_UNITS,
        )
        + _set_variable_s16(MISSILE_BONUS_AWARDED_VARIABLE, 1)
    )
    routine.jump("missile_bonus_city_check")
    routine.label("missile_bonus_city_ready")
    for city_index in range(len(MISSILE_CITY_COLUMNS)):
        restore_label = f"missile_restore_city_{city_index}"
        next_label = f"missile_restore_city_{city_index}_next"
        routine.jump_if_equal(
            MISSILE_RESERVE_CITIES_VARIABLE,
            0,
            "missile_city_restore_done",
        )
        routine.jump_if_bit_clear(
            MISSILE_CITY_MASK_VARIABLE,
            1 << city_index,
            restore_label,
        )
        routine.jump(next_label)
        routine.label(restore_label)
        routine.emit(
            _set_var_bit(MISSILE_CITY_MASK_VARIABLE, city_index)
            + _increment_variable(MISSILE_CITIES_VARIABLE)
            + _decrement_variable(MISSILE_RESERVE_CITIES_VARIABLE)
        )
        routine.label(next_label)
    routine.label("missile_city_restore_done")
    routine.jump_if_equal(MISSILE_CITIES_VARIABLE, 0, "missile_failed")

    routine.emit(
        b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _call(missile_hud_pc)
        + _call(panel_fill_pc)
        + _nuke_centered_text_body("WAVE CLEARED", 58)
        + _nuke_centered_text_body("CITY + MISSILE BONUS", 76)
    )
    routine.jump_if_equal(
        MISSILE_BONUS_AWARDED_VARIABLE,
        1,
        "missile_bonus_city_message",
    )
    routine.emit(_nuke_centered_text_body("NEXT WAVE INCOMING", 94))
    routine.jump("missile_wave_message_ready")
    routine.label("missile_bonus_city_message")
    routine.emit(_nuke_centered_text_body("BONUS CITY EARNED", 94))
    routine.label("missile_wave_message_ready")
    routine.emit(_wait(36))
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(
            PAD_MASK_CROSS,
            release_pc,
        )
    )
    routine.jump_if_equal(
        MISSILE_WAVE_VARIABLE,
        MISSILE_MAX_WAVE,
        "missile_wave_number_ready",
    )
    routine.emit(_increment_variable(MISSILE_WAVE_VARIABLE))
    routine.label("missile_wave_number_ready")
    routine.emit(
        _call(missile_setup_wave_pc)
        + _call(missile_terrain_pc)
        + _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_ARMING,
        )
    )
    routine.jump("missile_frame_loop")

    routine.label("missile_failed")
    routine.emit(_set_variable_s16(MISSILE_OUTCOME_VARIABLE, 1))
    routine.jump("missile_finish")

    routine.label("missile_finish")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _set_variable_s16(MISSILE_ACTIVE_VARIABLE, 0)
        + b"\x74"
        + _immediate(MISSILE_SOUND_EXPLOSION)
        + _wait(18)
    )
    routine.jump_if_not_signed_greater_than(
        MISSILE_WAVE_VARIABLE,
        missile_game.best_wave_variable,
        "missile_best_wave_done",
    )
    routine.emit(
        _copy_variable(
            missile_game.best_wave_variable,
            MISSILE_WAVE_VARIABLE,
        )
    )
    routine.label("missile_best_wave_done")
    routine.emit(_missile_pack_records_body(nuke_game, missile_game))
    routine.jump_if_not_signed_greater_than(
        MISSILE_SCORE_VARIABLE,
        missile_game.high_score_variable,
        "missile_score_entry_done",
    )
    routine.emit(
        _copy_variable(
            missile_game.high_score_variable,
            MISSILE_SCORE_VARIABLE,
        )
        + _missile_pack_records_body(nuke_game, missile_game)
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _nuke_unpack_initials_body(nuke_game)
        + _set_variable_s16(NUKE_NAME_POSITION_VARIABLE, 0)
        + _call(name_draw_pc)
    )
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(
            menu_mask
            | PAD_MASK_UP
            | PAD_MASK_DOWN
            | PAD_MASK_LEFT
            | PAD_MASK_RIGHT,
            release_pc,
        )
    )

    routine.label("missile_name_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(PAD_MASK_UP, "missile_name_check_down")
    routine.jump("missile_name_up")
    routine.label("missile_name_check_down")
    routine.jump_if_pad_not_pressed(PAD_MASK_DOWN, "missile_name_check_left")
    routine.jump("missile_name_down")
    routine.label("missile_name_check_left")
    routine.jump_if_pad_not_pressed(PAD_MASK_LEFT, "missile_name_check_right")
    routine.jump("missile_name_left")
    routine.label("missile_name_check_right")
    routine.jump_if_pad_not_pressed(PAD_MASK_RIGHT, "missile_name_check_cross")
    routine.jump("missile_name_right")
    routine.label("missile_name_check_cross")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "missile_name_check_circle")
    routine.jump("missile_name_cross")
    routine.label("missile_name_check_circle")
    routine.jump_if_pad_not_pressed(PAD_MASK_CIRCLE, "missile_name_loop")
    routine.jump("missile_name_left")

    name_variables = (
        NUKE_NAME_0_VARIABLE,
        NUKE_NAME_1_VARIABLE,
        NUKE_NAME_2_VARIABLE,
        NUKE_NAME_3_VARIABLE,
    )
    routine.label("missile_name_up")
    for index in range(4):
        routine.jump_if_equal(
            NUKE_NAME_POSITION_VARIABLE,
            index,
            f"missile_name_up_{index}",
        )
    routine.jump("missile_name_loop")
    for index, name_variable in enumerate(name_variables):
        routine.label(f"missile_name_up_{index}")
        routine.emit(_increment_variable(name_variable))
        routine.jump_if_signed_less_than(
            name_variable,
            26,
            "missile_name_changed",
        )
        routine.emit(_set_variable_s16(name_variable, 0))
        routine.jump("missile_name_changed")

    routine.label("missile_name_down")
    for index in range(4):
        routine.jump_if_equal(
            NUKE_NAME_POSITION_VARIABLE,
            index,
            f"missile_name_down_{index}",
        )
    routine.jump("missile_name_loop")
    for index, name_variable in enumerate(name_variables):
        routine.label(f"missile_name_down_{index}")
        routine.jump_if_equal(
            name_variable,
            0,
            f"missile_name_down_wrap_{index}",
        )
        routine.emit(_decrement_variable(name_variable))
        routine.jump("missile_name_changed")
        routine.label(f"missile_name_down_wrap_{index}")
        routine.emit(_set_variable_s16(name_variable, 25))
        routine.jump("missile_name_changed")

    routine.label("missile_name_left")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 0, "missile_name_loop")
    routine.emit(_decrement_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("missile_name_changed")
    routine.label("missile_name_right")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 3, "missile_name_loop")
    routine.emit(_increment_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("missile_name_changed")
    routine.label("missile_name_cross")
    routine.jump_if_equal(NUKE_NAME_POSITION_VARIABLE, 3, "missile_name_commit")
    routine.emit(_increment_variable(NUKE_NAME_POSITION_VARIABLE))
    routine.jump("missile_name_changed")
    routine.label("missile_name_changed")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
        + _call(name_draw_pc)
        + _wait(4)
    )
    routine.jump("missile_name_loop")
    routine.label("missile_name_commit")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _nuke_pack_initials_body(nuke_game)
        + _missile_pack_records_body(nuke_game, missile_game)
        + b"\x74"
        + _immediate(NUKE_SOUND_CONFIRM)
    )
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(
            menu_mask
            | PAD_MASK_UP
            | PAD_MASK_DOWN
            | PAD_MASK_LEFT
            | PAD_MASK_RIGHT,
            release_pc,
        )
    )

    routine.label("missile_score_entry_done")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(missile_hud_pc)
        + _call(panel_fill_pc)
    )
    routine.emit(_nuke_centered_text_body("THE END", 49))
    routine.emit(
        _nuke_centered_text_body("----------------------", 59)
        + _nuke_static_text_body("SCORE", 104, 70)
        + _missile_draw_score_body(
            MISSILE_SCORE_VARIABLE,
            165,
            70,
            digit_pc,
        )
        + _nuke_static_text_body("WAVE", 104, 79)
        + _nuke_draw_number_body(
            MISSILE_WAVE_VARIABLE,
            2,
            165,
            79,
            digit_pc,
        )
        + _nuke_static_text_body("BEST", 104, 88)
        + _missile_draw_score_body(
            missile_game.high_score_variable,
            165,
            88,
            digit_pc,
        )
        + _nuke_centered_text_body("----------------------", 98)
        + _nuke_centered_text_body("CROSS RETRY", 109)
        + _nuke_centered_text_body("CIRCLE EXIT", 118)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(menu_mask, release_pc))
    routine.label("missile_game_over_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "missile_game_over_retry")
    routine.jump("exit_game")
    routine.label("missile_game_over_retry")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "missile_game_over_loop")
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(PAD_MASK_CROSS, release_pc)
        + b"\x74"
        + _immediate(NUKE_SOUND_LAUNCH)
        + _call(missile_setup_game_pc)
        + _call(missile_setup_wave_pc)
        + _call(missile_terrain_pc)
        + _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_ARMING,
        )
    )
    routine.jump("missile_frame_loop")

    routine.label("missile_pause_wait_ack")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_not_equal(
        MISSILE_MODE_ACK_VARIABLE,
        MISSILE_MODE_PAUSED,
        "missile_pause_wait_ack",
    )
    routine.label("missile_pause")
    routine.emit(
        b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _nuke_fill_screen_rect_body(
            NUKE_HUD_SCREEN_RECT,
            NUKE_PANEL_BACKGROUND_TILE_NAME,
        )
        + _nuke_centered_text_body("DEFENSE PAUSED", 18)
        + _nuke_centered_text_body("CROSS RESUME  CIRCLE EXIT", 27)
    )
    release_pc = routine.pc
    routine.emit(_wait_for_pad_release(missile_pause_mask, release_pc))
    routine.label("missile_pause_loop")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_pad_not_pressed(cancel_mask, "missile_pause_check_resume")
    routine.emit(
        _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_STOPPED,
        )
    )
    routine.jump("missile_exit_wait_ack")
    routine.label("missile_pause_check_resume")
    routine.jump_if_pad_not_pressed(PAD_MASK_CROSS, "missile_pause_loop")
    release_pc = routine.pc
    routine.emit(
        _wait_for_pad_release(PAD_MASK_CROSS, release_pc)
        + b"\xC6" * NUKE_VM_CYCLE_BOOSTERS
        + _call(missile_hud_pc)
        + _set_variable_s16(
            MISSILE_MODE_REQUEST_VARIABLE,
            MISSILE_MODE_ARMING,
        )
    )
    routine.jump("missile_frame_loop")

    routine.label("missile_exit_wait_ack")
    routine.emit(_yield_tick() + b"\xC6")
    routine.jump_if_not_equal(
        MISSILE_MODE_ACK_VARIABLE,
        MISSILE_MODE_STOPPED,
        "missile_exit_wait_ack",
    )
    routine.emit(_set_variable_s16(MISSILE_ACTIVE_VARIABLE, 0))
    routine.jump("exit_game")

    routine.label("exit_game")
    routine.emit(_nuke_teardown_body(nuke_game.screen_entity))

    routine.label("video_disk")
    routine.emit(
        _facility_video_terminal_action(
            video_event,
            routine.pc,
        )
    )
    routine.label("leave")
    routine.emit(_actor_dialog_reset_body() + b"\xFE\x53\x00")
    return routine.finish()


def _local_door_party_update_script(
    base: int,
    transfers: Sequence[tuple[int, int, int, int]],
) -> bytes:
    """Walk each active party actor without allocating another VM slot.

    Script index 1 is Xenogears' already-scheduled per-frame party update.
    The wrapper preserves its retail A7/STOP idle body.  During one local-door
    request, every loaded party actor performs a bounded walk to the audited
    far-side walkmesh point, exact-snaps there, and faces forward.  The door
    owner therefore never waits on a leader or follower execution slot, while
    the crossing remains visible instead of looking like a geometry glitch.
    """

    if LOCAL_DOOR_TRANSFER_SETTLE_FRAMES < DOOR_MOVEMENT_GRACE_FRAMES:
        raise DungeonBuildError(
            "Local-door settle window "
            f"{LOCAL_DOOR_TRANSFER_SETTLE_FRAMES} is shorter than bounded "
            f"movement grace {DOOR_MOVEMENT_GRACE_FRAMES}"
        )
    if not transfers:
        raise DungeonBuildError("Local-door party update needs at least one route")
    codes = [request for request, _x, _z, _direction in transfers]
    if len(codes) != len(set(codes)) or any(code <= 0 for code in codes):
        raise DungeonBuildError("Local-door transfer request codes are invalid")

    routine = _RoutineBuilder(base)
    for index, (request, x, z, direction) in enumerate(transfers):
        if not 0 <= direction <= 7:
            raise DungeonBuildError(
                f"Local-door actor direction outside 0..7: {direction}"
            )
        next_label = f"transfer_check_{index + 1}"
        routine.jump_if_not_equal(
            LOCAL_DOOR_TRANSFER_VARIABLE,
            request,
            next_label,
        )
        position = _s16(x) + _s16(z)
        routine.emit(
            b"\x4B"
            + position
            + b"\xC0"
            + _immediate(DOOR_MOVEMENT_MAX_STEPS)
            + b"\x19"
            + position
            + b"\xC0"
            + b"\x1A\x00"
            + b"\x5F"
            + bytes((direction,))
            + b"\x00"
        )
        routine.label(next_label)
    routine.emit(b"\xA7\x00")
    return routine.finish()


def validate_route(
    route: Sequence[int] = ROUTE,
    edges: Sequence[tuple[int, int]] = ROUTE_EDGES,
) -> tuple[tuple[int, int], ...]:
    """Validate the complete reachable dungeon graph and its audited slots."""

    if len(route) < 2:
        raise DungeonBuildError("Mass Driver route must contain at least two fields")
    if len(route) != len(set(route)):
        raise DungeonBuildError("Mass Driver target list contains a duplicate")
    unsafe = [field for field in route if field not in SAFE_ROUTE_TARGETS]
    if unsafe:
        raise DungeonBuildError(
            f"Route target(s) not in the audited safe-target list: {unsafe}"
        )
    normalized = tuple(edges)
    if len(normalized) != len(set(normalized)):
        raise DungeonBuildError("Mass Driver route graph contains a duplicate edge")
    route_set = set(route)
    outside = [
        edge
        for edge in normalized
        if edge[0] not in route_set or edge[1] not in route_set
    ]
    if outside:
        raise DungeonBuildError(f"Route edge endpoint is outside the target list: {outside}")
    if route[0] != ROUTE_ENTRY_FIELD or route[-1] != BOOTSTRAP_FIELD:
        raise DungeonBuildError(
            f"Route must begin at {ROUTE_ENTRY_FIELD} and end at {BOOTSTRAP_FIELD}"
        )

    successors: dict[int, set[int]] = {field: set() for field in route}
    for source, destination in normalized:
        successors[source].add(destination)
    missing_exits = [field for field in route if not successors[field]]
    if missing_exits:
        raise DungeonBuildError(f"Route field(s) have no graph exit: {missing_exits}")

    reached = {route[0]}
    frontier = [route[0]]
    while frontier:
        source = frontier.pop()
        for destination in successors[source]:
            if destination not in reached:
                reached.add(destination)
                frontier.append(destination)
    unreachable = sorted(route_set - reached)
    if unreachable:
        raise DungeonBuildError(
            f"Route target(s) are unreachable from field {route[0]}: {unreachable}"
        )
    return normalized


def _component_path(directory: Path, index: int) -> Path:
    return directory / f"{index:02d}_{STREAM_NAMES[index]}.bin"


def _load_components(directory: Path) -> tuple[bytes, list[bytes]]:
    header_path = directory / "header.bin"
    paths = [_component_path(directory, index) for index in range(len(STREAM_NAMES))]
    missing = [path for path in (header_path, *paths) if not path.is_file()]
    if missing:
        raise DungeonBuildError(f"Missing unpacked field input: {missing[0]}")
    return header_path.read_bytes(), [path.read_bytes() for path in paths]


def _indexed_bundle_entries(data: bytes) -> tuple[bytes, ...]:
    """Split a field actor/sprite component with checked absolute offsets."""

    if len(data) < 8:
        raise DungeonBuildError("Indexed component is shorter than its header")
    count = struct.unpack_from("<I", data)[0]
    if count == 0:
        raise DungeonBuildError("Indexed component contains no entries")
    table_end = 4 + count * 4
    if table_end > len(data):
        raise DungeonBuildError("Indexed component offset table is truncated")
    offsets = struct.unpack_from(f"<{count}I", data, 4)
    if offsets[0] < table_end:
        raise DungeonBuildError(
            "Indexed component data overlaps its offset table"
        )
    if any(left >= right for left, right in zip(offsets, offsets[1:])):
        raise DungeonBuildError("Indexed component offsets are not increasing")
    if offsets[-1] >= len(data):
        raise DungeonBuildError(
            "Indexed component final entry is empty or truncated"
        )
    ends = (*offsets[1:], len(data))
    return tuple(data[start:end] for start, end in zip(offsets, ends, strict=True))


def _indexed_bundle_entry(data: bytes, index: int) -> bytes:
    entries = _indexed_bundle_entries(data)
    if not isinstance(index, int) or not 0 <= index < len(entries):
        raise DungeonBuildError(
            f"Indexed component entry must be in 0..{len(entries) - 1}: {index}"
        )
    return entries[index]


def _replace_indexed_bundle_entry(
    data: bytes,
    index: int,
    replacement: bytes,
    expected_sha256: str,
) -> bytes:
    """Replace one checked actor/sprite bank and rebuild absolute offsets."""

    entries = list(_indexed_bundle_entries(data))
    if not isinstance(index, int) or not 0 <= index < len(entries):
        raise DungeonBuildError(
            f"Indexed component entry must be in 0..{len(entries) - 1}: {index}"
        )
    actual_hash = _sha256(entries[index])
    if actual_hash != expected_sha256:
        raise DungeonBuildError(
            f"Indexed component entry {index} hash mismatch: {actual_hash}"
        )
    if not replacement:
        raise DungeonBuildError("Indexed component replacement cannot be empty")
    entries[index] = bytes(replacement)
    table_end = 4 + len(entries) * 4
    first_offset = struct.unpack_from("<I", data, 4)[0]
    prefix_padding = data[table_end:first_offset]
    offsets: list[int] = []
    cursor = table_end + len(prefix_padding)
    for entry in entries:
        offsets.append(cursor)
        cursor += len(entry)
    return (
        struct.pack("<I", len(entries))
        + struct.pack(f"<{len(entries)}I", *offsets)
        + prefix_padding
        + b"".join(entries)
    )


def _rebuild_indexed_bundle(
    source: bytes,
    entries: Sequence[bytes],
) -> bytes:
    """Rebuild an indexed component while preserving its pre-entry padding."""

    original_count = struct.unpack_from("<I", source)[0]
    original_table_end = 4 + original_count * 4
    original_first = struct.unpack_from("<I", source, 4)[0]
    prefix_padding = source[original_table_end:original_first]
    table_end = 4 + len(entries) * 4
    offsets: list[int] = []
    cursor = table_end + len(prefix_padding)
    for entry in entries:
        if not entry:
            raise DungeonBuildError("Indexed component entry cannot be empty")
        offsets.append(cursor)
        cursor += len(entry)
    return (
        struct.pack("<I", len(entries))
        + struct.pack(f"<{len(entries)}I", *offsets)
        + prefix_padding
        + b"".join(entries)
    )


def _recenter_single_block_model(
    model: bytes,
    *,
    expected_sha256: str,
    pivot: tuple[int, int, int],
    expected_vertices: int,
) -> bytes:
    """Clone one checked field model around its native sliding origin."""

    actual_hash = _sha256(model)
    if actual_hash != expected_sha256:
        raise DungeonBuildError(
            f"Static door model hash mismatch: {actual_hash}"
        )
    result = bytearray(model)
    if len(result) < 0x48 or struct.unpack_from("<I", result)[0] != 1:
        raise DungeonBuildError(
            "Static door donor is not the audited single-block model"
        )
    block = 0x10
    vertex_count = struct.unpack_from("<H", result, block + 2)[0]
    vertex_offset = struct.unpack_from("<I", result, block + 8)[0]
    if vertex_count != expected_vertices:
        raise DungeonBuildError(
            f"Static door donor has {vertex_count} vertices, "
            f"expected {expected_vertices}"
        )
    if vertex_offset + vertex_count * 8 > len(result):
        raise DungeonBuildError("Static door donor vertex table is truncated")

    pivot_x, pivot_y, pivot_z = pivot

    def recenter_vector(offset: int) -> None:
        x, y, z = struct.unpack_from("<hhh", result, offset)
        replacement = (x - pivot_x, y - pivot_y, z - pivot_z)
        if any(not -0x8000 <= value <= 0x7FFF for value in replacement):
            raise DungeonBuildError("Recentered static door vertex overflows s16")
        struct.pack_into("<hhh", result, offset, *replacement)

    # Two block-space bound vectors precede the vertex table.
    recenter_vector(block + 0x20)
    recenter_vector(block + 0x28)
    for index in range(vertex_count):
        recenter_vector(vertex_offset + index * 8)
    return bytes(result)


def _static_door_models(models: bytes, target_field: int) -> bytes:
    """Expose audited baked panels as independently movable native models."""

    entries = list(_indexed_bundle_entries(models))
    if target_field == 726:
        if len(entries) != 6:
            raise DungeonBuildError("Field 726 model inventory is not the audited set")
        if _sha256(entries[3]) != (
            "466b6238bf36bf83ea1555f4048cb63202cfb4b7c7a2a0bf934ced9a6808a55d"
        ):
            raise DungeonBuildError("Field 726 baked-door model hash mismatch")
        baked = bytearray(entries[3])
        panel_indices = bytes.fromhex(
            "93 00 92 00 94 00 91 00 53 00 52 00 4E 00 4D 00 "
            "71 00 72 00 6F 00 6E 00 76 00 75 00 77 00 74 00 "
            "83 00 82 00 84 00 81 00 6A 00 6B 00 67 00 66 00 "
            "8B 00 8A 00 8C 00 89 00 4D 00 4C 00 4E 00 4B 00"
        )
        if baked[0x1200:0x1240] != panel_indices:
            raise DungeonBuildError(
                "Field 726 baked-door primitive indices do not match audit"
            )
        # These eight panels are the final eight primitives of the final mesh
        # block. Earlier builds either collapsed each quad onto one vertex or
        # lowered only the two primitive counts. The former still submitted
        # unsafe degenerate textured geometry; the latter left a malformed
        # 64-byte gap before the unchanged display list, all eight live GPU
        # records, and the old runtime instance-buffer size. Both faults can
        # project enormous near-plane stripes while the replacement panel
        # moves. Remove the complete audited tail instead: eight 8-byte index
        # records and their eight 12-byte type-0x0D display records, then
        # relocate the display-list offset and shrink the instance buffer by
        # eight 0x28-byte textured-quad instances.
        if (
            struct.unpack_from("<H", baked, 0x14)[0] != 268
            or baked[0x0A7C:0x0A80] != bytes.fromhex("0D 77 F8 00")
            or struct.unpack_from("<I", baked, 0x24)[0] != 0x1240
            or struct.unpack_from("<I", baked, 0x44)[0] != 0x2940
            or len(baked) != 0x1EBC
            or _sha256(baked[-0x60:])
            != "0896a0b227e563ef497f4f435c594073d4af91cad14387a1437e26ac3fc6d16f"
        ):
            raise DungeonBuildError(
                "Field 726 baked-door tail is not the audited final mesh block"
            )
        struct.pack_into("<H", baked, 0x14, 260)
        struct.pack_into("<H", baked, 0x0A7E, 240)
        struct.pack_into("<I", baked, 0x24, 0x1200)
        struct.pack_into("<I", baked, 0x44, 0x2800)
        baked = baked[:0x1200] + baked[0x1240:-0x60]
        if (
            len(baked) != 0x1E1C
            or 0x0A80 + 240 * 8 != struct.unpack_from("<I", baked, 0x24)[0]
            or len(baked) - struct.unpack_from("<I", baked, 0x24)[0] != 3100
        ):
            raise DungeonBuildError(
                "Field 726 structural baked-door removal is inconsistent"
            )
        entries[3] = bytes(baked)
        vertical = _recenter_single_block_model(
            entries[0],
            expected_sha256=(
                "40f1395ee7d6213e3cf2caffef873eea462c342bed05a5fc8cfeb826368d1847"
            ),
            pivot=(-661, 0, -611),
            expected_vertices=6,
        )
        horizontal = _recenter_single_block_model(
            entries[1],
            expected_sha256=(
                "475f4bd954c5ad9da4b03483ddd16dd12f2066b637b4f5cf0bb531dc829cab8f"
            ),
            pivot=(402, 0, -661),
            expected_vertices=4,
        )
        horizontal_positive = _recenter_single_block_model(
            entries[2],
            expected_sha256=(
                "14c3d848c2890fb8468b9fcbea296fa54a10b961b22456668ece07a723fa8d78"
            ),
            pivot=(5, 0, 661),
            expected_vertices=6,
        )
        entries.extend((vertical, horizontal, horizontal_positive))
    elif target_field == 376:
        if (
            len(entries) != 14
            or _sha256(models)
            != "252824c3c5b5486eb2d755df96f9c1e2eeba45bc9c4ef75b65309026a94ee3b2"
        ):
            raise DungeonBuildError(
                "Field 394 model archive is not the audited defense archive"
            )
        if _sha256(entries[8]) != (
            "aefb29e76bc1db2ba32bff1033cc0aa0ade0afe703c9beef18777facf18cb31a"
        ):
            raise DungeonBuildError(
                "Field 394 west-wall model hash does not match the audit"
            )

        # Model 8 owns the complete west wall.  Remove its exact central
        # 88-by-132 textured quad, including both the mesh index record and
        # GPU display record.  Counts, display offset, and the runtime
        # textured-quad instance allocation all shrink together; leaving any
        # one of them behind produces malformed geometry or near-plane
        # artifacts when the replacement bulkhead moves.
        wall = bytearray(entries[8])
        expected_indices = bytes.fromhex("2A 00 38 00 C8 00 C7 00")
        expected_display = bytes.fromhex(
            "00 00 00 2D 60 73 80 73 60 42 80 42"
        )
        if (
            len(wall) != 0x1408
            or struct.unpack_from("<H", wall, 0x14)[0] != 154
            or struct.unpack_from("<H", wall, 0x806)[0] != 152
            or struct.unpack_from("<I", wall, 0x24)[0] != 0x0CC8
            or struct.unpack_from("<I", wall, 0x44)[0] != 0x1800
            or wall[0x0AF8:0x0B00] != expected_indices
            or wall[0x1150:0x115C] != expected_display
        ):
            raise DungeonBuildError(
                "Field 394 west-wall aperture no longer matches its audit"
            )
        del wall[0x1150:0x115C]
        del wall[0x0AF8:0x0B00]
        struct.pack_into("<H", wall, 0x14, 153)
        struct.pack_into("<H", wall, 0x806, 151)
        struct.pack_into("<I", wall, 0x24, 0x0CC0)
        struct.pack_into("<I", wall, 0x44, 0x17D8)
        if (
            len(wall) != 0x13F4
            or _sha256(wall)
            != "0d4f5eeac9f21d96e3a1c93cdb8ac0cf4b6d5e09ed7a1de4d690063c2e72138a"
        ):
            raise DungeonBuildError(
                "Field 394 west-wall removal is not structurally exact"
            )
        entries[8] = bytes(wall)

        if _sha256(entries[13]) != (
            "09723c2ee728286282593f0ef2b7b734d9609569305af07df8dc8cf8617f719c"
        ):
            raise DungeonBuildError(
                "Field 394 north-wall model hash does not match the audit"
            )

        # Model 13's nineteenth textured quad is the central north-wall
        # service panel. Remove precisely that quad before substituting two
        # leaves with the same vertices and UV range. This creates an actual
        # aperture without covering the monitor strip or the adjacent wall
        # art above it.
        north_wall = bytearray(entries[13])
        expected_north_indices = bytes.fromhex(
            "16 00 14 00 15 00 13 00"
        )
        expected_north_display = bytes.fromhex(
            "00 00 00 2D C0 73 9F 73 C0 54 9F 54"
        )
        if (
            len(north_wall) != 0x0A70
            or struct.unpack_from("<H", north_wall, 0x14)[0] != 90
            or struct.unpack_from("<H", north_wall, 0x3EE)[0] != 74
            or struct.unpack_from("<I", north_wall, 0x24)[0] != 0x0640
            or struct.unpack_from("<I", north_wall, 0x44)[0] != 0x0D90
            or north_wall[0x0488:0x0490] != expected_north_indices
            or north_wall[0x07C4:0x07D0] != expected_north_display
        ):
            raise DungeonBuildError(
                "Field 394 north-wall aperture no longer matches its audit"
            )
        del north_wall[0x07C4:0x07D0]
        del north_wall[0x0488:0x0490]
        struct.pack_into("<H", north_wall, 0x14, 89)
        struct.pack_into("<H", north_wall, 0x3EE, 73)
        struct.pack_into("<I", north_wall, 0x24, 0x0638)
        struct.pack_into("<I", north_wall, 0x44, 0x0D68)
        if len(north_wall) != 0x0A5C:
            raise DungeonBuildError(
                "Field 394 north-wall removal is not structurally exact"
            )
        entries[13] = bytes(north_wall)

        # Rebuild both removed POLY_FT4 panels as paired moving leaves. Their
        # divided UVs reconstruct the donor's own weathered wall textures when
        # closed, while the fixed geometry is only a dim reveal behind each
        # wall plane.
        left_leaf = build_defense_archive_bulkhead_left_leaf()
        right_leaf = build_defense_archive_bulkhead_right_leaf()
        frame = build_defense_archive_bulkhead_frame()
        north_left_leaf = build_defense_archive_north_lift_left_leaf()
        north_right_leaf = build_defense_archive_north_lift_right_leaf()
        north_frame = build_defense_archive_north_lift_frame()
        model_contracts = (
            (
                left_leaf,
                BULKHEAD_LEFT_MODEL_SIZE,
                BULKHEAD_LEFT_MODEL_SHA256,
                "left leaf",
            ),
            (
                right_leaf,
                BULKHEAD_RIGHT_MODEL_SIZE,
                BULKHEAD_RIGHT_MODEL_SHA256,
                "right leaf",
            ),
            (
                frame,
                BULKHEAD_FRAME_MODEL_SIZE,
                BULKHEAD_FRAME_MODEL_SHA256,
                "frame",
            ),
            (
                north_left_leaf,
                NORTH_LIFT_LEFT_MODEL_SIZE,
                NORTH_LIFT_LEFT_MODEL_SHA256,
                "north-lift left leaf",
            ),
            (
                north_right_leaf,
                NORTH_LIFT_RIGHT_MODEL_SIZE,
                NORTH_LIFT_RIGHT_MODEL_SHA256,
                "north-lift right leaf",
            ),
            (
                north_frame,
                NORTH_LIFT_FRAME_MODEL_SIZE,
                NORTH_LIFT_FRAME_MODEL_SHA256,
                "north-lift frame",
            ),
        )
        for model, expected_size, expected_hash, label in model_contracts:
            if len(model) != expected_size or _sha256(model) != expected_hash:
                raise DungeonBuildError(
                    f"Defense-archive bulkhead {label} is not deterministic"
                )
        if len(entries) != 14:
            raise DungeonBuildError(
                "Defense-archive bulkhead model indices drifted"
            )
        entries.extend(
            (
                left_leaf,
                right_leaf,
                frame,
                north_left_leaf,
                north_right_leaf,
                north_frame,
            )
        )
    else:
        raise DungeonBuildError(
            f"Field {target_field} has no audited static-door model transform"
        )
    rebuilt = _rebuild_indexed_bundle(models, entries)
    if target_field == 376 and (
        len(rebuilt) != 53496
        or _sha256(rebuilt)
        != "1720f5af5e753aa89bcbb9d6032e9127576e6ceb314ec99ec58219e9047bcd24"
    ):
        raise DungeonBuildError(
            "Defense-archive model archive does not match the audited rebuild: "
            f"{len(rebuilt)} bytes, SHA-256 {_sha256(rebuilt)}"
        )
    return rebuilt


def _install_defense_archive_video_plane_model(
    models: bytes,
    input_root: Path,
) -> bytes:
    """Append retail fields 617/618's isolated still-image screen model."""

    entries = list(_indexed_bundle_entries(models))
    if (
        len(models) != 53496
        or _sha256(models)
        != "1720f5af5e753aa89bcbb9d6032e9127576e6ceb314ec99ec58219e9047bcd24"
        or len(entries) != FACILITY_VIDEO_SCREEN_MODEL_INDEX
    ):
        raise DungeonBuildError(
            "Defense Archive video screen requires the audited 20-model "
            "door-and-lift archive"
        )

    donor_path = (
        input_root
        / FACILITY_VIDEO_SCREEN_DONOR_DIRECTORY
        / "02_models.bin"
    ).resolve()
    if not donor_path.is_file():
        raise DungeonBuildError(
            f"Facility-video screen donor is missing: {donor_path}"
        )
    donor = donor_path.read_bytes()
    if (
        len(donor) != FACILITY_VIDEO_SCREEN_DONOR_ARCHIVE_SIZE
        or _sha256(donor) != FACILITY_VIDEO_SCREEN_DONOR_ARCHIVE_SHA256
    ):
        raise DungeonBuildError(
            "Facility-video screen donor archive does not match retail field 617"
        )
    donor_entries = _indexed_bundle_entries(donor)
    if FACILITY_VIDEO_SCREEN_DONOR_MODEL_INDEX >= len(donor_entries):
        raise DungeonBuildError("Facility-video screen donor model is absent")
    screen = donor_entries[FACILITY_VIDEO_SCREEN_DONOR_MODEL_INDEX]
    if (
        len(screen) != FACILITY_VIDEO_SCREEN_MODEL_SIZE
        or _sha256(screen) != FACILITY_VIDEO_SCREEN_MODEL_SHA256
    ):
        raise DungeonBuildError(
            "Facility-video screen model does not match the audited 36-quad plane"
        )

    result = _rebuild_indexed_bundle(models, (*entries, screen))
    if (
        len(result) != FACILITY_VIDEO_SCREEN_MODELS_SIZE
        or _sha256(result) != FACILITY_VIDEO_SCREEN_MODELS_SHA256
        or len(_indexed_bundle_entries(result))
        != FACILITY_VIDEO_SCREEN_MODEL_INDEX + 1
    ):
        raise DungeonBuildError(
            "Defense Archive video-screen model transplant is not deterministic"
        )
    return result


def _field_actor_record(
    flags: int,
    x: int,
    z: int,
    model_index: int,
    y_rotation: int = 0,
    y: int = 0,
) -> bytes:
    if not 0 <= flags <= 0xFFFF or not 0 <= model_index <= 0xFFFF:
        raise DungeonBuildError("Field actor flags/model are outside u16")
    if not all(
        -0x8000 <= value <= 0x7FFF
        for value in (x, y, z, y_rotation)
    ):
        raise DungeonBuildError("Field actor position is outside s16")
    return struct.pack(
        "<Hhhh hhh H",
        flags,
        0,
        y_rotation,
        0,
        x,
        y,
        z,
        model_index,
    )


def _install_lift_service_archive_assets(
    header: bytes,
    models: bytes,
    room: LiftServiceArchiveRoom,
) -> tuple[bytes, bytes]:
    """Place a real freestanding archive console in source field 382."""

    expected = LiftServiceArchiveRoom(
        terminal_node_index=26,
        terminal_model_index=10,
        terminal_position=(0, 0, 110),
        terminal_y_rotation=-0x0400,
    )
    if room != expected:
        raise DungeonBuildError(
            "Lift-service archive room no longer matches the source-382 audit"
        )
    if (
        len(header) != 832
        or _sha256(header)
        != "02ae84183132c6f2970fe26ee65e778933507cc9feb7824d7cb687f60394ebb4"
        or struct.unpack_from("<H", header, 0x18C)[0] != 27
        or len(models) != 14828
        or _sha256(models)
        != "0ed054591deaccf554aae377db11e32f00a8c314008146e938c23cde5430808e"
    ):
        raise DungeonBuildError(
            "Lift-service archive assets do not match retail field 382"
        )

    entries = list(_indexed_bundle_entries(models))
    if (
        len(entries) != 11
        or _sha256(entries[room.terminal_model_index])
        != "6ee5f43b44758c66f9503615fd60bd14a775276a3ae0a8b0848cc974ebad79c5"
    ):
        raise DungeonBuildError(
            "Lift-service archive terminal donor slot is not the parked model"
        )
    terminal = build_archive_terminal_model()
    if (
        len(terminal) != ARCHIVE_TERMINAL_MODEL_SIZE
        or _sha256(terminal) != ARCHIVE_TERMINAL_MODEL_SHA256
    ):
        raise DungeonBuildError(
            "Lift-service archive terminal model is not deterministic"
        )
    preserved_entries = tuple(entries[: room.terminal_model_index])
    entries[room.terminal_model_index] = terminal
    rebuilt_models = _rebuild_indexed_bundle(models, entries)
    rebuilt_entries = _indexed_bundle_entries(rebuilt_models)
    if tuple(rebuilt_entries[: room.terminal_model_index]) != preserved_entries:
        raise DungeonBuildError(
            "Lift-service archive terminal changed a preserved retail model"
        )

    result_header = bytearray(header)
    node_offset = 0x190 + room.terminal_node_index * 16
    expected_parked_node = _field_actor_record(
        0,
        0,
        0,
        room.terminal_model_index,
    )
    if result_header[node_offset : node_offset + 16] != expected_parked_node:
        raise DungeonBuildError(
            "Lift-service archive terminal node is not the audited parked node"
        )
    x, y, z = room.terminal_position
    result_header[node_offset : node_offset + 16] = _field_actor_record(
        0x0010,
        x,
        z,
        room.terminal_model_index,
        room.terminal_y_rotation,
        y,
    )
    if (
        _sha256(result_header)
        != "f001b71ddd7df5724b16aa11d520471f0e3d46e45b5f77596715b9ddff72d848"
        or len(rebuilt_models) != 16140
        or _sha256(rebuilt_models)
        != "861e5cc4bfbc2ee8905513601cad55b6dbddd6c2cd19a1f2a845fd82441acd41"
    ):
        raise DungeonBuildError(
            "Lift-service archive terminal asset rebuild is not deterministic"
        )
    return bytes(result_header), rebuilt_models


def _install_distinct_archive_room_assets(
    header: bytes,
    walkmesh: bytes,
    models: bytes,
    room: DistinctArchiveRoom,
) -> tuple[bytes, bytes]:
    """Expose source 380's compact lab and isolate its local floor island."""

    expected = DistinctArchiveRoom(
        0,
        0x0092,
        31,
        42,
        32,
        -170,
        70,
        -190,
        70,
        726,
        4,
    )
    if room != expected:
        raise DungeonBuildError(
            "Distinct archive room no longer matches the source-380 audit"
        )
    if (
        len(header) != 1296
        or _sha256(header)
        != "3f9ffa9fdffd774bc8bf2f4424b8d925900eefee069dd9110ccd345557ccd594"
        or struct.unpack_from("<H", header, 0x18C)[0] != 56
        or _sha256(walkmesh)
        != "d5a935472400669525db9d1f540496b66ddcc10490125ad967ef7181d5a64782"
        or _sha256(models)
        != "d79f67d3e87a9bc20b2c61a32b7727edb487a88ca61953423c918d77cd48ba25"
    ):
        raise DungeonBuildError(
            "Distinct archive room inputs do not match source field 380"
        )
    model_entries = _indexed_bundle_entries(models)
    if (
        len(model_entries) != 43
        or len(model_entries[room.helper_model_index]) != 136
        or _sha256(model_entries[room.helper_model_index])
        != "c52a635d3e5e064b77a8acf631e206567c2abadaeea3b9ca0106164390b4a95c"
    ):
        raise DungeonBuildError(
            "Distinct archive west-panel model no longer matches its audit"
        )

    helper_offset = 0x190 + room.helper_entity * 16
    controller_offset = 0x190 + room.controller_entity * 16
    if header[helper_offset : helper_offset + 16] != _field_actor_record(
        0x0290,
        0,
        0,
        room.helper_model_index,
        0x0800,
    ) or header[controller_offset : controller_offset + 16] != _field_actor_record(
        0x01E0,
        0,
        0,
        0,
    ):
        raise DungeonBuildError(
            "Distinct archive helper/controller header records changed"
        )
    patched_header = bytearray(header)
    patched_header[controller_offset : controller_offset + 16] = (
        _field_actor_record(
            0x01E0,
            room.controller_x,
            room.controller_z,
            0,
        )
    )
    if _sha256(patched_header) != (
        "db31782c189a83b3360efae33e461af28ca8f242e8a1afca3ea8f3e254a70ef7"
    ):
        raise DungeonBuildError("Distinct archive controller header patch drifted")

    isolated_walkmesh = bytearray(walkmesh)
    if (
        isolated_walkmesh[0x00BE:0x00C0] != bytes.fromhex("0E 00")
        or isolated_walkmesh[0x00F2:0x00F4] != bytes.fromhex("0A 00")
    ):
        raise DungeonBuildError(
            "Distinct archive offstage walkmesh links changed from the audit"
        )
    isolated_walkmesh[0x00BE:0x00C0] = b"\xFF\xFF"
    isolated_walkmesh[0x00F2:0x00F4] = b"\xFF\xFF"
    if _sha256(isolated_walkmesh) != (
        "be961b782ebe2b118e37580a6abf93d0ca894de262865059aab643e835da031e"
    ):
        raise DungeonBuildError("Distinct archive walkmesh isolation drifted")
    return bytes(patched_header), bytes(isolated_walkmesh)


def _audit_storage_annex_terminal_and_chest_assets(
    header: bytes,
    models: bytes,
    actors: bytes,
    sprites: bytes,
) -> None:
    """Prove the donor's original computer and treasure art remain intact."""

    expected_header_sha256 = (
        "4015dba74e05433ce0574bebf20c76dd004272f574961825b48b74e9bbfbfa1e"
    )
    expected_models_sha256 = (
        "aff2acfc5174eabf374df807cad59aed8d8779136e7d7f795b2c9ca8878cb258"
    )
    if (
        len(header) != 0x340
        or _sha256(header) != expected_header_sha256
        or struct.unpack_from("<H", header, 0x18C)[0] != 27
    ):
        raise DungeonBuildError(
            "Storage-annex header is not the audited 27-node field-374 source"
        )
    if len(models) != 28060 or _sha256(models) != expected_models_sha256:
        raise DungeonBuildError(
            "Storage-annex model archive does not match the audited source"
        )
    if (
        len(actors) != 7944
        or _sha256(actors)
        != "763cd7beb2ef61789fb372532899621dbadecd341a4bc8679bd8a082125d187b"
        or len(sprites) != 8100
        or _sha256(sprites)
        != "337209b64be352028122c9f4ee69761027975592abf1cc09086acefcab36c347"
    ):
        raise DungeonBuildError(
            "Storage-annex native memory-cube/treasure asset banks changed"
        )
    model_entries = _indexed_bundle_entries(models)
    if (
        len(model_entries) != 12
        or _sha256(model_entries[7])
        != "475fb3ae6e42235ebb5e0acc62c6186bbf1d452e1c9d0b00a7a9401191b5812d"
        or _sha256(model_entries[8])
        != "3f2987485d9a0a1e40637071d578526619cf1c8e0730fb2ca45a9d8d92ba1195"
    ):
        raise DungeonBuildError(
            "Storage-annex native terminal models 7/8 failed their audit"
        )

    actor_table = header[0x190:]
    native_terminal = (
        _field_actor_record(0x0010, 0, 0, 7),
        _field_actor_record(0x0010, 0, 0, 8),
    )
    if (
        actor_table[22 * 16 : 23 * 16] != native_terminal[0]
        or actor_table[23 * 16 : 24 * 16] != native_terminal[1]
    ):
        raise DungeonBuildError(
            "Storage-annex original terminal nodes 22/23 changed"
        )

    actor_entries = _indexed_bundle_entries(actors)
    sprite_entries = _indexed_bundle_entries(sprites)
    if (
        len(actor_entries) != 3
        or len(sprite_entries) != 2
        or _sha256(actor_entries[1])
        != "42d88ff3385229ef53fdcf468b13ab61b6413a9ee47d756ece61756c246b8c52"
        or _sha256(actor_entries[2])
        != "fed1648acf4758bdffb60ebd04b762f4a69255aabe04e64d72c69dc3b893826c"
        or _sha256(sprite_entries[0])
        != "69060c5d8f1f25c3a3a4c438baaaabb18551f250abf66364b60cbbc28ac468d0"
        or _sha256(sprite_entries[1])
        != "8e3be5c4a63d06e76f6afd4d132169e40c846a4e4a3f8b7307bf23345f9088d1"
    ):
        raise DungeonBuildError(
            "Storage-annex memory-cube or treasure bank entries failed their audit"
        )


def _reconstruct_field_graphics_vram(
    graphics: bytes,
    *,
    label: str,
) -> tuple[bytearray, tuple[tuple[int, int, int, int], ...]]:
    """Replay one checked TIM-style field upload stream into word-addressed VRAM."""

    sector = 0x800
    vram_width = 1024
    vram_height = 512
    vram = bytearray(vram_width * vram_height * 2)
    rectangles: list[tuple[int, int, int, int]] = []
    cursor = 0
    block_index = 0
    while cursor < len(graphics):
        if cursor + 0x1C > len(graphics):
            raise DungeonBuildError(
                f"{label} graphics end inside upload {block_index} header"
            )
        upload_type = struct.unpack_from("<H", graphics, cursor)[0]
        (
            page_x,
            page_y,
            move_x,
            move_y,
            width,
            nominal_height,
            unknown,
            chunk_count,
        ) = struct.unpack_from("<8H", graphics, cursor + 4)
        if (
            upload_type not in (0x1200, 0x1201)
            or unknown != 1
            or width == 0
            or nominal_height == 0
            or chunk_count == 0
        ):
            raise DungeonBuildError(
                f"{label} graphics upload {block_index} has an invalid header"
            )
        height_table_end = cursor + 0x1C + chunk_count * 2
        if height_table_end > len(graphics):
            raise DungeonBuildError(
                f"{label} graphics upload {block_index} height table is truncated"
            )
        chunk_heights = struct.unpack_from(
            f"<{chunk_count}H",
            graphics,
            cursor + 0x1C,
        )
        if any(
            height == 0 or height > nominal_height
            for height in chunk_heights
        ):
            raise DungeonBuildError(
                f"{label} graphics upload {block_index} has an invalid chunk"
            )
        header_size = (
            (0x1C + chunk_count * 2 + sector - 1) // sector
        ) * sector
        cursor += header_size
        destination_x = page_x + move_x
        destination_y = page_y + move_y
        total_height = sum(chunk_heights)
        if (
            destination_x + width > vram_width
            or destination_y + total_height > vram_height
        ):
            raise DungeonBuildError(
                f"{label} graphics upload {block_index} exceeds PSX VRAM"
            )
        rectangles.append(
            (destination_x, destination_y, width, total_height)
        )
        for chunk_height in chunk_heights:
            data_size = width * chunk_height * 2
            padded_size = ((data_size + sector - 1) // sector) * sector
            if cursor + padded_size > len(graphics):
                raise DungeonBuildError(
                    f"{label} graphics upload {block_index} data is truncated"
                )
            for row in range(chunk_height):
                source_start = cursor + row * width * 2
                target_start = (
                    (destination_y + row) * vram_width + destination_x
                ) * 2
                vram[target_start : target_start + width * 2] = graphics[
                    source_start : source_start + width * 2
                ]
            destination_y += chunk_height
            cursor += padded_size
        block_index += 1
    if cursor != len(graphics):
        raise DungeonBuildError(f"{label} graphics do not end on an upload boundary")
    return vram, tuple(rectangles)


def _historical_prebacked_graphics_upload(
    target_graphics: bytes,
    miang_donor_graphics: bytes,
    officer_donor_graphics: bytes,
) -> bytes:
    """Append exact retail Miang and adult command-staff sprite pages."""

    if (
        len(target_graphics) != 180224
        or _sha256(target_graphics)
        != "4d411b597b06d9901789c73ffdb1e7dcaca4fb526b41d806fd01d5abf88a8d28"
        or len(miang_donor_graphics) != 122880
        or _sha256(miang_donor_graphics)
        != "a70b23574f0e0b9d6467c4388f475ca1ca1adf95c021502d74da26cf523d7cce"
        or len(officer_donor_graphics) != 301056
        or _sha256(officer_donor_graphics)
        != "e35798fd14ec0c2565a6aafb8812b610645a507982e0d138b4bbc02b76aaf0fa"
    ):
        raise DungeonBuildError(
            "Central Control historical-actor graphics failed provenance checks"
        )
    miang_vram, miang_rectangles = _reconstruct_field_graphics_vram(
        miang_donor_graphics,
        label="Retail Miang",
    )
    officer_vram, officer_rectangles = _reconstruct_field_graphics_vram(
        officer_donor_graphics,
        label="Retail field-366 command staff",
    )
    _target_vram, target_rectangles = _reconstruct_field_graphics_vram(
        target_graphics,
        label="Central Control",
    )
    expected_target = (
        (0, 480, 256, 7),
        (320, 0, 288, 192),
        (320, 192, 248, 64),
        (576, 192, 24, 64),
    )
    expected_miang = (
        (0, 480, 256, 7),
        (322, 0, 62, 252),
        (832, 0, 64, 220),
        (322, 256, 62, 172),
        (384, 0, 64, 128),
        (320, 0, 2, 428),
        (896, 0, 64, 8),
    )
    expected_officers = (
        (0, 480, 256, 14),
        (320, 0, 64, 256),
        (448, 0, 64, 256),
        (832, 0, 64, 233),
        (385, 0, 48, 256),
        (528, 0, 48, 256),
        (576, 0, 48, 240),
        (896, 0, 64, 144),
        (960, 0, 64, 129),
        (656, 0, 32, 256),
        (624, 0, 32, 128),
        (512, 0, 16, 192),
        (433, 0, 15, 192),
        (624, 160, 32, 80),
        (704, 0, 32, 64),
        (384, 0, 1, 192),
    )
    if (
        target_rectangles != expected_target
        or miang_rectangles != expected_miang
        or officer_rectangles != expected_officers
    ):
        raise DungeonBuildError(
            "Central Control historical-actor VRAM layout changed from its audit"
        )

    def overlaps(
        left: tuple[int, int, int, int],
        right: tuple[int, int, int, int],
    ) -> bool:
        lx, ly, lw, lh = left
        rx, ry, rw, rh = right
        return (
            lx < rx + rw
            and rx < lx + lw
            and ly < ry + rh
            and ry < ly + lh
        )

    def normalized_rows(
        vram: bytes,
        source: tuple[int, int, int, int],
    ) -> bytes:
        x, y, width, height = source
        return b"".join(
            vram[
                ((y + row) * 1024 + x) * 2 :
                ((y + row) * 1024 + x + width) * 2
            ]
            for row in range(height)
        )

    def build_upload(
        rows: bytes,
        destination: tuple[int, int, int, int],
    ) -> bytes:
        x, y, width, height = destination
        chunk_heights = (16,) * (height // 16)
        if height % 16:
            chunk_heights += (height % 16,)
        header = bytearray(0x800)
        struct.pack_into("<H", header, 0, 0x1200)
        struct.pack_into(
            "<8H",
            header,
            4,
            x,
            0,
            0,
            y,
            width,
            16,
            1,
            len(chunk_heights),
        )
        struct.pack_into(
            f"<{len(chunk_heights)}H",
            header,
            0x1C,
            *chunk_heights,
        )
        upload = bytearray(header)
        cursor = 0
        for chunk_height in chunk_heights:
            size = width * chunk_height * 2
            chunk = rows[cursor : cursor + size]
            upload.extend(chunk)
            upload.extend(bytes((-len(chunk)) % 0x800))
            cursor += size
        if cursor != len(rows):
            raise DungeonBuildError(
                "Historical actor graphics upload did not consume its page"
            )
        return bytes(upload)

    page_contracts = (
        (
            "Miang",
            normalized_rows(miang_vram, (320, 256, 64, 172)),
            (320, 256, 64, 172),
            22016,
            "f57361613184aa3ea0e333aac2fe68aca62c32d9e4fe9d8fff8b49cddee03c90",
            24576,
            "e0fe087af054dc9c27a88a9cf0db9ef90ab4b55716af35f3595a48889ef1fc50",
        ),
        (
            "Systems Officer",
            normalized_rows(officer_vram, (896, 0, 64, 144)),
            (384, 256, 64, 144),
            18432,
            "86bbc4f5c6c8c49696e3dc014da6c37cc187685ca4cc439768c8fcebf9253e92",
            20480,
            "a2aaf424af5df2415067cb52cb223d8495de93238eb8901634ba3e557c8b9c19",
        ),
        (
            "Launch Director",
            normalized_rows(officer_vram, (960, 0, 64, 129)),
            (448, 256, 64, 129),
            16512,
            "712003556fbc8477bb48e742c652fbbb20a7420cd5d65bb05fb8dcd8b982a893",
            20480,
            "5378edf86be1f9d422df60956ba81a99cf476ce4f0dd4e292c9cecc5617729b2",
        ),
    )
    result = target_graphics
    occupied = list(target_rectangles)
    for (
        label,
        rows,
        destination,
        expected_rows_size,
        expected_rows_hash,
        expected_upload_size,
        expected_upload_hash,
    ) in page_contracts:
        if any(overlaps(destination, rectangle) for rectangle in occupied):
            raise DungeonBuildError(
                f"Retail {label} sprite page overlaps Central Control graphics"
            )
        if (
            len(rows) != expected_rows_size
            or _sha256(rows) != expected_rows_hash
        ):
            raise DungeonBuildError(
                f"Retail {label} normalized sprite page failed its audit"
            )
        upload = build_upload(rows, destination)
        if (
            len(upload) != expected_upload_size
            or _sha256(upload) != expected_upload_hash
        ):
            raise DungeonBuildError(
                f"Retail {label} graphics upload is not deterministic"
            )
        result += upload
        occupied.append(destination)

    if (
        len(result) != 245760
        or _sha256(result)
        != "dc60d25ba5c4e73891e498363816abf043fe61a87081f828cd20bb45bd6abf7a"
    ):
        raise DungeonBuildError(
            "Central Control graphics with adult historical actors failed its audit"
        )
    return result


