def _pointed_script_body(editor: ScriptEditor, pointer: int) -> bytes:
    """Return one entry-point body through the next pointed routine."""

    later = sorted(
        {
            candidate
            for entity in range(editor.entity_count)
            for script_index in range(32)
            if (candidate := editor.get_script_pointer(entity, script_index))
            > pointer
        }
    )
    end = later[0] if later else editor.bytecode_size
    return editor.bytecode[pointer:end]


def _calls_helper(body: bytes, helper_entity: int) -> bool:
    """Recognize either retail blocking or asynchronous script-4 calls."""

    return any(
        body[index] in (0x07, 0x09)
        and body[index + 1] == helper_entity
        and body[index + 2] & 0x1F == 4
        for index in range(max(0, len(body) - 2))
    )


def _has_audited_door_animation(
    editor: ScriptEditor,
    pointer: int,
) -> bool:
    """Recognize a finite retail FE1B or detailed-model OP19 door slide."""

    if pointer <= 0 or pointer >= editor.bytecode_size:
        return False
    body = _pointed_script_body(editor, pointer)
    if bytes(editor.bytecode[pointer : pointer + 4]) == bytes.fromhex(
        "05 84 03 00"
    ):
        # Field 573's e5 helper is a finite CALL/STOP wrapper around one
        # retail door routine. The callee contains the native 0x77 cues and
        # bounded FE1B interpolation and is unchanged by the compact adapter.
        native = _pointed_script_body(
            editor,
            KRELIAN_COMPUTER_ROOM_DOOR_SUBROUTINE_PC,
        )
        return (
            len(native) == 152
            and _sha256(native)
            == KRELIAN_COMPUTER_ROOM_DOOR_SUBROUTINE_SHA256
            and b"\x74\x77\x80" in native
            and native.endswith(b"\xE0\x00\x38")
        )
    if (
        len(body) == 7
        and body[0] == 0x4E
        and body[5:] == b"\xC0\x00"
    ):
        delta_x, delta_z = struct.unpack_from("<hh", body, 1)
        return (delta_x == 0) != (delta_z == 0)
    # Field 507's native laboratory leaf uses one finite OP10 interpolation
    # from its wall pivot to the checked open endpoint.  Its owner supplies
    # SFX 0x77; this helper is the exact retail movement tail.
    if body == bytes.fromhex(
        "10 00 F4 01 78 00 00 00 E0 10 01 00"
    ):
        return True
    if (
        len(body) >= 10
        and body[0] == 0x19
        and body[-1] == 0x00
        and (len(body) - 1) % 9 == 0
    ):
        steps = (len(body) - 1) // 9
        if not 1 <= steps <= DOOR_ANIMATION_GRACE_FRAMES:
            return False
        positions: list[tuple[int, int]] = []
        for offset in range(0, len(body) - 1, 9):
            chunk = body[offset : offset + 9]
            if (
                chunk[0] != 0x19
                or chunk[5] != 0xC0
                # Unlike an authored pause, the unrolled model animation
                # needs retail WAIT 0: yield once and then advance.
                or chunk[6:9] != bytes.fromhex("26 00 80")
            ):
                return False
            positions.append(struct.unpack_from("<hh", chunk, 1))
        x_values = [x for x, _z in positions]
        z_values = [z for _x, z in positions]
        x_deltas = {
            later - earlier
            for earlier, later in zip(x_values, x_values[1:])
        }
        z_deltas = {
            later - earlier
            for earlier, later in zip(z_values, z_values[1:])
        }
        return (
            len(x_deltas) <= 1
            and len(z_deltas) <= 1
            and (not x_deltas or x_deltas <= {-2, 0, 2})
            and (not z_deltas or z_deltas <= {-2, 0, 2})
            and ((x_deltas or {0}) != {0}) != ((z_deltas or {0}) != {0})
        )
    if len(body) < 28:
        return False
    core = body[:28]
    variable = core[1:3]
    limit = struct.unpack_from("<H", core, 6)[0]
    exit_target = struct.unpack_from("<H", core, 9)[0]
    loop_target = struct.unpack_from("<H", core, 25)[0]
    delta_x, delta_y = struct.unpack_from("<hh", core, 14)
    return (
        core[0] == 0x37
        and core[3] == 0x02
        and core[4:6] == variable
        and 1 <= limit <= DOOR_ANIMATION_GRACE_FRAMES
        and core[8] == 0x43
        and exit_target == pointer + 27
        and core[11:14] == bytes.fromhex("C6 FE 1B")
        and delta_x in (-2, 2)
        and delta_y == 0
        and core[18:21] == b"\x26\x00\x80"
        and core[21] == 0x3C
        and core[22:24] == variable
        and core[24] == 0x01
        and loop_target == pointer + 3
        and core[27] == 0x00
    )


def _player_waypoint(
    editor: ScriptEditor,
    body: bytes,
    destination_field: int,
    destination_parameter: int,
) -> tuple[int, int]:
    """Extract a retail FE68 or bounded party-script door waypoint."""

    transition = _change_field(destination_field, destination_parameter)
    transition_index = body.find(transition)
    if transition_index < 0:
        raise DungeonBuildError(
            "Door action has no checked transition after its player waypoint"
        )
    compact_return_prefix = b"\x09\x05\x24\x07\x01\x24" + _wait(10)
    if (
        destination_field == 388
        and destination_parameter == 0
        and body == compact_return_prefix + transition
        and editor.entity_count == 11
    ):
        crossing_pointer = editor.get_script_pointer(1, 4)
        crossing = _pointed_script_body(editor, crossing_pointer)
        if (
            len(crossing) != 9
            or crossing[:3] != bytes.fromhex("1F 10 4A")
            or crossing[7:] != b"\xC0\x00"
        ):
            raise DungeonBuildError(
                "Compact final-room native party crossing changed"
            )
        return struct.unpack_from("<hh", crossing, 3)
    retail_markers = tuple(
        index
        for index in range(max(0, transition_index - 6))
        if body[index : index + 2] == b"\xFE\x68"
    )
    bounded_calls = tuple(
        index
        for index in range(max(0, transition_index - 2))
        if (
            body[index] in (0x07, 0x09)
            and body[index + 1] == 0xFF
            and body[index + 2] & 0x20
        )
    )
    if len(retail_markers) == 1 and not bounded_calls:
        return struct.unpack_from("<hh", body, retail_markers[0] + 2)
    if retail_markers or len(bounded_calls) != 1:
        raise DungeonBuildError(
            "Door action does not contain exactly one player waypoint"
        )

    script_index = body[bounded_calls[0] + 2] & 0x1F
    # Historical field-507 adapters placed three playable-character stubs at
    # e1..e3; the ordinary field convention uses e2..e12. Keep this branch for
    # their older bounded-door layouts.
    lab_pointers = {
        editor.get_script_pointer(entity, script_index)
        for entity in range(1, 4)
    }
    lab_tail = {
        editor.get_script_pointer(entity, script_index)
        for entity in range(4, 13)
    }
    party_entities = (
        range(1, 4)
        if editor.entity_count == 25
        and len(lab_pointers) == 1
        and 0 not in lab_pointers
        and lab_tail == {0}
        else range(2, 13)
    )
    pointers = {
        editor.get_script_pointer(entity, script_index)
        for entity in party_entities
    }
    if len(pointers) != 1 or 0 in pointers:
        raise DungeonBuildError(
            "Bounded door waypoint is not shared by all party actors"
        )
    pointer = pointers.pop()
    delayed_prefix = _wait(DOOR_ANIMATION_GRACE_FRAMES)
    delayed = editor.bytecode[
        pointer : pointer + len(delayed_prefix) + 15
    ]
    if delayed.startswith(delayed_prefix):
        x, z = struct.unpack_from("<hh", delayed, len(delayed_prefix) + 1)
        expected = _delayed_door_waypoint_script(x, z)
        routine = delayed
    else:
        routine = editor.bytecode[pointer : pointer + 15]
        if len(routine) != 15 or routine[0] != 0x4B:
            raise DungeonBuildError(
                "Bounded door waypoint does not use the audited party routine"
            )
        x, z = struct.unpack_from("<hh", routine, 1)
        max_steps = struct.unpack_from("<H", routine, 6)[0] & 0x7FFF
        expected = _party_actor_waypoint_script(x, z, max_steps)
    if routine != expected:
        raise DungeonBuildError(
            "Bounded door waypoint does not finish with its exact-position snap"
        )
    return x, z


def _nearest_direction(dx: int, dz: int) -> int:
    """Quantize a nonzero world-space vector to an entry-direction octant."""

    if dx == 0 and dz == 0:
        raise DungeonBuildError("Cannot infer an arrival direction from zero vector")
    angle = math.atan2(dx, dz)
    return int(math.floor(angle / (math.pi / 4) + 0.5)) & 7


def verify_visible_door_contracts(
    prepared: Sequence[PreparedReplacement],
) -> None:
    """Prove every audited visible door is actionable, animated, and paired."""

    items = {
        item.target_field: item
        for item in prepared
        if item.target_field is not None
    }
    active_door_contracts = (
        *VISIBLE_DOOR_CONTRACTS,
        *PREOPENED_DOOR_CONTRACTS,
    )
    contracts = {
        (contract.field, contract.entity): contract
        for contract in active_door_contracts
    }
    if len(contracts) != len(active_door_contracts):
        raise DungeonBuildError("Visible-door contract contains a duplicate trigger")
    inert_contracts = {
        (contract.field, contract.entity): contract
        for contract in INERT_DOOR_CONTRACTS
    }
    if len(inert_contracts) != len(INERT_DOOR_CONTRACTS):
        raise DungeonBuildError("Inert-door contract contains a duplicate trigger")
    overlap = sorted(set(contracts) & set(inert_contracts))
    if overlap:
        raise DungeonBuildError(
            f"Door trigger(s) declared both active and inert: {overlap}"
        )
    passages = {
        (contract.field, contract.entity): contract
        for contract in OPEN_PASSAGE_CONTRACTS
    }
    if len(passages) != len(OPEN_PASSAGE_CONTRACTS):
        raise DungeonBuildError(
            "Open-passage contract contains a duplicate trigger"
        )

    expected_helpers: dict[int, set[int]] = {}
    for contract in VISIBLE_DOOR_CONTRACTS:
        item = items.get(contract.field)
        if item is None:
            raise DungeonBuildError(
                f"Visible door field {contract.field} is not prepared"
            )
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        action = editor.get_script_pointer(contract.entity, 2)
        collision = editor.get_script_pointer(contract.entity, 3)
        if action == collision or editor.bytecode[action] == 0x00:
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} has no "
                "active X action"
            )
        if editor.bytecode[collision] != 0x00:
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} activates "
                "on collision instead of X"
            )
        body = _pointed_script_body(editor, action)
        compact_native_door = (
            contract == DoorContract(507, 4, (5,), 388, 0, 388, 14)
            and editor.entity_count == 11
        )
        if compact_native_door:
            helper_pointer = editor.get_script_pointer(5, 4)
            expected_body = (
                b"\x09\x05\x24\x07\x01\x24"
                + _wait(10)
                + _change_field(388, 0)
            )
            reciprocal = contracts.get((388, 14))
            if (
                body != expected_body
                or not _calls_helper(body, 5)
                or not _has_audited_door_animation(editor, helper_pointer)
                or _player_waypoint(editor, body, 388, 0)
                != KRELIAN_COMPUTER_ROOM_RETURN_WAYPOINT
                or reciprocal is None
                or reciprocal.destination_field != 507
                or reciprocal.reciprocal_field != 507
                or reciprocal.reciprocal_entity != 4
            ):
                raise DungeonBuildError(
                    "Krelian compact computer-room native return door or "
                    "reciprocal contract drifted"
                )
            expected_helpers.setdefault(contract.field, set()).add(5)
            continue
        if b"\x74\x77\x80" not in body:
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} does not "
                "play the native door sound"
            )
        for helper in contract.helper_entities:
            helper_pointer = editor.get_script_pointer(helper, 4)
            if not _has_audited_door_animation(editor, helper_pointer):
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} helper "
                    f"e{helper} has no audited door animation"
                )
            if not _calls_helper(body, helper):
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} does "
                    f"not call helper e{helper}"
                )
            if contract.destination_field is not None:
                if b"\x09" + bytes((helper, 0x24)) in body:
                    raise DungeonBuildError(
                        f"Visible door {contract.field}:e{contract.entity} "
                        f"still blocks on helper e{helper}'s model animation"
                    )
                if b"\x07" + bytes((helper, 0x24)) not in body:
                    raise DungeonBuildError(
                        f"Visible door {contract.field}:e{contract.entity} "
                        f"does not start helper e{helper} asynchronously"
                    )
            else:
                opening = b"\x09" + bytes((helper, 0x24))
                closing = b"\x07" + bytes((helper, 0x25))
                if opening not in body:
                    raise DungeonBuildError(
                        f"Local door {contract.field}:e{contract.entity} "
                        f"does not serialize native opening helper e{helper}"
                    )
                if closing not in body:
                    raise DungeonBuildError(
                        f"Local door {contract.field}:e{contract.entity} "
                        f"does not run native closing helper e{helper}"
                    )
                if not (
                    body.index(b"\xFE\x54") < body.index(opening)
                    and body.index(b"\xFE\x53") < body.index(closing)
                ):
                    raise DungeonBuildError(
                        f"Local door {contract.field}:e{contract.entity} "
                        f"helper e{helper} can strand cinematic control"
                    )
            expected_helpers.setdefault(contract.field, set()).add(helper)

        if contract.destination_field is not None:
            transition = _change_field(
                contract.destination_field,
                contract.destination_parameter,
            )
            if transition not in body:
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} has no "
                    f"transition to {contract.destination_field}/"
                    f"{contract.destination_parameter}"
                )
            transition_offsets = tuple(
                index
                for index in range(max(0, len(body) - len(transition) + 1))
                if body[index : index + len(transition)] == transition
            )
            transition_index = transition_offsets[0]
            if b"\xFE\x68" in body:
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} still "
                    "uses an unbounded FE68 party walk"
                )
            asynchronous_waypoints = tuple(
                index
                for index in range(max(0, len(body) - 2))
                if (
                    body[index : index + 2] == b"\x07\xFF"
                    and body[index + 2] & 0x20
                )
            )
            expected_branch_count = (
                2
                if (contract.field, contract.entity)
                in {(723, 13), (375, 13)}
                else 1
            )
            if len(asynchronous_waypoints) != expected_branch_count:
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} does "
                    f"not have {expected_branch_count} finite pre-cinematic "
                    "party launch(es)"
                )
            script_indices = {
                body[waypoint + 2] & 0x1F
                for waypoint in asynchronous_waypoints
            }
            if len(script_indices) != 1:
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} uses "
                    "different bounded party scripts across its branches"
                )
            opening = b"\xFE\x54\x74\x77\x80"
            for waypoint in asynchronous_waypoints:
                if body[waypoint + 3 : waypoint + 3 + len(opening)] != opening:
                    raise DungeonBuildError(
                        f"Visible door {contract.field}:e{contract.entity} does "
                        "not allocate its bounded party walk before cinematic "
                        "control"
                    )
            grace = _wait(DOOR_TRANSITION_GRACE_FRAMES)
            grace_offsets = tuple(
                index
                for index in range(len(body))
                if body[index : index + len(grace) + 1] == grace + b"\x0E"
            )
            if (
                len(grace_offsets) != expected_branch_count
                or len(transition_offsets) != expected_branch_count
                or any(
                    not waypoint < grace_offset < transition_offset
                    for waypoint, grace_offset, transition_offset in zip(
                        asynchronous_waypoints,
                        grace_offsets,
                        transition_offsets,
                        strict=True,
                    )
                )
            ):
                raise DungeonBuildError(
                    f"Visible door {contract.field}:e{contract.entity} does "
                    "not use one audited finite grace and transition per branch"
                )
            _player_waypoint(
                editor,
                body,
                contract.destination_field,
                contract.destination_parameter,
            )
        else:
            if contract.field != 372 or (
                contract.entity not in LOCAL_DOOR_TRANSFER_CONTROL
            ):
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} has no "
                    "audited deterministic transfer"
                )
            if any(
                opcode in body
                for opcode in (b"\x09\xFF", b"\xFE\x68", b"\xFE\x24")
            ):
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} retains "
                    "a runtime-dependent party handoff"
                )

            request, _direction, state = LOCAL_DOOR_TRANSFER_CONTROL[
                contract.entity
            ]
            expected_action = (
                _set_variable_s16(LOCAL_DOOR_TRANSFER_VARIABLE, 0)
                + b"\xFE\x54\x74\x77\x80"
                + b"".join(
                    b"\x09" + bytes((helper, 0x24))
                    for helper in contract.helper_entities
                )
                + bytes.fromhex("80 98 00 00 80")
                + _set_variable_s16(
                    LOCAL_DOOR_TRANSFER_VARIABLE,
                    request,
                )
                + _wait(LOCAL_DOOR_TRANSFER_HOLD_FRAMES)
                + _set_variable_s16(LOCAL_DOOR_TRANSFER_VARIABLE, 0)
                + _wait(LOCAL_DOOR_TRANSFER_SETTLE_FRAMES)
                + _set_variable_s16(0x0400, state)
                + bytes.fromhex("80 98 00 E0 80")
                + b"\xFE\x53"
                + b"".join(
                    b"\x07" + bytes((helper, 0x25))
                    for helper in contract.helper_entities
                )
                + b"\x00"
            )
            if body != expected_action:
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} does "
                    "not match the deterministic control-safe owner action"
                )

            cinematic_start = body.index(b"\xFE\x54") + 2
            cinematic_end = body.index(b"\xFE\x53")
            cinematic = body[cinematic_start:cinematic_end]
            if any(
                opcode in cinematic
                for opcode in (b"\x07\xFF", b"\x09\xFF", b"\xFE\x68", b"\xFE\x24")
            ):
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} allocates "
                    "a party task while cinematic control is disabled"
                )

            update_pointers = {
                editor.get_script_pointer(entity, 1)
                for entity in range(2, 13)
            }
            if len(update_pointers) != 1 or 0 in update_pointers:
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} party "
                    "actors do not share one deterministic update dispatcher"
                )
            update_pointer = update_pointers.pop()
            transfer_routes = tuple(
                (
                    LOCAL_DOOR_TRANSFER_CONTROL[entity][0],
                    *LOCAL_DOOR_TRANSFER_ENDPOINTS[entity],
                    LOCAL_DOOR_TRANSFER_CONTROL[entity][1],
                )
                for entity in sorted(LOCAL_DOOR_TRANSFER_CONTROL)
            )
            expected_update = _local_door_party_update_script(
                update_pointer,
                transfer_routes,
            )
            actual_update = editor.bytecode[
                update_pointer : update_pointer + len(expected_update)
            ]
            if actual_update != expected_update:
                raise DungeonBuildError(
                    f"Local door {contract.field}:e{contract.entity} has a "
                    "malformed party update dispatcher"
                )

        if contract.reciprocal_field is None:
            if contract.reciprocal_entity is not None:
                raise DungeonBuildError(
                    f"One-way door {contract.field}:e{contract.entity} has "
                    "a reciprocal entity without a field"
                )
            continue
        reciprocal_key = (
            contract.reciprocal_field,
            contract.reciprocal_entity,
        )
        reciprocal_door = contracts.get(reciprocal_key)
        reciprocal_passage = passages.get(reciprocal_key)
        if (reciprocal_door is None) == (reciprocal_passage is None):
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} has no "
                "single declared reciprocal threshold"
            )
        reciprocal = (
            reciprocal_door
            if reciprocal_door is not None
            else reciprocal_passage
        )
        assert reciprocal is not None
        if (
            reciprocal.reciprocal_field != contract.field
            or reciprocal.reciprocal_entity != contract.entity
        ):
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} has an "
                "asymmetric reciprocal declaration"
            )
        if (
            contract.destination_field is not None
            and reciprocal.destination_field != contract.field
        ):
            raise DungeonBuildError(
                f"Visible door {contract.field}:e{contract.entity} does not "
                "lead to a threshold that returns to its room"
            )

    for contract in PREOPENED_DOOR_CONTRACTS:
        item = items.get(contract.field)
        if item is None:
            raise DungeonBuildError(
                f"Preopened door field {contract.field} is not prepared"
            )
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        action_pointer = editor.get_script_pointer(contract.entity, 2)
        collision_pointer = editor.get_script_pointer(contract.entity, 3)
        action = _pointed_script_body(editor, action_pointer)
        collision = _pointed_script_body(editor, collision_pointer)
        transition = _change_field(
            contract.destination_field,
            contract.destination_parameter,
        )
        collision_is_valid = editor.bytecode[collision_pointer] == 0
        if (
            editor.bytecode[action_pointer] == 0
            or not collision_is_valid
            or transition not in action
            or b"\x09\xFF" not in action
            or b"\xFE\x68" in action
            or b"\x74\x77\x80" in action
            or any(_calls_helper(action, helper) for helper in contract.helper_entities)
        ):
            raise DungeonBuildError(
                f"Preopened door {contract.field}:e{contract.entity} does not "
                "use its bounded crossing-only threshold"
            )
        for helper in contract.helper_entities:
            helper_pointer = editor.get_script_pointer(helper, 4)
            if not _has_audited_door_animation(editor, helper_pointer):
                raise DungeonBuildError(
                    f"Preopened door {contract.field}:e{contract.entity} helper "
                    f"e{helper} lost its finite opening animation"
                )
            expected_helpers.setdefault(contract.field, set()).add(helper)

    # Inert doors deliberately retain their architectural leaves and bounded
    # native OP4E routines. Their owner action must be exactly the input-safe
    # error dialogue: no helper dispatch, sound, movement, or field change can
    # be smuggled into a non-route control.
    for contract in INERT_DOOR_CONTRACTS:
        item = items.get(contract.field)
        if item is None:
            raise DungeonBuildError(
                f"Inert door field {contract.field} is not prepared"
            )
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        action_pointer = editor.get_script_pointer(contract.entity, 2)
        collision_pointer = editor.get_script_pointer(contract.entity, 3)
        expected_action = (
            _automatic_dialogue_body(
                (contract.dialogue_id,),
                routine_pc=action_pointer,
            )
            + b"\x00"
        )
        action = _pointed_script_body(editor, action_pointer)
        if action != expected_action or editor.bytecode[collision_pointer] != 0x00:
            raise DungeonBuildError(
                f"Inert door {contract.field}:e{contract.entity} is not an "
                "offline-dialogue-only X control"
            )
        for helper in contract.helper_entities:
            helper_pointer = editor.get_script_pointer(helper, 4)
            if not _has_audited_door_animation(editor, helper_pointer):
                raise DungeonBuildError(
                    f"Inert door {contract.field}:e{contract.entity} helper "
                    f"e{helper} lost its bounded native animation"
                )
            if _calls_helper(action, helper):
                raise DungeonBuildError(
                    f"Inert door {contract.field}:e{contract.entity} still "
                    f"dispatches helper e{helper}"
                )
            expected_helpers.setdefault(contract.field, set()).add(helper)

    # Reject every native or finite synthesized door helper left outside a
    # reciprocal visible-door contract or the one explicit inert-door set.
    for field, item in items.items():
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        actual = {
            entity
            for entity in range(editor.entity_count)
            if (
                (pointer := editor.get_script_pointer(entity, 4)) > 0
                and _has_audited_door_animation(editor, pointer)
            )
        }
        expected = expected_helpers.get(field, set())
        if actual != expected:
            raise DungeonBuildError(
                f"Field {field} door-helper inventory mismatch: "
                f"actual {sorted(actual)}, declared {sorted(expected)}"
            )

    for contract in OPEN_PASSAGE_CONTRACTS:
        item = items.get(contract.field)
        if item is None:
            raise DungeonBuildError(
                f"Open passage field {contract.field} is not prepared"
            )
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        action = editor.get_script_pointer(contract.entity, 2)
        collision = editor.get_script_pointer(contract.entity, 3)
        if contract.activation_script_index not in (1, 3):
            raise DungeonBuildError(
                f"Open passage {contract.field}:e{contract.entity} uses an "
                "unaudited activation slot"
            )
        activation = editor.get_script_pointer(
            contract.entity,
            contract.activation_script_index,
        )
        if (
            editor.bytecode[action] != 0x00
            or editor.bytecode[activation] == 0x00
            or (
                contract.activation_script_index == 1
                and editor.bytecode[collision] != 0x00
            )
        ):
            raise DungeonBuildError(
                f"Open passage {contract.field}:e{contract.entity} no longer "
                "uses its audited automatic threshold"
            )
        body = _pointed_script_body(editor, activation)
        fixed = _change_field(
            contract.destination_field,
            contract.destination_parameter,
        )
        custom = _custom_field_transition(
            contract.destination_field,
            contract.destination_parameter,
            0,
            32,
        )
        if fixed not in body and custom not in body:
            raise DungeonBuildError(
                f"Open passage {contract.field}:e{contract.entity} has no "
                "audited destination"
            )
        reciprocal_key = (
            contract.reciprocal_field,
            contract.reciprocal_entity,
        )
        reciprocal_passage = passages.get(reciprocal_key)
        reciprocal_door = contracts.get(reciprocal_key)
        if (reciprocal_passage is None) == (reciprocal_door is None):
            raise DungeonBuildError(
                f"Open passage {contract.field}:e{contract.entity} has no "
                "single reciprocal threshold"
            )
        reciprocal = (
            reciprocal_passage
            if reciprocal_passage is not None
            else reciprocal_door
        )
        assert reciprocal is not None
        if (
            reciprocal.reciprocal_field != contract.field
            or reciprocal.reciprocal_entity != contract.entity
            or reciprocal.destination_field != contract.field
        ):
            raise DungeonBuildError(
                f"Open passage {contract.field}:e{contract.entity} is not "
                "reciprocal"
                )


def verify_save_point_visual_contracts(
    prepared: Sequence[PreparedReplacement],
) -> None:
    """Keep native computers and chests distinct from the one route Save.

    Target 722 entity 14 invisibly controls the room's original model-7/model-8
    computer; its former gold memory-cube update and collision remain parked.
    Entity 15 retains field 374's native animated treasure presentation and
    one-time object-award flow in target 722 and both optional storage annexes.
    Target 725 entity 16 remains the only active gold memory cube and retains
    its exact FE55 Save-menu action.
    """

    items = {
        item.target_field: item
        for item in prepared
        if item.target_field is not None
    }
    required_fields = {722, 385, 386, 725}
    if not required_fields.issubset(items):
        raise DungeonBuildError(
            "Save-point presentation verification requires fields "
            f"{sorted(required_fields)}"
        )

    storage = items[722]
    storage_editor = ScriptEditor(storage.components[SCRIPT_INDEX])
    parked_pointer = 0x0182
    if (
        storage_editor.bytecode[parked_pointer] != 0x00
        or storage_editor.get_script_pointer(14, 1) != parked_pointer
        or storage_editor.get_script_pointer(14, 3) != parked_pointer
    ):
        raise DungeonBuildError(
            "Storage-annex entity 14 still updates or collides as its former "
            "memory cube"
        )

    storage_header = storage.header
    storage_models = storage.components[MODEL_INDEX]
    storage_actors = storage.components[ACTOR_INDEX]
    storage_sprites = storage.components[SPRITE_INDEX]
    if storage_header is not None:
        if (
            len(storage_header) != 0x340
            or struct.unpack_from("<H", storage_header, 0x18C)[0] != 27
            or _sha256(storage_header)
            != "4015dba74e05433ce0574bebf20c76dd004272f574961825b48b74e9bbfbfa1e"
            or len(storage_models) != 28060
            or _sha256(storage_models)
            != "aff2acfc5174eabf374df807cad59aed8d8779136e7d7f795b2c9ca8878cb258"
            or len(storage_actors) != 7944
            or _sha256(storage_actors)
            != "763cd7beb2ef61789fb372532899621dbadecd341a4bc8679bd8a082125d187b"
            or len(storage_sprites) != 8100
            or _sha256(storage_sprites)
            != "337209b64be352028122c9f4ee69761027975592abf1cc09086acefcab36c347"
        ):
            raise DungeonBuildError(
                "Storage-annex computer/chest presentation failed its audited "
                "native asset contract"
            )
    elif storage_models:
        raise DungeonBuildError(
            "Storage-annex models were supplied without their native header"
        )

    expected_controller = _static_door_controller_init(
        40,
        150,
        requires_facing=False,
        interaction_half_width=0x20,
    )
    controller_pointer = storage_editor.get_script_pointer(14, 0)
    if (
        storage_editor.bytecode[
            controller_pointer : controller_pointer + len(expected_controller)
        ]
        != expected_controller
    ):
        raise DungeonBuildError(
            "Storage-annex entity 14 is not the sole facility-terminal controller"
        )

    authority_write = _set_var_bit(
        INTERLOCK_VARIABLE,
        ADDRESS_RECORD_BIT,
    )
    terminal_pointer = storage_editor.get_script_pointer(14, 2)
    terminal_action = _pointed_script_body(storage_editor, terminal_pointer)
    if (
        not terminal_action.startswith(authority_write)
        or _dialog(8) not in terminal_action
        or _dialog(1) in terminal_action
    ):
        raise DungeonBuildError(
            "Storage-annex computer lost its combined archive or clue write"
        )

    chest_pointers = tuple(
        storage_editor.get_script_pointer(15, script_index)
        for script_index in range(4)
    )
    if chest_pointers != (0x019D, 0x01E6, 0x01E7, 0x0241):
        raise DungeonBuildError(
            "Storage-annex entity 15 no longer uses its four native chest scripts"
        )
    item_assignment = (
        b"\x35"
        + _u16(0x041E)
        + _s16(OMEGASOL_ITEM_ID)
        + b"\x40"
    )
    opened_check = _jump_if_bit_clear(
        INTERLOCK_VARIABLE,
        STORAGE_ANNEX_CHEST_OPENED_MASK,
        0x006A,
    )
    opened_write = _set_var_bit(
        INTERLOCK_VARIABLE,
        STORAGE_ANNEX_CHEST_OPENED_BIT,
    )
    if (
        storage_editor.bytecode[0x0059 : 0x0059 + len(item_assignment)]
        != item_assignment
        or storage_editor.bytecode[0x005F : 0x005F + len(opened_check)]
        != opened_check
        or storage_editor.bytecode[0x006D : 0x006D + len(opened_write)]
        != opened_write
        or _sha256(storage_editor.bytecode[0x019D:0x01E6])
        != "b96a676d57e16926e7bcfab06bdd776da8f1b9fdcf68470f040a2a7536a44f8a"
        or storage_editor.bytecode[0x01E6] != 0x00
        or _sha256(storage_editor.bytecode[0x01E7:0x0241])
        != "7a9ff15926d4236dfdf64b6d662b44eaee76514893eab3b39ef965ed100447c9"
        or storage_editor.bytecode[0x0241] != 0x00
    ):
        raise DungeonBuildError(
            "Storage-annex entity 15 lost its audited Omegasol chest contract"
        )

    # Both new dead ends retain the same retail computer and chest assets but
    # carry independent archive text and independent bits in 0x03FA.  The
    # former memory-cube entity is an X-only baked-model controller and can
    # never open the Save menu.
    annex_bits = {
        385: ANNEX_TREASURE_A_OPENED_BIT,
        386: ANNEX_TREASURE_B_OPENED_BIT,
    }
    for field, opened_bit in annex_bits.items():
        annex = items[field]
        editor = ScriptEditor(annex.components[SCRIPT_INDEX])
        if annex.header is not None:
            if (
                _sha256(annex.header)
                != "4015dba74e05433ce0574bebf20c76dd004272f574961825b48b74e9bbfbfa1e"
                or _sha256(annex.components[MODEL_INDEX])
                != "aff2acfc5174eabf374df807cad59aed8d8779136e7d7f795b2c9ca8878cb258"
                or _sha256(annex.components[ACTOR_INDEX])
                != "763cd7beb2ef61789fb372532899621dbadecd341a4bc8679bd8a082125d187b"
                or _sha256(annex.components[SPRITE_INDEX])
                != "337209b64be352028122c9f4ee69761027975592abf1cc09086acefcab36c347"
            ):
                raise DungeonBuildError(
                    f"Optional storage annex {field} lost its native assets"
                )
        elif annex.components[MODEL_INDEX]:
            raise DungeonBuildError(
                f"Optional storage annex {field} supplied models without its "
                "native header"
            )
        init_pointer = editor.get_script_pointer(14, 0)
        action_pointer = editor.get_script_pointer(14, 2)
        action = _pointed_script_body(editor, action_pointer)
        if (
            editor.bytecode[
                init_pointer : init_pointer + len(expected_controller)
            ]
            != expected_controller
            or editor.get_script_pointer(14, 1) != 0x0182
            or editor.get_script_pointer(14, 3) != 0x0182
            or action
            != _automatic_dialogue_body((2,), routine_pc=action_pointer)
            + b"\x00"
        ):
            raise DungeonBuildError(
                f"Optional storage annex {field} lost its mail terminal"
            )
        opened_check = _jump_if_bit_clear(
            ANNEX_TREASURE_VARIABLE,
            1 << opened_bit,
            0x006A,
        )
        opened_write = _set_var_bit(ANNEX_TREASURE_VARIABLE, opened_bit)
        if (
            tuple(
                editor.get_script_pointer(15, script_index)
                for script_index in range(4)
            )
            != (0x019D, 0x01E6, 0x01E7, 0x0241)
            or editor.bytecode[0x0059 : 0x0059 + len(item_assignment)]
            != item_assignment
            or editor.bytecode[0x005F : 0x005F + len(opened_check)]
            != opened_check
            or editor.bytecode[0x006D : 0x006D + len(opened_write)]
            != opened_write
            or _sha256(editor.bytecode[0x019D:0x01E6])
            != "b96a676d57e16926e7bcfab06bdd776da8f1b9fdcf68470f040a2a7536a44f8a"
            or _sha256(editor.bytecode[0x01E7:0x0241])
            != "7a9ff15926d4236dfdf64b6d662b44eaee76514893eab3b39ef965ed100447c9"
        ):
            raise DungeonBuildError(
                f"Optional storage annex {field} lost its one-time Omegasol"
            )

    save = items[725]
    save_editor = ScriptEditor(save.components[SCRIPT_INDEX])
    save_init_pointer = save_editor.get_script_pointer(16, 0)
    save_action_pointer = save_editor.get_script_pointer(16, 2)
    save_collision_pointer = save_editor.get_script_pointer(16, 3)
    if (
        save_editor.bytecode[save_init_pointer : save_init_pointer + 3]
        != bytes.fromhex("0B 01 80")
        or save_editor.bytecode[
            save_action_pointer : save_action_pointer + 8
        ]
        != bytes.fromhex("FE 99 00 FE 55 FE 87 00")
        or save_editor.bytecode[
            save_collision_pointer : save_collision_pointer + 3
        ]
        != bytes.fromhex("FE 99 00")
    ):
        raise DungeonBuildError(
            "Magnetic Conduit entity 16 is not the sole audited memory-cube Save"
        )

    memory_actor_sha256 = (
        "42d88ff3385229ef53fdcf468b13ab61b6413a9ee47d756ece61756c246b8c52"
    )
    memory_sprite_sha256 = (
        "69060c5d8f1f25c3a3a4c438baaaabb18551f250abf66364b60cbbc28ac468d0"
    )
    supplied_asset_fields = {
        field
        for field, item in items.items()
        if (
            item.components[ACTOR_INDEX]
            or item.components[SPRITE_INDEX]
        )
    }
    if supplied_asset_fields:
        if supplied_asset_fields != set(items):
            raise DungeonBuildError(
                "Save-point asset audit received only a partial route inventory"
            )

        def indexed_hashes(component: bytes) -> set[str]:
            # Retail fields with no actor or sprite banks encode the
            # component as a lone zero count rather than an indexed archive
            # with an offset table.
            if component == b"\x00\x00\x00\x00":
                return set()
            return {
                _sha256(entry)
                for entry in _indexed_bundle_entries(component)
            }

        asset_fields: set[int] = set()
        for field, item in items.items():
            actor_hashes = indexed_hashes(item.components[ACTOR_INDEX])
            sprite_hashes = indexed_hashes(item.components[SPRITE_INDEX])
            if (
                memory_actor_sha256 in actor_hashes
                or memory_sprite_sha256 in sprite_hashes
            ):
                if not (
                    memory_actor_sha256 in actor_hashes
                    and memory_sprite_sha256 in sprite_hashes
                ):
                    raise DungeonBuildError(
                        f"Field {field} carries only half of the audited "
                        "memory-cube asset"
                    )
                asset_fields.add(field)
        if asset_fields != {722, 385, 386, 725}:
            raise DungeonBuildError(
                "Memory-cube assets occur outside their audited storage/Save "
                f"fields: {sorted(asset_fields)}"
            )

    active_save_actions = []
    native_save_action = bytes.fromhex("FE 99 00 FE 55 FE 87 00")
    for field, item in items.items():
        editor = ScriptEditor(item.components[SCRIPT_INDEX])
        for entity in range(editor.entity_count):
            pointer = editor.get_script_pointer(entity, 2)
            if (
                editor.bytecode[
                    pointer : pointer + len(native_save_action)
                ]
                == native_save_action
            ):
                active_save_actions.append((field, entity))
    if active_save_actions != [(725, 16)]:
        raise DungeonBuildError(
            "Active Save actions do not resolve exclusively to field 725 "
            f"entity 16: {active_save_actions}"
        )


def verify_control_and_archive_terminal_roles(
    prepared: Sequence[PreparedReplacement],
) -> None:
    """Keep switch exceptions isolated and make every lore console readable."""

    items = {
        item.target_field: item
        for item in prepared
        if item.target_field is not None
    }
    required_fields = {
        361,
        366,
        367,
        368,
        369,
        370,
        371,
        376,
        377,
        378,
        379,
        382,
        383,
        724,
        728,
    }
    missing_fields = sorted(required_fields - items.keys())
    if missing_fields:
        raise DungeonBuildError(
            "Control/archive terminal verification is missing target fields "
            f"{missing_fields}"
        )

    # In the auxiliary-grid room, entities 12 and 13 are the two floor-console
    # sections and both operate the same Auxiliary Grid bypass. Dormant entity
    # 16 is the independent controller for the green-lit computer suspended
    # from the overhead arm; it alone carries Directive 0320 and optional mail.
    auxiliary = ScriptEditor(items[361].components[SCRIPT_INDEX])
    auxiliary_write = _set_var_bit(
        INTERLOCK_VARIABLE,
        AUXILIARY_INTERLOCK_BIT,
    )
    directive_write = _set_var_bit(
        INTERLOCK_VARIABLE,
        DIRECTIVE_RECORD_BIT,
    )
    left_switch_init_pointer = auxiliary.get_script_pointer(12, 0)
    right_switch_init_pointer = auxiliary.get_script_pointer(13, 0)
    hanging_archive_init_pointer = auxiliary.get_script_pointer(16, 0)
    expected_left_switch_init = _static_door_controller_init(
        -31,
        165,
        requires_facing=False,
        interaction_half_width=0x08,
    )
    expected_right_switch_init = _static_door_controller_init(
        110,
        117,
        requires_facing=False,
        interaction_half_width=0x1E,
    )
    expected_hanging_archive_init = _static_door_controller_init(
        -31,
        -105,
        requires_facing=False,
        interaction_half_width=0x08,
    )
    left_switch_action = _pointed_script_body(
        auxiliary,
        auxiliary.get_script_pointer(12, 2),
    )
    right_switch_action = _pointed_script_body(
        auxiliary,
        auxiliary.get_script_pointer(13, 2),
    )
    hanging_archive_action = _pointed_script_body(
        auxiliary,
        auxiliary.get_script_pointer(16, 2),
    )
    if (
        auxiliary.bytecode[
            left_switch_init_pointer : left_switch_init_pointer
            + len(expected_left_switch_init)
        ]
        != expected_left_switch_init
        or auxiliary.bytecode[
            right_switch_init_pointer : right_switch_init_pointer
            + len(expected_right_switch_init)
        ]
        != expected_right_switch_init
        or auxiliary.bytecode[
            hanging_archive_init_pointer : hanging_archive_init_pointer
            + len(expected_hanging_archive_init)
        ]
        != expected_hanging_archive_init
        or not left_switch_action.startswith(
            auxiliary_write + bytes.fromhex("74 37 80")
        )
        or _dialog(1) not in left_switch_action
        or _dialog(0) in left_switch_action
        or directive_write in left_switch_action
        or not right_switch_action.startswith(
            auxiliary_write + bytes.fromhex("74 37 80")
        )
        or _dialog(1) not in right_switch_action
        or _dialog(0) in right_switch_action
        or directive_write in right_switch_action
        or not hanging_archive_action.startswith(directive_write)
        or _dialog(0) not in hanging_archive_action
        or _dialog(1) in hanging_archive_action
        or auxiliary_write in hanging_archive_action
        or auxiliary.bytecode.count(auxiliary_write) != 2
        or auxiliary.bytecode.count(directive_write) != 1
    ):
        raise DungeonBuildError(
            "Auxiliary room lost its dual-floor-switch/hanging-mail separation"
        )

    # The Defense Archive has seven physical desk-console banks. Entity 13
    # remains the ABCD station; e20..e25 own aligned console controllers.
    # Ordinary record readers remain facing-gated. The long east U-bank keeps
    # its wide reach, while shared arcade/video e21 moves its invisible pivot
    # toward the visible console and enlarges its facing-gated frontage.
    # The southeast bank e21 always offers the nested NUKE/Missile Command
    # arcade directory or the seven-still player gated by the real Video Disk
    # from apparatus e26.
    # The other five banks retain their historical/control functions.
    defense_item = items[376]
    defense_spec = _CLONE_BY_TARGET[376]
    defense_terminals = defense_spec.defense_archive_record_terminals
    defense_video = defense_spec.defense_archive_video_event
    defense_nuke = defense_spec.defense_archive_nuke_game
    defense_missile = defense_spec.defense_archive_missile_game
    if (
        len(defense_terminals) != 6
        or defense_item.header is None
        or defense_video is None
        or defense_nuke is None
        or defense_missile is None
        or defense_missile.terminal_entity != defense_nuke.terminal_entity
        or len(defense_spec.static_door_exits) != 1
    ):
        raise DungeonBuildError(
            "Defense Archive does not declare all console/video controllers"
        )
    _validate_defense_archive_record_terminal_walkmesh(
        defense_item.components[1],
        defense_terminals,
    )
    _validate_defense_archive_walkmesh_point(
        defense_item.components[1],
        defense_video.disk_approach_position,
        defense_video.disk_approach_walkmesh_triangle,
        "video disk pickup",
    )
    if (
        len(defense_item.header) != DEFENSE_ARCHIVE_RECORD_HEADER_SIZE
        or _sha256(defense_item.header)
        != DEFENSE_ARCHIVE_RECORD_HEADER_SHA256
        or struct.unpack_from("<H", defense_item.header, 0x18C)[0] != 44
    ):
        raise DungeonBuildError(
            "Defense Archive lost its audited controller/video-plane header"
        )
    if (
        len(defense_item.components[MODEL_INDEX])
        != FACILITY_VIDEO_SCREEN_MODELS_SIZE
        or _sha256(defense_item.components[MODEL_INDEX])
        != FACILITY_VIDEO_SCREEN_MODELS_SHA256
        or len(_indexed_bundle_entries(defense_item.components[MODEL_INDEX]))
        != FACILITY_VIDEO_SCREEN_MODEL_INDEX + 1
    ):
        raise DungeonBuildError(
            "Defense Archive lost its native retail video-screen model"
        )
    defense_editor = ScriptEditor(defense_item.components[SCRIPT_INDEX])
    if (
        defense_editor.entity_count != 28
        or len(defense_item.components[SCRIPT_INDEX])
        != DEFENSE_ARCHIVE_RECORD_SCRIPT_SIZE
        or _sha256(defense_item.components[SCRIPT_INDEX])
        != DEFENSE_ARCHIVE_RECORD_SCRIPT_SHA256
    ):
        raise DungeonBuildError(
            "Defense Archive readers/video no longer match the audited "
            "entities 20..26 script: "
            f"{len(defense_item.components[SCRIPT_INDEX])} bytes, "
            f"SHA-256 {_sha256(defense_item.components[SCRIPT_INDEX])}"
        )
    missile_worker_pointers = {
        entity: defense_editor.get_script_pointer(entity, 1)
        for entity in MISSILE_WORKER_ENTITIES
    }
    missile_idle_pointer = defense_editor.get_script_pointer(
        defense_nuke.terminal_entity,
        1,
    )
    missile_worker_bodies = {
        entity: _pointed_script_body(defense_editor, pointer)
        for entity, pointer in missile_worker_pointers.items()
    }
    if (
        tuple(missile_worker_pointers) != MISSILE_WORKER_ENTITIES
        or len(set(missile_worker_pointers.values()))
        != len(MISSILE_WORKER_ENTITIES)
        or defense_editor.bytecode[missile_idle_pointer] != 0
        or any(
            pointer == missile_idle_pointer
            or not body
            or not body.endswith(b"\x00")
            for entity, pointer in missile_worker_pointers.items()
            for body in (missile_worker_bodies[entity],)
        )
        or not all(
            signature in defense_editor.bytecode
            for signature in (
                _set_variable_s16(
                    MISSILE_MODE_REQUEST_VARIABLE,
                    MISSILE_MODE_ARMING,
                ),
                _set_variable_s16(
                    MISSILE_MODE_REQUEST_VARIABLE,
                    MISSILE_MODE_PAUSED,
                ),
                _set_variable_s16(
                    MISSILE_MODE_REQUEST_VARIABLE,
                    MISSILE_MODE_STOPPED,
                ),
                _set_variable_s16(MISSILE_RUN_VARIABLE, 1),
                _set_variable_s16(MISSILE_RUN_VARIABLE, 0),
                _set_variable_s16(MISSILE_WAVE_COMPLETE_VARIABLE, 1),
            )
        )
    ):
        raise DungeonBuildError(
            "Defense Archive Missile Command lost its finite real-time "
            "script-1 worker/lifecycle contract"
        )
    try:
        defense_dialogue = parse_dialogue(
            defense_item.components[DIALOGUE_INDEX]
        )
    except DialogueFormatError as exc:
        raise DungeonBuildError(
            "Defense Archive shared-console dialogue is malformed"
        ) from exc
    expected_console_dialogues = (
        (
            defense_nuke.prompt_dialogue,
            40,
            4,
            "<Opcode:01:FF>MEDIA TERMINAL\n"
            "     Arcade Games\n"
            "     Video Disk\n"
            "     Leave<Close>",
        ),
        (
            defense_nuke.arcade_prompt_dialogue,
            40,
            4,
            "<Opcode:01:FF>ARCADE DIRECTORY\n"
            "     Play NUKE\n"
            "     Missile Command\n"
            "     Back<Close>",
        ),
        (
            39,
            58,
            4,
            "<Opcode:01:FF>WEST BULKHEAD CONTROL\n"
            "     Operate bulkhead\n"
            "     Read safety report\n"
            "     Leave<Close>",
        ),
        (40, 58, 2, "CUSTODIAN DEFENSE ACTIVE\nBULKHEAD RELEASE LOCKED<Close>"),
        (41, 42, 1, "WEST BULKHEAD OPEN<Close>"),
    )
    if len(defense_dialogue.blocks) <= max(row[0] for row in expected_console_dialogues) or any(
        (
            defense_dialogue.blocks[dialogue_id].width,
            defense_dialogue.blocks[dialogue_id].height,
            defense_dialogue.blocks[dialogue_id].text,
        )
        != (width, height, text)
        for dialogue_id, width, height, text in expected_console_dialogues
    ):
        raise DungeonBuildError(
            "Defense Archive lost its arcade or west-bulkhead menu dialogue"
        )
    defense_authorization = defense_spec.authorization_terminal
    defense_lift = defense_spec.defense_bay_lift_exit
    if defense_authorization is None or defense_lift is None:
        raise DungeonBuildError(
            "Defense Archive lost its authorization or north-lift control"
        )
    _validate_defense_archive_interaction_layout(
        defense_authorization,
        defense_lift,
        defense_terminals,
        defense_video,
        defense_spec.static_door_exits[0],
    )
    if defense_authorization.controller_position is None:
        raise DungeonBuildError(
            "Defense Archive authorization lost its console frontage"
        )
    expected_authorization_init = _static_door_controller_init(
        *defense_authorization.controller_position,
        requires_facing=defense_authorization.controller_requires_facing,
        interaction_half_width=(
            defense_authorization.controller_interaction_half_width
        ),
    )
    actual_authorization_init = _pointed_script_body(
        defense_editor,
        defense_editor.get_script_pointer(defense_authorization.entity, 0),
    )
    expected_lift_init = _static_door_controller_init(
        defense_lift.controller_x,
        defense_lift.controller_z,
        requires_facing=False,
        interaction_half_width=defense_lift.interaction_half_width,
    )
    actual_lift_init = _pointed_script_body(
        defense_editor,
        defense_editor.get_script_pointer(defense_lift.controller_entity, 0),
    )
    lift_party_script_index = 30
    lift_transition = _defense_bay_lift_transition_body(
        defense_lift,
        lift_party_script_index,
    )
    lift_action_pointer = defense_editor.get_script_pointer(
        defense_lift.controller_entity,
        2,
    )
    expected_lift_action_builder = _RoutineBuilder(lift_action_pointer)
    expected_lift_action_builder.jump_if_bit_clear(
        defense_lift.variable,
        defense_lift.required_mask,
        "locked",
    )
    expected_lift_action_builder.emit(lift_transition)
    expected_lift_action_builder.label("locked")
    expected_lift_action_builder.emit(
        _automatic_dialogue_body(
            (defense_lift.locked_dialogue,),
            routine_pc=expected_lift_action_builder.pc,
        )
        + b"\x00"
    )
    expected_lift_action = expected_lift_action_builder.finish()
    actual_lift_action = _pointed_script_body(
        defense_editor,
        lift_action_pointer,
    )
    lift_collision_pointer = defense_editor.get_script_pointer(
        defense_lift.controller_entity,
        3,
    )
    actual_lift_collision = _pointed_script_body(
        defense_editor,
        lift_collision_pointer,
    )
    lift_poll_pointer = defense_editor.get_script_pointer(0, 1)
    expected_lift_poll = _defense_bay_lift_proximity_poll(
        lift_poll_pointer,
        defense_lift,
    )
    actual_lift_poll = _pointed_script_body(
        defense_editor,
        lift_poll_pointer,
    )
    expected_lift_party_waypoint = _party_actor_waypoint_script(
        0,
        285,
        DOOR_MOVEMENT_MAX_STEPS,
    )
    if (
        actual_authorization_init != expected_authorization_init
        or actual_lift_init != expected_lift_init
        or actual_lift_action != expected_lift_action
        or actual_lift_collision != b"\x00"
        or actual_lift_poll != expected_lift_poll
        or lift_poll_pointer in (lift_action_pointer, lift_collision_pointer)
        or any(
            defense_editor.get_script_pointer(entity, lift_party_script_index)
            != defense_editor.get_script_pointer(2, lift_party_script_index)
            for entity in range(3, 13)
        )
        or _pointed_script_body(
            defense_editor,
            defense_editor.get_script_pointer(2, lift_party_script_index),
        )
        != expected_lift_party_waypoint
    ):
        raise DungeonBuildError(
            "Defense Archive code or automatic lift threshold escaped its "
            "visible frontage"
        )
    for terminal in defense_terminals:
        x, z = terminal.controller_position
        expected_record = _field_actor_record(0x01E0, x, z, 0)
        record_offset = 0x190 + terminal.entity * 16
        expected_init = _static_door_controller_init(
            x,
            z,
            requires_facing=terminal.controller_requires_facing,
            interaction_half_width=terminal.controller_interaction_half_width,
            interaction_half_depth=terminal.controller_interaction_half_depth,
        )
        init_pointer = defense_editor.get_script_pointer(terminal.entity, 0)
        action_pointer = defense_editor.get_script_pointer(terminal.entity, 2)
        expected_action = (
            _automatic_dialogue_body(
                (terminal.dialogue_id,),
                routine_pc=action_pointer,
            )
            + b"\x00"
        )
        actual_action = _pointed_script_body(defense_editor, action_pointer)
        if terminal.entity == defense_nuke.terminal_entity:
            teardown = _nuke_teardown_body(defense_nuke.screen_entity)
            teardown_offset = actual_action.find(teardown)
            video_offset = (
                teardown_offset + len(teardown)
                if teardown_offset >= 0
                else -1
            )
            expected_video_action = (
                _facility_video_terminal_action(
                    defense_video,
                    action_pointer + video_offset,
                )
                if video_offset >= 0
                else b""
            )
            leave_offset = (
                video_offset + len(expected_video_action)
                if video_offset >= 0
                else -1
            )
            video_action = (
                actual_action[video_offset:leave_offset]
                if video_offset >= 0 and leave_offset >= 0
                else b""
            )
            leave_action = (
                actual_action[leave_offset:]
                if leave_offset >= 0
                else b""
            )
            expected_leave_action = _actor_dialog_reset_body() + b"\xFE\x53\x00"
            outer_choice = (
                _choice_dialog(defense_nuke.prompt_dialogue)
                + b"\xA9\x13\x9C"
            )
            outer_choice_offset = actual_action.find(outer_choice)
            outer_branch_offset = (
                outer_choice_offset + len(outer_choice)
                if outer_choice_offset >= 0
                else -1
            )
            expected_outer_branches = (
                b"\x02"
                + _u16(0x0014)
                + _u16(2)
                + b"\x41"
                + _u16(action_pointer + video_offset)
                + b"\x02"
                + _u16(0x0014)
                + _u16(1)
                + b"\x40"
                + _u16(action_pointer + leave_offset)
                if video_offset >= 0
                else b""
            )
            arcade_choice = (
                _choice_dialog(defense_nuke.arcade_prompt_dialogue)
                + b"\xA9\x13\x9C"
            )
            arcade_choice_offset = actual_action.find(arcade_choice)
            arcade_branch_offset = (
                arcade_choice_offset + len(arcade_choice)
                if arcade_choice_offset >= 0
                else -1
            )
            arcade_branch_size = 19
            arcade_branches = (
                actual_action[
                    arcade_branch_offset : arcade_branch_offset
                    + arcade_branch_size
                ]
                if arcade_branch_offset >= 0
                else b""
            )
            nuke_select_pc = (
                struct.unpack_from("<H", arcade_branches, 6)[0]
                if len(arcade_branches) == arcade_branch_size
                else -1
            )
            missile_select_pc = (
                struct.unpack_from("<H", arcade_branches, 14)[0]
                if len(arcade_branches) == arcade_branch_size
                else -1
            )
            back_target_pc = (
                struct.unpack_from("<H", arcade_branches, 17)[0]
                if len(arcade_branches) == arcade_branch_size
                else -1
            )
            expected_arcade_branches = (
                b"\x02"
                + _u16(0x0014)
                + _u16(1)
                + b"\x41"
                + _u16(nuke_select_pc)
                + b"\x02"
                + _u16(0x0014)
                + _u16(2)
                + b"\x41"
                + _u16(missile_select_pc)
                + _jump(back_target_pc)
                if min(nuke_select_pc, missile_select_pc, back_target_pc) >= 0
                else b""
            )
            nuke_select_offset = nuke_select_pc - action_pointer
            missile_select_offset = missile_select_pc - action_pointer
            missile_selector = _set_variable_s16(MISSILE_OUTCOME_VARIABLE, 1)
            persistence_offset = missile_select_offset + len(missile_selector)
            persistence_pc = action_pointer + persistence_offset
            nuke_selector = (
                _set_variable_s16(MISSILE_OUTCOME_VARIABLE, 0)
                + _jump(persistence_pc)
            )
            nested_arcade_menu_valid = (
                arcade_branches == expected_arcade_branches
                and back_target_pc == action_pointer
                and arcade_branch_offset + arcade_branch_size
                == nuke_select_offset
                and missile_select_offset == nuke_select_offset + len(nuke_selector)
                and actual_action[
                    nuke_select_offset : nuke_select_offset + len(nuke_selector)
                ]
                == nuke_selector
                and actual_action[
                    missile_select_offset : persistence_offset
                ]
                == missile_selector
                and outer_choice_offset < arcade_choice_offset
                < nuke_select_offset
                < missile_select_offset
                < persistence_offset
                < video_offset
            )
            arcade_action = actual_action[:video_offset]
            missile_action_signatures = (
                _arcade_unpack_records_body(defense_nuke, defense_missile),
                _arcade_unpack_v1_records_body(defense_nuke, defense_missile),
                _missile_pack_records_body(defense_nuke, defense_missile),
                _copy_variable(
                    defense_missile.high_score_variable,
                    MISSILE_SCORE_VARIABLE,
                ),
                _copy_variable(
                    defense_missile.best_wave_variable,
                    MISSILE_WAVE_VARIABLE,
                ),
                _nuke_centered_text_body("MISSILE COMMAND", 47),
                _nuke_centered_text_body("THE END", 49),
                _set_variable_s16(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[0], 1),
                _set_variable_s16(MISSILE_INTERCEPTOR_ACTIVE_VARIABLES[2], 1),
            )
            missile_helper_signatures = (
                _set_variable_s16(MISSILE_CITY_MASK_VARIABLE, 0x3F),
                _set_variable_s16(
                    MISSILE_AMMO_VARIABLE,
                    MISSILE_INITIAL_AMMO,
                ),
                _set_variable_s16(MISSILE_EXPLOSION_PHASE_VARIABLE, 1),
                _random_modulo_variable(
                    MISSILE_ENEMY_START_X_VARIABLES[0],
                    25,
                ),
                _random_modulo_variable(
                    MISSILE_ENEMY_TARGET_INDEX_VARIABLES[0],
                    len(MISSILE_TARGET_COLUMNS) - 1,
                ),
            )
            image_load = b"\xFE\x77\x01"
            image_begin = b"\xFE\x77\x00"
            image_commit = b"\xFE\x77\x02"
            terminal_action_valid = (
                defense_nuke.terminal_entity == defense_video.computer_entity
                and defense_missile.terminal_entity
                == defense_nuke.terminal_entity
                and actual_action.count(teardown) == 1
                and video_offset > 0
                and video_action == expected_video_action
                and leave_action == expected_leave_action
                and outer_choice_offset >= 0
                and outer_choice_offset < video_offset
                and actual_action[
                    outer_branch_offset : outer_branch_offset
                    + len(expected_outer_branches)
                ]
                == expected_outer_branches
                and nested_arcade_menu_valid
                and all(
                    signature in arcade_action
                    for signature in missile_action_signatures
                )
                and all(
                    signature in defense_editor.bytecode
                    for signature in missile_helper_signatures
                )
                and video_action.count(image_begin)
                == len(defense_video.clip_dialogues)
                and video_action.count(image_load)
                == len(defense_video.clip_dialogues)
                and video_action.count(image_commit)
                == len(defense_video.clip_dialogues)
                and video_action.count(
                    b"\x74" + _immediate(defense_video.sound_id)
                )
                == len(defense_video.clip_dialogues) + 3
                and all(
                    b"\xF5" + _u16(dialogue_id) + b"\x53\x9C"
                    in video_action
                    for dialogue_id in defense_video.clip_dialogues
                )
                and all(
                    b"\xF5" + _u16(dialogue_id) + b"\x53\x9C"
                    + _facility_video_screen_fade_body(0xFF)
                    in video_action
                    for dialogue_id in defense_video.clip_dialogues
                )
                and all(
                    b"\xF5" + _u16(dialogue_id) + b"\x03\x9C"
                    not in video_action
                    for dialogue_id in defense_video.clip_dialogues
                )
                and b"\xFE\x9D" not in video_action
                and b"\xFE\x9C" not in video_action
                and b"\x24" + bytes((defense_video.screen_entity,))
                in video_action
                and b"\x25" + bytes((defense_video.screen_entity,))
                in video_action
                and _facility_video_screen_camera_body() in video_action
                and _historical_camera_release_body() in video_action
                and _set_var_bit(
                    defense_video.state_variable,
                    defense_video.acquired_bit,
                )
                not in actual_action
                and _clear_var_bit(
                    defense_video.state_variable,
                    defense_video.acquired_bit,
                )
                not in actual_action
                and b"\x8B" + _immediate(defense_video.inventory_item_id)
                in video_action
                and _choice_dialog(defense_video.insert_prompt_dialogue)
                in video_action
                and b"\xA9\x12\x9C" in video_action
                and b"\xFE\x0D\x00\x80" not in video_action
                and _actor_dialog_reset_body() in video_action
                and video_action.endswith(b"\xFE\x53\x00")
                and b"\xFE\x77\x01"
                + _u16(defense_nuke.background_file_id)
                in actual_action[:video_offset]
                and b"\xFE\x77\x01" + _u16(defense_nuke.atlas_file_id)
                in actual_action[:video_offset]
                and b"\xE1" in actual_action[:video_offset]
                and b"\xFE\xE0\x01" in actual_action[:video_offset]
                and b"\xFE\xE0\x00" in actual_action[:video_offset]
                and b"\x24" + bytes((defense_nuke.screen_entity,))
                in actual_action[:video_offset]
                and b"\x25" + bytes((defense_nuke.screen_entity,))
                in actual_action[:video_offset]
                and _facility_video_screen_camera_body()
                in actual_action[:video_offset]
                and _historical_camera_release_body()
                in actual_action[:video_offset]
                and _set_variable_s16(
                    defense_nuke.signature_variable,
                    NUKE_SIGNATURE,
                )
                in actual_action[:video_offset]
                and _copy_variable(
                    defense_nuke.high_score_variable,
                    NUKE_SCORE_VARIABLE,
                )
                in actual_action[:video_offset]
                and _copy_variable(
                    defense_nuke.best_level_variable,
                    NUKE_LEVEL_VARIABLE,
                )
                in actual_action[:video_offset]
                and all(
                    b"\x31" + _u16(mask) in actual_action[:video_offset]
                    for mask in (
                        PAD_MASK_UP,
                        PAD_MASK_RIGHT,
                        PAD_MASK_DOWN,
                        PAD_MASK_LEFT,
                        PAD_MASK_TRIANGLE,
                        PAD_MASK_CROSS,
                        PAD_MASK_CIRCLE,
                    )
                )
                and b"\x31" + _u16(PAD_MASK_START)
                not in actual_action[:video_offset]
            )
        elif terminal.entity == 23:
            west = defense_spec.defense_archive_west_bulkhead
            retired_camera_body = (
                _historical_camera_shot_body(
                    west.camera,
                    enter_camera_mode=True,
                )
                if west is not None
                else b""
            )
            retired_camera_release = _historical_camera_release_body()
            terminal_action_valid = (
                west is not None
                and not west.move_camera
                and actual_action == _defense_archive_west_bulkhead_action(
                    west, action_pointer
                )
                and retired_camera_body not in actual_action
                and retired_camera_release not in actual_action
                and (
                    b"\x33" * len(retired_camera_body)
                    + b"\x74"
                    + _immediate(west.sound_id)
                )
                in actual_action
                and (
                    _wait()
                    + b"\x33" * len(retired_camera_release)
                    + _dialogue_sequence((west.opened_dialogue,))
                )
                in actual_action
                and b"\x74" + _immediate(west.sound_id) in actual_action
                and all(
                    _calls_helper(actual_action, helper)
                    for helper in west.helper_entities
                )
                and _set_var_bit(
                    west.opened_variable,
                    west.opened_bit,
                )
                in actual_action
                and not any(
                    _change_field(destination, parameter) in actual_action
                    for destination, parameter in (
                        (377, 0),
                        (384, 0),
                    )
                )
            )
        else:
            terminal_action_valid = actual_action == expected_action
        if (
            defense_item.header[
                record_offset : record_offset + len(expected_record)
            ]
            != expected_record
            or (
                # Repointing only the west action leaves its former body
                # unreferenced after this STOP-terminated initializer. Its
                # next pointed routine is consequently farther away.
                defense_editor.bytecode[init_pointer : init_pointer + len(expected_init)]
                if terminal.entity == 23
                else _pointed_script_body(defense_editor, init_pointer)
            ) != expected_init
            or not terminal_action_valid
            or (
                terminal.entity in missile_worker_pointers
                and defense_editor.get_script_pointer(terminal.entity, 1)
                != missile_worker_pointers[terminal.entity]
            )
            or (
                terminal.entity not in missile_worker_pointers
                and defense_editor.bytecode[
                    defense_editor.get_script_pointer(terminal.entity, 1)
                ]
                != 0
            )
            or defense_editor.bytecode[
                defense_editor.get_script_pointer(terminal.entity, 3)
            ]
            != 0
        ):
            raise DungeonBuildError(
                f"Defense Archive console bank entity {terminal.entity} lost "
                "its audited record/control interaction"
            )

    disk_x, disk_z = defense_video.disk_position
    expected_disk_record = _field_actor_record(0x01E0, disk_x, disk_z, 0)
    disk_record_offset = 0x190 + defense_video.disk_entity * 16
    disk_init_pointer = defense_editor.get_script_pointer(
        defense_video.disk_entity,
        0,
    )
    disk_action_pointer = defense_editor.get_script_pointer(
        defense_video.disk_entity,
        2,
    )
    disk_init = _pointed_script_body(defense_editor, disk_init_pointer)
    disk_action = _pointed_script_body(defense_editor, disk_action_pointer)
    pickup_examination = _dialog(defense_video.pickup_dialogue)
    pickup_choice = (
        _choice_dialog(defense_video.pickup_choice_dialogue) + b"\xA9\x12\x9C"
    )
    inventory_award = b"\x8C" + _immediate(defense_video.inventory_item_id)
    pickup_receipt = _dialog(defense_video.pickup_receipt_dialogue)
    persistence_write = _set_var_bit(
        defense_video.state_variable,
        defense_video.acquired_bit,
    )
    pickup_examination_offset = disk_action.find(pickup_examination)
    pickup_choice_offset = disk_action.find(pickup_choice)
    inventory_award_offset = disk_action.find(inventory_award)
    pickup_receipt_offset = disk_action.find(pickup_receipt)
    persistence_write_offset = disk_action.find(persistence_write)
    if (
        defense_item.header[
            disk_record_offset : disk_record_offset + len(expected_disk_record)
        ]
        != expected_disk_record
        or disk_init
        != _facility_video_disk_init_body(defense_video, disk_init_pointer)
        or disk_action
        != _facility_video_disk_action_body(defense_video, disk_action_pointer)
        or persistence_write not in disk_action
        or disk_action.count(
            b"\x8B" + _immediate(defense_video.inventory_item_id)
        )
        != 2
        or inventory_award not in disk_action
        or b"\x74" + _immediate(FACILITY_VIDEO_ITEM_ACQUIRED_SOUND_ID)
        not in disk_action
        or b"\xFE\x53" not in disk_action
        or min(
            pickup_examination_offset,
            pickup_choice_offset,
            inventory_award_offset,
            pickup_receipt_offset,
            persistence_write_offset,
        )
        < 0
        or not (
            pickup_examination_offset
            < pickup_choice_offset
            < inventory_award_offset
            < pickup_receipt_offset
            < persistence_write_offset
        )
        or b"\x29\xFB" in disk_init
        or b"\x29\xFB" in disk_action
        or any(
            defense_editor.bytecode[
                defense_editor.get_script_pointer(
                    defense_video.disk_entity,
                    script_index,
                )
            ]
            != 0
            for script_index in range(32)
            if script_index not in (0, 1, 2)
        )
        or defense_editor.get_script_pointer(defense_video.disk_entity, 1)
        != missile_worker_pointers[MISSILE_REFRESH_WORKER_ENTITY]
    ):
        raise DungeonBuildError(
            "Defense Archive Video Disk lost its inventory/repeat contract"
        )

    screen_x, screen_y, screen_z = FACILITY_VIDEO_SCREEN_POSITION
    expected_screen_record = _field_actor_record(
        0x02B0,
        screen_x,
        screen_z,
        FACILITY_VIDEO_SCREEN_MODEL_INDEX,
        y=screen_y,
    )
    screen_record_offset = 0x190 + defense_video.screen_entity * 16
    screen_init_pointer = defense_editor.get_script_pointer(
        defense_video.screen_entity,
        0,
    )
    if (
        defense_video.screen_entity != FACILITY_VIDEO_SCREEN_ENTITY
        or defense_item.header[
            screen_record_offset : screen_record_offset + 16
        ]
        != expected_screen_record
        or _pointed_script_body(defense_editor, screen_init_pointer)
        != _facility_video_screen_init_body()
        or any(
            defense_editor.bytecode[
                defense_editor.get_script_pointer(
                    defense_video.screen_entity,
                    script_index,
                )
            ]
            != 0
            for script_index in range(2, 32)
        )
        or defense_editor.get_script_pointer(defense_video.screen_entity, 1)
        != missile_worker_pointers[MISSILE_CURSOR_WORKER_ENTITY]
    ):
        raise DungeonBuildError(
            "Defense Archive video plane lost its hidden native actor contract"
        )

    # Five lore-only source-378 clones expose both visible computers: the large
    # desk console owns official/government mail in block 1, while the hanging
    # overhead-arm terminal retains its personal staff thread in block 0. Both
    # are repeatable and neither may write progression or change fields. The
    # hanging controller uses the live triangle-16 operator pose, not v87's
    # unreachable prop-side anchor.
    expected_desk_init = _static_door_controller_init(
        45,
        -42,
        requires_facing=False,
        interaction_half_width=0x1E,
    )
    expected_hanging_init = _static_door_controller_init(
        -124,
        -25,
        requires_facing=False,
        interaction_half_width=0x08,
    )
    for field in (366, 369, 370, 371, 724):
        lore_editor = ScriptEditor(items[field].components[SCRIPT_INDEX])
        desk_init_pointer = lore_editor.get_script_pointer(13, 0)
        desk_action_pointer = lore_editor.get_script_pointer(13, 2)
        hanging_init_pointer = lore_editor.get_script_pointer(14, 0)
        hanging_action_pointer = lore_editor.get_script_pointer(14, 2)
        desk_action = _pointed_script_body(
            lore_editor,
            desk_action_pointer,
        )
        hanging_action = _pointed_script_body(
            lore_editor,
            hanging_action_pointer,
        )
        expected_desk_action = (
            _automatic_dialogue_body(
                (1,),
                routine_pc=desk_action_pointer,
            )
            + b"\x00"
        )
        expected_hanging_action = (
            _automatic_dialogue_body(
                (0,),
                routine_pc=hanging_action_pointer,
            )
            + b"\x00"
        )
        if (
            lore_editor.bytecode[
                desk_init_pointer : desk_init_pointer + len(expected_desk_init)
            ]
            != expected_desk_init
            or lore_editor.get_script_pointer(13, 1) != 0x02E5
            or lore_editor.get_script_pointer(13, 3) != 0x030E
            or desk_action != expected_desk_action
            or lore_editor.bytecode[
                hanging_init_pointer : hanging_init_pointer
                + len(expected_hanging_init)
            ]
            != expected_hanging_init
            or lore_editor.get_script_pointer(14, 1) != 0x0312
            or lore_editor.get_script_pointer(14, 3) != 0x0314
            or hanging_action != expected_hanging_action
        ):
            raise DungeonBuildError(
                f"Lore annex {field} lost its independent desk/hanging mail pair"
            )

    # Target 367 is now an unmodified retail source-377 architectural shell.
    # Its three genuine animated doors form the branch junction; exposition
    # and treasure live only on visible native objects in the two leaf rooms.
    branch_item = items[367]
    if (
        branch_item.header is None
        or _sha256(branch_item.header)
        != "f46e59eb359cca3d27da02b1c1919a2c4c1e846ed3562b38ebcbb803b8757f09"
        or _sha256(branch_item.components[MODEL_INDEX])
        != "c4435de49086ccfd68df20488c7e69204c2bbde27305d26af798c0512cb1d2b4"
        or _sha256(branch_item.components[ACTOR_INDEX])
        != "f84a626b32efd650069e635576ba51a420e4dfd2061f8323278737ef1761df5f"
        or _sha256(branch_item.components[SPRITE_INDEX])
        != "96902a4a530809dee1c9fb6eb01ec046205ff6a04ff81e445acac3ab3a4052e2"
    ):
        raise DungeonBuildError(
            "Archive branch junction no longer uses exact native source-377 assets"
        )

    # All five reserve magazines enter silently and reuse the same visible,
    # solid aisle-side field-373 Zeboim station. Entity 7 owns both its hidden
    # native contact actor and repeatable X dialogue; no forward-entry update
    # may survive.
    magazine_terminal_init = _solid_station_controller_init(
        ZEBOIM_STATION_VISUAL_CENTER[0],
        0,
        requires_facing=True,
        collision_operand=ZEBOIM_STATION_COLLISION_OPERAND,
    )
    expected_station_record = struct.pack(
        "<HhhhhhhH",
        ZEBOIM_STATION_NODE_FLAGS,
        0,
        ZEBOIM_STATION_Y_ROTATION,
        0,
        *ZEBOIM_STATION_PLACEMENT,
        ZEBOIM_STATION_TARGET_MODEL_INDEX,
    )
    for field in (377, 378, 379, 382, 383):
        magazine_item = items[field]
        magazine_editor = ScriptEditor(
            magazine_item.components[SCRIPT_INDEX]
        )
        stop = magazine_editor.get_script_pointer(20, 2)
        init_pointer = magazine_editor.get_script_pointer(7, 0)
        action_pointer = magazine_editor.get_script_pointer(7, 2)
        action = _pointed_script_body(magazine_editor, action_pointer)
        expected_action = (
            _automatic_dialogue_body((0,), routine_pc=action_pointer) + b"\x00"
        )
        station_models = _indexed_bundle_entries(
            magazine_item.components[MODEL_INDEX]
        )
        if (
            magazine_editor.bytecode[
                init_pointer : init_pointer + len(magazine_terminal_init)
            ]
            != magazine_terminal_init
            or magazine_editor.get_script_pointer(7, 1) != stop
            or {
                magazine_editor.get_script_pointer(7, index)
                for index in range(3, 32)
            }
            != {stop}
            or action != expected_action
            or magazine_item.header is None
            or _sha256(magazine_item.header)
            != ZEBOIM_STATION_FIELD_673_HEADER_SHA256
            or magazine_item.header[
                0x190 + ZEBOIM_STATION_TARGET_NODE_INDEX * 16 :
                0x190 + ZEBOIM_STATION_TARGET_NODE_INDEX * 16 + 16
            ]
            != expected_station_record
            or _sha256(magazine_item.components[MODEL_INDEX])
            != ZEBOIM_STATION_FIELD_673_MODELS_SHA256
            or _sha256(station_models[ZEBOIM_STATION_TARGET_MODEL_INDEX])
            != ZEBOIM_STATION_RELOCATED_MODEL_SHA256
            or magazine_item.graphics is None
            or _sha256(magazine_item.graphics)
            != ZEBOIM_STATION_FIELD_673_GRAPHICS_SHA256
        ):
            raise DungeonBuildError(
                f"Reserve Magazine field {field} lost its silent-entry Zeboim station"
            )

    annex = items[368]
    editor = ScriptEditor(annex.components[SCRIPT_INDEX])
    rail_write = _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT)
    rail_init_pointer = editor.get_script_pointer(13, 0)
    rail_action = _pointed_script_body(
        editor,
        editor.get_script_pointer(13, 2),
    )
    if (
        editor.bytecode[
            rail_init_pointer : rail_init_pointer + len(expected_desk_init)
        ]
        != expected_desk_init
        or tuple(editor.get_script_pointer(13, index) for index in (1, 3))
        != (0x02E5, 0x030E)
        or not rail_action.startswith(rail_write + bytes.fromhex("74 50 80"))
        or _dialog(0) not in rail_action
        or _dialog(1) in rail_action
    ):
        raise DungeonBuildError(
            "Archive Console D entity 13 lost its rail-only interaction"
        )

    mail_init_pointer = editor.get_script_pointer(14, 0)
    mail_action = _pointed_script_body(
        editor,
        editor.get_script_pointer(14, 2),
    )
    if (
        editor.bytecode[
            mail_init_pointer : mail_init_pointer + len(expected_hanging_init)
        ]
        != expected_hanging_init
        or editor.get_script_pointer(14, 1) != 0x0312
        or editor.get_script_pointer(14, 3) != 0x0314
        or _dialog(1) not in mail_action
        or rail_write in mail_action
    ):
        raise DungeonBuildError(
            "Archive Console D entity 14 lost its independent rear-mail "
            "interaction"
        )
    if editor.get_script_pointer(15, 1) != 0x03B5:
        raise DungeonBuildError(
            "Archive Console D's retired nanoreactor director is active"
        )

    if annex.header is None:
        raise DungeonBuildError(
            "Archive Console D requires its native static-model header"
        )
    models = annex.components[MODEL_INDEX]
    walkmesh = annex.components[1]
    if (
        len(annex.header) != 976
        or _sha256(annex.header)
        != "1745402e7ac9bc03566a0546e8bce08b1d4316af20082ae8b0083d26b69bd22f"
        or struct.unpack_from("<H", annex.header, 0x18C)[0] != 36
        or struct.unpack_from(
            "<HhhhhhhH",
            annex.header,
            0x190 + 24 * 16,
        )
        != (0x0010, 0, 0x0600, 0, 0, 0, 0, 3)
        or struct.unpack_from(
            "<HhhhhhhH",
            annex.header,
            0x190 + 25 * 16,
        )
        != (0x0010, 0, 0x0600, 0, 0, 0, 0, 4)
        or _sha256(models)
        != "b734fbc3155ba006227ff9f2c0540558a283574d3b1beea0f3f988cac749af87"
        or _sha256(_indexed_bundle_entries(models)[3])
        != "4295f313e5fd54f3cb496ea050bcb3f38234298d1e8522f0e5a673f081efab8b"
        or _sha256(_indexed_bundle_entries(models)[4])
        != "56625491e9d7d52225e3391cf6fe7cd905b6a59a2d54f80329b2a2403bfe8aed"
        or _sha256(walkmesh)
        != "5bae54017424c13437d0790f57e4b5be3eea2e3f6fd3952351a87b03bac12e6f"
        or struct.unpack_from("<hhhh", walkmesh, 0x150 + 7 * 8)
        != (41, -2, -35, 0)
        or struct.unpack_from("<hhhh", walkmesh, 0x150 + 19 * 8)
        != (-70, -3, 74, 0)
    ):
        raise DungeonBuildError(
            "Archive Console D's desk/hanging terminals or reachable walkmesh "
            "changed"
        )

    # Central Control keeps a repeatable, state-neutral Elly observation on
    # entity 12 at the visibly out-of-place keypad. Entity 13 is the
    # independent story console: its authorized activation presents the
    # Zeboim afterimage, then automatically admits Citan and launches the
    # capsule locally without a second X press.
    central_spec = _CLONE_BY_TARGET[728]
    if (
        len(central_spec.optional_interactions) != 1
        or central_spec.completion_interaction is None
    ):
        raise DungeonBuildError(
            "Central Control lost its distinct keypad remark and story "
            "interactions"
        )
    central_archive = central_spec.optional_interactions[0]
    central_completion = central_spec.completion_interaction
    _validate_central_control_terminal_walkmesh(
        items[728].components[1],
        central_archive,
        central_completion,
    )

    central = ScriptEditor(items[728].components[SCRIPT_INDEX])
    for interaction in (central_archive, central_completion):
        assert interaction.fixed_script_position is not None
        expected_init = _static_door_controller_init(
            *interaction.fixed_script_position,
            requires_facing=interaction.controller_requires_facing,
            interaction_half_width=(
                interaction.controller_interaction_half_width
            ),
            interaction_half_depth=(
                interaction.controller_interaction_half_depth
                if isinstance(interaction, CompletionInteraction)
                else None
            ),
        )
        init_pointer = central.get_script_pointer(interaction.entity, 0)
        if (
            _pointed_script_body(central, init_pointer) != expected_init
            or (
                interaction.entity == 12
                and (
                    init_pointer != CENTRAL_CONTROL_ARCHIVE_CONSOLE_INIT_PC
                    or _sha256(expected_init)
                    != CENTRAL_CONTROL_ARCHIVE_CONSOLE_INIT_SHA256
                    or expected_init[16:18] != b"\x01\x01"
                )
            )
            or central.bytecode[
                central.get_script_pointer(interaction.entity, 1)
            ]
            != 0
            or central.bytecode[
                central.get_script_pointer(interaction.entity, 3)
            ]
            != 0
        ):
            raise DungeonBuildError(
                f"Central Control terminal {interaction.entity} lost its "
                "local, X-only console frontage"
            )

    collider_pointers = tuple(
        central.get_script_pointer(
            CENTRAL_CONTROL_HANGING_TERMINAL_COLLIDER_ENTITY,
            script_index,
        )
        for script_index in range(32)
    )
    collider_pc = collider_pointers[0]
    collider_body = _pointed_script_body(central, collider_pc)
    expected_collider_body = _solid_station_controller_init(
        *CENTRAL_CONTROL_HANGING_TERMINAL_COLLIDER_POSITION,
        requires_facing=False,
        collision_operand=CENTRAL_CONTROL_HANGING_TERMINAL_COLLISION_OPERAND,
        interaction_enabled=False,
    )
    if (
        collider_pc != CENTRAL_CONTROL_HANGING_TERMINAL_COLLIDER_PC
        or collider_pointers[1:]
        != (CENTRAL_CONTROL_NATIVE_TREASURE_POINTERS[1],) * 31
        or collider_body != expected_collider_body
        or collider_body != CENTRAL_CONTROL_HANGING_TERMINAL_COLLIDER_BODY
        or _sha256(collider_body)
        != CENTRAL_CONTROL_HANGING_TERMINAL_COLLIDER_SHA256
        or collider_body[20:24]
        != bytes(
            (
                CENTRAL_CONTROL_HANGING_TERMINAL_COLLISION_OPERAND,
                CENTRAL_CONTROL_HANGING_TERMINAL_COLLISION_OPERAND,
                0x64,
                CENTRAL_CONTROL_HANGING_TERMINAL_COLLISION_OPERAND,
            )
        )
        or collider_body[-3:] != b"\x23\x2A\x00"
    ):
        raise DungeonBuildError(
            "Central Control entity 16 lost its hidden, immovable, "
            "noninteractive standing-keypad collider"
        )

    # The native east door remains a third, independent X zone. Its narrow
    # rectangular controller is disjoint from both remapped console regions.
    door_init = _pointed_script_body(
        central,
        central.get_script_pointer(14, 0),
    )
    if (
        len(door_init) < 24
        or door_init[:2] != b"\xBC\x19"
        or struct.unpack_from("<hh", door_init, 2) != (181, 88)
        or door_init[11:16] != bytes.fromhex("F8 03 04 00 18")
        or door_init[16:20] != bytes.fromhex("05 1E 64 00")
    ):
        raise DungeonBuildError(
            "Central Control east door lost its audited local X zone"
        )
    door_position = (181, 88)
    door_reach = (0x05 * 2 + 16, 0x1E * 2 + 16)
    for interaction in (central_archive, central_completion):
        assert interaction.fixed_script_position is not None
        width, depth = _interaction_bound_operands(
            interaction.controller_interaction_half_width,
            (
                interaction.controller_interaction_half_depth
                if isinstance(interaction, CompletionInteraction)
                else None
            ),
        )
        reach = (width * 2 + 16, depth * 2 + 16)
        if not (
            abs(interaction.fixed_script_position[0] - door_position[0])
            > reach[0] + door_reach[0]
            or abs(interaction.fixed_script_position[1] - door_position[1])
            > reach[1] + door_reach[1]
        ):
            raise DungeonBuildError(
                f"Central Control terminal {interaction.entity} overlaps the "
                "east door X zone"
            )

    central_remark_pointer = central.get_script_pointer(12, 2)
    central_remark_body = _pointed_script_body(central, central_remark_pointer)
    if central_remark_body != (
        _automatic_dialogue_body((1,), routine_pc=central_remark_pointer)
        + b"\x00"
    ) or _screen_dialogue_calls(central_remark_body) != ((1, 0),):
        raise DungeonBuildError(
            "Central Control entity 12 lost Elly's repeatable keypad remark"
        )
    central_story_pointer = central.get_script_pointer(13, 2)
    central_story = _pointed_script_body(central, central_story_pointer)
    historical = central_completion.historical_scene
    central_dialogue_calls = _screen_dialogue_calls(central_story)
    expected_central_dialogue_calls = tuple(
        (
            dialogue,
            CENTRAL_CONTROL_HIDDEN_DIRECTOR_DIALOGUE_FLAGS,
        )
        for dialogue in CENTRAL_CONTROL_FINALE_DIALOGUE_IDS
    )
    memory_shots = (
        (historical.reaction_camera, *historical.apparition_camera_shots)
        if historical is not None
        else ()
    )
    historical_scene_offset = -1
    expected_historical_scene = b""
    historical_auto_chain_prefix = b""
    historical_manual_arrival_prefix = b""
    historical_arrival_suffix = b""
    present_camera_signature = b""
    memory_transition_signature = b""
    memory_transition_sound = b""
    terminal_operation_camera = b""
    terminal_operation_call = b""
    terminal_operation_pc = -1
    terminal_operation_body = b""
    launch_dialogue_offsets: tuple[int, ...] = ()
    terminal_operation_offset = -1
    launch_worldmap_offset = -1
    native_terminal_assets_valid = False
    if historical is not None:
        first_present_dialogue = _dialog(
            historical.prelude_dialogue,
            dialogue_flags=central_completion.dialogue_flags,
        )
        first_dialogue_offset = central_story.find(first_present_dialogue)
        scene_prefix_size = (
            len(b"\x33\xFE\x54")
            + len(_wait_for_pad_release(PAD_MASK_CROSS, 0))
            + len(_wait())
        )
        historical_scene_offset = first_dialogue_offset - scene_prefix_size
        historical_scene_pc = central_story_pointer + historical_scene_offset
        if historical_scene_offset >= 0:
            expected_historical_scene = _historical_ghost_scene_body(
                historical,
                routine_pc=historical_scene_pc,
                dialogue_flags=central_completion.dialogue_flags,
            )
            if historical.final_party_arrival is not None:
                historical_arrival = historical.final_party_arrival
                historical_auto_chain_prefix = (
                    _set_var_bit(historical.variable, historical.seen_bit)
                    + _wait()
                    + _final_party_arrival_prepare_body(historical_arrival)
                    + _historical_camera_shot_body(
                        historical.arrival_camera,
                        enter_camera_mode=False,
                    )
                )
                historical_manual_arrival_prefix = (
                    _final_party_arrival_prepare_body(historical_arrival)
                    + _historical_camera_shot_body(
                        historical.arrival_camera,
                        enter_camera_mode=True,
                    )
                )
                historical_arrival_suffix = _final_party_arrival_suffix_body(
                    historical_arrival,
                    conversation_camera=historical.final_camera,
                )
                operation_script = (
                    historical_arrival.terminal_operation_script_index
                )
                if operation_script is not None:
                    terminal_operation_pc = central.get_script_pointer(
                        historical_arrival.entity,
                        operation_script,
                    )
                    terminal_operation_body = _pointed_script_body(
                        central,
                        terminal_operation_pc,
                    )
                    terminal_operation_camera = _historical_camera_shot_body(
                        historical.terminal_operation_camera,
                        enter_camera_mode=False,
                        allow_silent=True,
                    )
                    terminal_operation_call = b"\x09" + bytes(
                        (
                            historical_arrival.entity,
                            operation_script | 0x20,
                        )
                    )
                    launch_dialogue = (
                        _dialog(
                            historical.commit_dialogue,
                            dialogue_flags=central_completion.dialogue_flags,
                        )
                        + b"\x9C"
                    )
                    launch_dialogue_offsets = tuple(
                        index
                        for index in range(len(central_story))
                        if central_story.startswith(launch_dialogue, index)
                    )
                    operation_signature = (
                        terminal_operation_camera + terminal_operation_call
                    )
                    if central_story.count(operation_signature) == 1:
                        terminal_operation_offset = central_story.index(
                            operation_signature
                        )
                    launch_worldmap = _worldmap(
                        MASS_DRIVER_LAUNCH_SCENE_POSITION,
                        MASS_DRIVER_LAUNCH_SCENE_MODE,
                    )
                    if central_story.count(launch_worldmap) == 1:
                        launch_worldmap_offset = central_story.index(
                            launch_worldmap
                        )
        present_camera_signature = (
            b"\x60\x64"
            + _historical_camera_vector(0x63, historical.present_camera.target)
            + _historical_camera_vector(0xA3, historical.present_camera.eye)
        )
        memory_transition_sound = (
            b"\x74" + _immediate(historical.transition_sound_id)
        )
        memory_transition_signature = (
            _dialog(
                historical.vision_prelude_dialogues[-1],
                dialogue_flags=central_completion.dialogue_flags,
            )
            + b"\x9C"
            + memory_transition_sound
            + b"\xB4"
            + _immediate(historical.fade_frames)
        )
        central_header = items[728].header or b""
        central_models = items[728].components[MODEL_INDEX]
        central_graphics = items[728].graphics or b""
        central_model_entries = _indexed_bundle_entries(central_models)
        native_terminal_assets_valid = (
            len(central_header) == CENTRAL_CONTROL_HANGING_TERMINAL_HEADER_SIZE
            and _sha256(central_header)
            == CENTRAL_CONTROL_HANGING_TERMINAL_HEADER_SHA256
            and struct.unpack_from("<H", central_header, 0x18C)[0] == 44
            and len(central_models) == CENTRAL_CONTROL_MODELS_SIZE
            and _sha256(central_models) == CENTRAL_CONTROL_MODELS_SHA256
            and len(central_graphics) == CENTRAL_CONTROL_GRAPHICS_SIZE
            and _sha256(central_graphics) == CENTRAL_CONTROL_GRAPHICS_SHA256
            and len(central_model_entries) == 12
            and all(
                central_header[0x190 + node * 16 : 0x190 + (node + 1) * 16]
                == record
                for node, record in CENTRAL_CONTROL_CHAIR_FIXTURE_NODE_RECORDS.items()
            )
            and central_header[0x190 + 29 * 16 : 0x190 + 30 * 16]
            == CENTRAL_CONTROL_WALL_BANK_NODE_RECORD
            and central_header[
                0x190 + CENTRAL_CONTROL_HANGING_TERMINAL_NODE * 16 :
                0x190 + (CENTRAL_CONTROL_HANGING_TERMINAL_NODE + 1) * 16
            ]
            == CENTRAL_CONTROL_HANGING_TERMINAL_NODE_RECORD
            and all(
                _sha256(central_model_entries[index]) == expected_hash
                for index, expected_hash in (
                    CENTRAL_CONTROL_NATIVE_FIXTURE_MODEL_SHA256S.items()
                )
            )
            and len(
                central_model_entries[CENTRAL_CONTROL_HANGING_TERMINAL_MODEL]
            )
            == CENTRAL_CONTROL_HANGING_TERMINAL_MODEL_SIZE
            and _sha256(
                central_model_entries[CENTRAL_CONTROL_HANGING_TERMINAL_MODEL]
            )
            == CENTRAL_CONTROL_HANGING_TERMINAL_MODEL_SHA256
        )
    if (
        not central_completion.launch_scene
        or central_completion.handoff_field is not None
        or central_completion.dialogue_flags
        != CENTRAL_CONTROL_HIDDEN_DIRECTOR_DIALOGUE_FLAGS
        or historical is None
        or historical.final_party_arrival is None
        or historical.final_party_arrival.position
        != CENTRAL_CONTROL_HANGING_TERMINAL_STATION
        or historical.final_party_arrival.waypoints
        != (
            FinalPartyWaypoint(170, 89, 32),
            FinalPartyWaypoint(160, 110, 32),
            FinalPartyWaypoint(136, 131, 20),
        )
        or historical.final_party_arrival.preserve_terminal_facing
        or not historical.final_party_arrival.hold_camera_through_launch
        or historical.final_party_arrival.terminal_operation_script_index
        != CENTRAL_CONTROL_HANGING_TERMINAL_OPERATION_SCRIPT
        or historical.final_party_arrival.terminal_operation_body
        != CENTRAL_CONTROL_HANGING_TERMINAL_OPERATION_BODY
        or historical.arrival_camera
        != HistoricalCameraShot(
            target=(-13, 106, -32),
            eye=(-27, -767, -544),
            transition_frames=24,
            dialogues=(35,),
        )
        or historical.final_camera != historical.arrival_camera
        or historical.terminal_operation_camera
        != HistoricalCameraShot(
            target=(145, 160, -45),
            eye=(170, -80, -135),
            transition_frames=12,
            dialogues=(),
        )
        or historical.vision_prelude_dialogues != (21,)
        or historical.historical_dialogues != (*range(22, 32), 36)
        or historical.present_dialogues != (32,)
        or historical.transition_sound_id
        != CENTRAL_CONTROL_MEMORY_TRANSITION_SOUND_ID
        or historical.reaction_camera.dialogues
        or historical.present_camera.dialogues != (32,)
        or any(
            shot.eye != CENTRAL_CONTROL_HISTORICAL_MEMORY_EYE
            for shot in memory_shots
        )
        or len(memory_shots) != 12
        or central_story.count(first_present_dialogue) != 1
        or historical_scene_offset < 0
        or central_story[
            historical_scene_offset:
            historical_scene_offset + len(expected_historical_scene)
        ]
        != expected_historical_scene
        or central_story[
            historical_scene_offset + len(expected_historical_scene):
            historical_scene_offset
            + len(expected_historical_scene)
            + len(historical_auto_chain_prefix)
        ]
        != historical_auto_chain_prefix
        or not historical_auto_chain_prefix
        or central_story.count(historical_auto_chain_prefix) != 1
        or central_story.count(historical_manual_arrival_prefix) != 1
        or central_story.count(historical_arrival_suffix) != 1
        or historical_arrival_suffix.count(
            b"\xFE\x17"
            + bytes((historical.final_party_arrival.entity, 0xFF))
        )
        != 1
        or historical_arrival_suffix.count(
            b"\xFE\x17"
            + bytes((0xFF, historical.final_party_arrival.entity))
        )
        != 1
        or central_story.count(
            b"\xFE\x17"
            + bytes((historical.final_party_arrival.entity, 0xFF))
        )
        != 2
        or central_story.count(
            b"\xFE\x17"
            + bytes((0xFF, historical.final_party_arrival.entity))
        )
        != 2
        or terminal_operation_pc != CENTRAL_CONTROL_FINAL_PARTY_OPERATION_PC
        or terminal_operation_body
        != CENTRAL_CONTROL_HANGING_TERMINAL_OPERATION_BODY
        or _sha256(terminal_operation_body)
        != CENTRAL_CONTROL_FINAL_PARTY_OPERATION_SHA256
        or not terminal_operation_camera
        or terminal_operation_camera
        != CENTRAL_CONTROL_TERMINAL_OPERATION_CAMERA_BODY
        or _sha256(terminal_operation_camera)
        != CENTRAL_CONTROL_TERMINAL_OPERATION_CAMERA_SHA256
        or central_story.count(
            terminal_operation_camera + terminal_operation_call
        )
        != 1
        or terminal_operation_offset
        > central_story.index(
            _set_var_bit(INTERLOCK_VARIABLE, LAUNCH_COMPLETED_BIT)
        )
        or len(launch_dialogue_offsets) != 2
        or terminal_operation_offset
        != launch_dialogue_offsets[1]
        + len(
            _dialog(
                historical.commit_dialogue,
                dialogue_flags=central_completion.dialogue_flags,
            )
            + b"\x9C"
        )
        or central_story[
            launch_dialogue_offsets[0]
            + len(
                _dialog(
                    historical.commit_dialogue,
                    dialogue_flags=central_completion.dialogue_flags,
                )
                + b"\x9C"
            ) :
            launch_dialogue_offsets[0]
            + len(
                _dialog(
                    historical.commit_dialogue,
                    dialogue_flags=central_completion.dialogue_flags,
                )
                + b"\x9C"
            )
            + 3
        ]
        != _jump(central_story_pointer + terminal_operation_offset)
        or any(
            b"\xFE\x53"
            in central_story[dialogue_offset:launch_worldmap_offset]
            for dialogue_offset in launch_dialogue_offsets
        )
        or _historical_camera_release_body() in central_story
        or not native_terminal_assets_valid
        or expected_historical_scene.count(present_camera_signature) != 1
        or expected_historical_scene.count(memory_transition_sound) != 1
        or memory_transition_signature not in expected_historical_scene
        or _change_field(388, 1) in central_story
        or _worldmap(
            MASS_DRIVER_LAUNCH_SCENE_POSITION,
            MASS_DRIVER_LAUNCH_SCENE_MODE,
        )
        not in central_story
        or _set_var_bit(INTERLOCK_VARIABLE, LAUNCH_COMPLETED_BIT)
        not in central_story
        or _set_var_bit(INTERLOCK_VARIABLE, CITAN_FINAL_ARRIVAL_BIT)
        not in central_story
        or _set_var_bit(INTERLOCK_VARIABLE, HISTORICAL_GHOST_SEEN_BIT)
        not in central_story
        or central_dialogue_calls != expected_central_dialogue_calls
        or any(flags == 0 for _dialogue, flags in central_dialogue_calls)
        or any(
            _dialog(dialogue, dialogue_flags=0) in central_story
            for dialogue in set(CENTRAL_CONTROL_FINALE_DIALOGUE_IDS)
        )
        or any(
            opcode not in central_story
            for opcode in (b"\xFE\x18", b"\xFE\x1A")
        )
    ):
        raise DungeonBuildError(
            "Central Control story console lost its local apparition, Citan "
            "arrival, capsule launch, or world-map cinematic path"
        )


def verify_scene_continuity(
    prepared: Sequence[PreparedReplacement],
) -> None:
    """Prove every directed link lands at its own inward-facing entry."""

    items = {
        item.target_field: item
        for item in prepared
        if item.target_field is not None
    }
    if set(items) != set(ROUTE):
        raise DungeonBuildError(
            "Scene-continuity verification requires every route field"
        )

    final_completion = _CLONE_BY_TARGET[728].completion_interaction
    historical = (
        final_completion.historical_scene
        if final_completion is not None
        else None
    )
    if (
        final_completion is None
        or historical is None
        or historical.final_party_arrival is None
    ):
        raise DungeonBuildError(
            "Central Control scene continuity requires Citan's final arrival"
        )
    _validate_final_party_arrival_walkmesh(
        items[728].components[1],
        historical.final_party_arrival,
    )

    # The west subway threshold uses a deliberately broad automatic volume so
    # it cannot be missed when leaving field 721. Prove that the reciprocal
    # field-363 arrival is not inside that same volume (the v92 coordinates
    # were, which caused an immediate 721 -> 363 bounce on return).
    subway_editor = ScriptEditor(items[721].components[SCRIPT_INDEX])
    subway_exit_init = _pointed_script_body(
        subway_editor,
        subway_editor.get_script_pointer(13, 0),
    )
    if (
        len(subway_exit_init) < 20
        or subway_exit_init[:2] != b"\xBC\x19"
        or subway_exit_init[15] != 0x18
    ):
        raise DungeonBuildError(
            "Subway exit controller lost its audited position/bound initializer"
        )
    exit_x, exit_z = struct.unpack_from("<hh", subway_exit_init, 2)
    runtime_x_reach = subway_exit_init[16] * 2 + 16
    runtime_z_reach = subway_exit_init[17] * 2 + 16
    subway_return = _read_field_entry(
        items[721].components[SCRIPT_INDEX],
        1,
    )
    x_clearance = abs(subway_return.x - exit_x) - runtime_x_reach
    inside_z = abs(subway_return.z - exit_z) <= runtime_z_reach
    if inside_z and x_clearance < 0x20:
        raise DungeonBuildError(
            "Field 363->721/1 return does not clear the subway exit trigger: "
            f"x clearance {x_clearance}, expected at least 32"
        )

    doors = {
        (contract.field, contract.entity): contract
        for contract in (*VISIBLE_DOOR_CONTRACTS, *PREOPENED_DOOR_CONTRACTS)
    }
    passages = {
        (contract.field, contract.entity): contract
        for contract in OPEN_PASSAGE_CONTRACTS
    }
    mechanical_links = 0
    open_links = 0

    for contract in ARRIVAL_CONTINUITY_CONTRACTS:
        item = items.get(contract.destination_field)
        if item is None:
            raise DungeonBuildError(
                f"Arrival destination {contract.destination_field} is not prepared"
            )
        script = item.components[SCRIPT_INDEX]
        actual = _read_field_entry(script, contract.destination_parameter)
        expected = FieldEntryAddition(
            contract.expected_entry.x,
            contract.expected_entry.z,
            contract.expected_entry.walkmesh,
            contract.resolved_camera_direction,
            contract.inward_direction,
        )
        if actual != expected:
            raise DungeonBuildError(
                f"Arrival {contract.source_field}->{contract.destination_field}/"
                f"{contract.destination_parameter} found {actual}, "
                f"expected {expected}"
            )
        if (
            actual.camera_direction == 0xFF
            or actual.actor_direction == 0xFF
        ):
            raise DungeonBuildError(
                f"Arrival {contract.source_field}->{contract.destination_field}/"
                f"{contract.destination_parameter} does not use explicit "
                "camera and actor directions"
            )

        if contract.source_field is None:
            continue
        source_item = items[contract.source_field]
        source_bytecode = ParsedAtelScript(
            source_item.components[SCRIPT_INDEX]
        ).bytecode
        fixed = _change_field(
            contract.destination_field,
            contract.destination_parameter,
        )
        custom_prefix = (
            b"\x12"
            + _immediate(contract.destination_field)
            + _immediate(contract.destination_parameter)
        )
        if fixed not in source_bytecode and custom_prefix not in source_bytecode:
            raise DungeonBuildError(
                f"Scene link {contract.source_field}->"
                f"{contract.destination_field}/"
                f"{contract.destination_parameter} is not present in the "
                "prepared source script"
            )

        outgoing_doors = tuple(
            door
            for door in (*VISIBLE_DOOR_CONTRACTS, *PREOPENED_DOOR_CONTRACTS)
            if (
                door.field == contract.source_field
                and door.destination_field == contract.destination_field
            )
        )
        outgoing_passages = tuple(
            passage
            for passage in OPEN_PASSAGE_CONTRACTS
            if (
                passage.field == contract.source_field
                and passage.destination_field == contract.destination_field
            )
        )
        if outgoing_doors and outgoing_passages:
            raise DungeonBuildError(
                f"Scene link {contract.source_field}->"
                f"{contract.destination_field} is both a door and passage"
            )

        if outgoing_doors:
            if len(outgoing_doors) != 1:
                raise DungeonBuildError(
                    f"Scene link {contract.source_field}->"
                    f"{contract.destination_field} has multiple door controls"
                )
            outgoing = outgoing_doors[0]
            if outgoing.destination_parameter != contract.destination_parameter:
                raise DungeonBuildError(
                    f"Door {outgoing.field}:e{outgoing.entity} uses parameter "
                    f"{outgoing.destination_parameter}, expected "
                    f"{contract.destination_parameter}"
                )
            if outgoing.reciprocal_field is None:
                if outgoing.reciprocal_entity is not None:
                    raise DungeonBuildError(
                        f"One-way door {outgoing.field}:e{outgoing.entity} has "
                        "an invalid reciprocal declaration"
                    )
                mechanical_links += 1
                continue
            reciprocal_key = (
                outgoing.reciprocal_field,
                outgoing.reciprocal_entity,
            )
            receiving_door = doors.get(reciprocal_key)
            receiving_passage = passages.get(reciprocal_key)
            if (
                (receiving_door is None) == (receiving_passage is None)
            ):
                raise DungeonBuildError(
                    f"Door link {contract.source_field}->"
                    f"{contract.destination_field} has no single receiving "
                    "threshold"
                )
            receiving = (
                receiving_door
                if receiving_door is not None
                else receiving_passage
            )
            assert receiving is not None
            if (
                receiving.field != contract.destination_field
                or receiving.destination_field != contract.source_field
            ):
                raise DungeonBuildError(
                    f"Door link {contract.source_field}->"
                    f"{contract.destination_field} is not reciprocal"
                )
            # A receiving mechanical door has a finite, exact party waypoint
            # from which its inward octant can be inferred.  An open
            # staircase/threshold has no such scripted waypoint; its explicit
            # entry record and reciprocal declaration are the geometry
            # contract instead.
            if receiving_door is not None:
                receiving_item = items[contract.destination_field]
                editor = ScriptEditor(
                    receiving_item.components[SCRIPT_INDEX]
                )
                action = editor.get_script_pointer(
                    receiving_door.entity,
                    2,
                )
                waypoint_x, waypoint_z = _player_waypoint(
                    editor,
                    _pointed_script_body(editor, action),
                    receiving_door.destination_field,
                    receiving_door.destination_parameter,
                )
                inferred = _nearest_direction(
                    actual.x - waypoint_x,
                    actual.z - waypoint_z,
                )
                if inferred != contract.inward_direction:
                    raise DungeonBuildError(
                        f"Arrival {contract.source_field}->"
                        f"{contract.destination_field}/"
                        f"{contract.destination_parameter} faces direction "
                        f"{contract.inward_direction}, but receiving door "
                        f"{receiving_door.entity} geometry requires {inferred}"
                    )
            mechanical_links += 1
        elif outgoing_passages:
            if len(outgoing_passages) != 1:
                raise DungeonBuildError(
                    f"Scene link {contract.source_field}->"
                    f"{contract.destination_field} has multiple open passages"
                )
            passage = outgoing_passages[0]
            reciprocal_key = (
                passage.reciprocal_field,
                passage.reciprocal_entity,
            )
            receiving_passage = passages.get(reciprocal_key)
            receiving_door = doors.get(reciprocal_key)
            if (
                (receiving_passage is None)
                == (receiving_door is None)
            ):
                raise DungeonBuildError(
                    f"Open link {contract.source_field}->"
                    f"{contract.destination_field} has no single receiving "
                    "threshold"
                )
            receiving = (
                receiving_passage
                if receiving_passage is not None
                else receiving_door
            )
            assert receiving is not None
            if (
                passage.destination_parameter != contract.destination_parameter
                or receiving.field != contract.destination_field
                or receiving.destination_field != contract.source_field
            ):
                raise DungeonBuildError(
                    f"Open link {contract.source_field}->"
                    f"{contract.destination_field} does not land at its "
                    "reciprocal entry"
                )
            open_links += 1

    expected_mechanical = sum(
        contract.destination_field is not None
        for contract in (*VISIBLE_DOOR_CONTRACTS, *PREOPENED_DOOR_CONTRACTS)
    )
    if mechanical_links != expected_mechanical:
        raise DungeonBuildError(
            f"Scene continuity covered {mechanical_links} mechanical links, "
            f"expected {expected_mechanical}"
        )
    if open_links != len(OPEN_PASSAGE_CONTRACTS):
        raise DungeonBuildError(
            f"Scene continuity covered {open_links} open links, "
            f"expected {len(OPEN_PASSAGE_CONTRACTS)}"
        )


def verify_route_transitions(prepared: Sequence[PreparedReplacement]) -> None:
    """Require the complete dungeon graph and a clean world-map terminus."""

    edges = validate_route()
    successors: dict[int, set[int]] = {field: set() for field in ROUTE}
    for source, destination in edges:
        successors[source].add(destination)
    route_items = tuple(
        item for item in prepared if item.target_field is not None
    )
    targets = tuple(item.target_field for item in route_items)
    duplicates = sorted(
        {target for target in targets if targets.count(target) > 1}
    )
    if duplicates:
        raise DungeonBuildError(
            f"Prepared route contains duplicate target field(s): {duplicates}"
        )

    missing = sorted(set(ROUTE) - set(targets))
    unexpected = sorted(set(targets) - set(ROUTE))
    if targets != ROUTE:
        details: list[str] = []
        if missing:
            details.append(f"missing {missing}")
        if unexpected:
            details.append(f"unexpected {unexpected}")
        if not missing and not unexpected:
            details.append(f"wrong order {list(targets)}")
        raise DungeonBuildError(
            "Prepared target fields do not exactly match ROUTE: "
            + "; ".join(details)
        )

    for source_field, item in zip(ROUTE, route_items, strict=True):
        parsed = ParsedAtelScript(item.components[SCRIPT_INDEX])
        spec = _CLONE_BY_TARGET[source_field]
        raw_transitions = tuple(
            transition
            for transition in scan_raw_transitions(parsed)
            # Values over the retail field range are variable-form operands
            # that only resemble fixed immediates in a raw scan.
            if transition.field <= 999
        )
        reload_contracts = {
            contract
            for contract in SAME_FIELD_RELOAD_CONTRACTS
            if contract[0] == source_field
        }
        reload_transitions = tuple(
            transition
            for transition in raw_transitions
            if transition.field == source_field
        )
        unexpected_reloads = tuple(
            transition
            for transition in reload_transitions
            if (source_field, transition.parameter) not in reload_contracts
        )
        if unexpected_reloads:
            transition = unexpected_reloads[0]
            raise DungeonBuildError(
                f"Field {source_field} retains undeclared same-field reload "
                f"at PC 0x{transition.pc:04X}, parameter "
                f"{transition.parameter}"
            )
        for contract in reload_contracts:
            expected_count = SAME_FIELD_RELOAD_COUNTS[contract]
            actual_count = sum(
                transition.parameter == contract[1]
                for transition in reload_transitions
            )
            if actual_count != expected_count:
                raise DungeonBuildError(
                    f"Field {source_field} has {actual_count} same-field "
                    f"reload(s) to parameter {contract[1]}, expected "
                    f"{expected_count}"
                )
        # Same-field rebuilds are audited state transitions, not physical
        # dungeon links.  Exclude them from graph/arrival successor checks.
        transitions = tuple(
            transition
            for transition in raw_transitions
            if transition.field != source_field
        )
        custom_destinations: set[int] = set()
        for edit in spec.preserved_custom_transitions:
            expected = _custom_field_transition(
                edit.new_field,
                edit.new_parameter,
                edit.old_mode,
                edit.old_fade,
            )
            actual = parsed.bytecode[edit.pc : edit.pc + len(expected)]
            if actual != expected:
                raise DungeonBuildError(
                    f"Field {source_field} cinematic transition at "
                    f"PC 0x{edit.pc:04X} was not preserved"
                )
            custom_destinations.add(edit.new_field)
        if source_field == BOOTSTRAP_FIELD:
            worldmap_routine = _worldmap(21, 1) + b"\x5B"
            if worldmap_routine not in parsed.bytecode:
                raise DungeonBuildError(
                    f"Bootstrap field {source_field} has no checked world-map "
                    "return routine"
                )

        expected_successors = successors[source_field]
        for transition in transitions:
            if transition.field not in expected_successors:
                raise DungeonBuildError(
                    f"Field {source_field} retains off-route transition at "
                    f"PC 0x{transition.pc:04X}: {transition.field}"
                )
        off_route_custom = sorted(custom_destinations - expected_successors)
        if off_route_custom:
            raise DungeonBuildError(
                f"Field {source_field} retains off-route cinematic "
                f"destination(s) {off_route_custom}"
            )
        actual_successors = {
            transition.field for transition in transitions
        } | custom_destinations
        missing_successors = sorted(expected_successors - actual_successors)
        if missing_successors:
            raise DungeonBuildError(
                f"Field {source_field} has no fixed transition to expected "
                f"successor(s) {missing_successors}"
            )


def build_dungeon(
    input_root: Path | str,
    dialogue_root: Path | str,
    output_root: Path | str,
    *,
    force: bool = False,
) -> tuple[PreparedReplacement, tuple[tuple[int, Path], ...]]:
    output = Path(output_root).resolve()
    _output_available(output, force)
    prepared = prepare_all(input_root, dialogue_root)
    verify_route_transitions(prepared)
    verify_visible_door_contracts(prepared)
    verify_save_point_visual_contracts(prepared)
    verify_control_and_archive_terminal_roles(prepared)
    verify_scene_continuity(prepared)
    emitted = materialize(prepared, output, force=force)
    return prepared, emitted


def build_parser() -> argparse.ArgumentParser:
    project = Path(__file__).resolve().parents[2]
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input-root", type=Path, default=project / "work")
    parser.add_argument(
        "--dialogue-root", type=Path, default=project / "modules" / "mass_driver" / "content"
    )
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--force", action="store_true")
    parser.add_argument("--build-disc", action="store_true")
    parser.add_argument("--xenoiso", type=Path)
    parser.add_argument("--source-disc", type=Path)
    parser.add_argument("--disc-output", type=Path)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.build_disc and not all((args.xenoiso, args.source_disc, args.disc_output)):
        parser.error("--build-disc requires --xenoiso, --source-disc, and --disc-output")
    if not args.build_disc and any((args.xenoiso, args.source_disc, args.disc_output)):
        parser.error("Disc arguments require --build-disc")
    try:
        prepared, replacements = build_dungeon(
            args.input_root,
            args.dialogue_root,
            args.output,
            force=args.force,
        )
        print(
            f"Prepared {len(CLONES)} standalone dungeon fields, the playable "
            "world-map data, the X-enabled field overlay, and the native title "
            "menu GameState, plus isolated expanded Repair Bot shop catalogs and "
            "retail Vierge for Elly throughout the Mass Driver route, with "
            "Video Disk-only system-data edits, 78 validated normal combat "
            "resources replacing Perfect Works Story Mode, and one additional "
            "isolated Guardian model resource. The reconstructed El-Regulus "
            "resource set remains available through the separate archive "
            "entry point and is not installed in this build"
        )
        for canonical_id, path in replacements:
            print(f"  canonical {canonical_id}: {path}")
        print(f"Wrote {Path(args.output).resolve() / 'manifest.json'}")
        if args.build_disc:
            # The stats override is curated above; the native models stay on
            # the selected base disc and must be verified before publishing.
            stats = next(item.bundle for item in prepared if item.bundle_id == 2630)
            image = Mode2Image(args.source_disc)
            entry = next(
                entry for entry in image.read_index()
                if entry.canonical_disc2_index == 2631
            )
            models = image.extract_entry(entry)
            validate_enemy_resource_pair(stats, models)
            command = xenoiso_wrapper_command(
                args.xenoiso,
                args.source_disc,
                args.disc_output,
                replacements,
                force=args.force,
            )
            result = subprocess.run(command, check=False)
            if result.returncode:
                raise DungeonBuildError(
                    f"Xenoiso wrapper exited with code {result.returncode}"
                )
            boot = verify_retail_title_boot(args.disc_output)
            print(
                f"Verified native publisher/title boot at raw LBA {boot.lba}: "
                f"{boot.sha256}"
            )
        return 0
    except (
        DialogueFormatError,
        DungeonBuildError,
        EncounterFormatError,
        FieldFormatError,
        GuardianResourceError,
        OSError,
        Mode2PatchError,
        ScriptFormatError,
        WorldmapFormatError,
        ZeboimMissileModelError,
    ) as exc:
        parser.error(str(exc))
    return 2


if __name__ == "__main__":
    sys.exit(main())
